const adoption = atom({ plugin: 'issue-board', key: 'adoption' } as const, { adopted: null, declined: [] })
// `/issues statuses` while it shows, and the guessed Status mappings the person answered, as the store last said.
const statusPicks = atom({ plugin: 'issue-board', key: 'statusPicks' } as const, null)
const guessSeen = atom({ plugin: 'issue-board', key: 'guessSeen' } as const, [])
// The plan Claude proposed, shown as a card in the pane until it is applied or discarded.
const proposal = atom({ plugin: 'issue-board', key: 'plan' } as const, null)
// The Bugs and Later markers the person chose, as the store last said, and `/issues labels` while it shows.
const chosenMarkers = atom({ plugin: 'issue-board', key: 'markers' } as const, {})
const markerPicks = atom({ plugin: 'issue-board', key: 'markerPicks' } as const, null)

// The bug and later labels the board goes by: the person's choice, else the repo's own names, else `bug` and `future`.
const markersNow = async ($: EngineInterface, now: Board | null | undefined): Promise<Markers> => markersOf(now, await read($, chosenMarkers))

// Whether a tool's calls may be allowed without asking: an organization can set a ceiling, the most permissive verdict
// a call of the tool may reach. None set, they may.
const mayAllow = (ceiling: 'allow' | 'ask' | 'deny' | undefined): boolean => ceiling === undefined || ceiling === 'allow'

// The pane's tabs as it offers them: the project's views with filters, then Inbox, All and Closed; or else the built-in
// filters.
const filtersFor = (project: Project | null | undefined): Tab[] => tabsOf(project)

const GROUPINGS: { id: GroupBy; label: string }[] = [
  { id: 'status', label: 'Status' },
  { id: 'epic', label: 'Epic' },
  { id: 'area', label: 'Area' },
]

// What the board has cost this session, for /issues stats. In memory only: a reload starts the counts over.
const stats = newStats(Date.now())

// Why the board is calling GitHub right now: the newest of the causes under way, or other. A cause is set around a poll,
// a full read, setup and the board's tools, not passed down to each call. Work that overlaps may take the other's
// cause, which is close enough for a count.
const causes: { cause: Cause }[] = []
const causeNow = (): Cause => causes.at(-1)?.cause ?? 'other'
const within = async <T,>(cause: Cause, work: () => Promise<T>): Promise<T> => {
  const token = { cause }
  causes.push(token)
  try {
    return await work()
  } finally {
    causes.splice(causes.indexOf(token), 1)
  }
}

// The cause a call counts under: one that changes GitHub is a write, unless a tool or setup made it.
const causeOf = (args: readonly string[], stdin?: string): Cause => {
  const now = causeNow()
  return now !== 'tool' && now !== 'setup' && (isMutation(args, stdin) || writesGitHub(['gh', ...args].join(' '))) ? 'write' : now
}

// Counts one gh call as it goes out.
const countGh = (args: readonly string[], stdin?: string): void => countCall(stats, causeOf(args, stdin), kindOf(args))

// Counts text the board adds to Claude's context.
const countText = (source: ContextSource, text: string): void => countContext(stats, source, text.length)

const runGh = async ($: EngineInterface, args: string[], stdin?: string, timeoutMs = 60_000): Promise<string> => {
  countGh(args, stdin)
  const { exitCode, stdout, stderr } = await $.process.run(['gh', ...args], { timeoutMs, ...(stdin === undefined ? {} : { stdin }) })
  if (exitCode !== 0) throw new Error(stderr.trim().split('\n')[0] || `gh ${args[0]} exited ${exitCode}`)
  return stdout
}

// Every gh call but a project write. A GraphQL mutation is refused here, so one written without projectWrite fails
// loudly instead of reaching a project nobody let the board change.
const gh = async ($: EngineInterface, args: string[], stdin?: string, timeoutMs = 60_000): Promise<string> => {
  if (isMutation(args, stdin)) throw new Error('the issue board sends GraphQL mutations only through its project write check')
  return runGh($, args, stdin, timeoutMs)
}

const messageOf = (cause: unknown): string => (cause instanceof Error ? cause.message : String(cause))

// The time on the engine's clock, which a test can move; the system's where there is none.
const nowOf = ($: EngineInterface): Promise<number> => $.clock.now().catch(() => Date.now())

// Why a hook failed, as its `.catch` handler reads it.
const failureOf = (error: HookFailure): string => (error.kind === 'timeout' ? `ran out of time${error.message ? ` (${error.message})` : ''}` : (error.message ?? 'threw'))

// What a hook that failed falls back to: the site's own behavior, as though the board had no hook there, with why it
// failed in the debug log. In a `.catch` handler `next(e)` replays what the hook's own call settled to, so nothing
// beneath runs twice. A guard falls back the same way: a fault in the board never refuses what Claude Code would let
// run. The engine reads each handler from a function literal, so each `.catch` is one that calls this.
const fallBack = <E, R>($: EngineInterface, e: E, next: ((e: E) => R) & Caught, site: string): R => {
  $.ui.log(`issue-board: ${site} failed and was left to the default: ${failureOf(next.error)}`, { to: 'debug' })
  return next(e)
}

// What one of the board's own tools answers when its hook fails: there is nothing beneath to fall back to, so Claude
// reads why.
const toolFailed = ($: EngineInterface, next: Caught, tool: string) => {
  $.ui.log(`issue-board: the ${tool} tool failed: ${failureOf(next.error)}`, { to: 'debug' })
  return { deny: `The issue board's ${tool} tool failed: ${failureOf(next.error)}` }
}

// How each of the board's tools that changes something acts: ask, then act. A hook that answers a tool call itself
// skips the engine's permission check, which only runs beneath it, so this calls next(e) first. That runs the check,
// with the board's own tool.check verdicts, and the prompt where they leave the call at ask. Only when the call got
// through does the engine go on to find that no hook answered, and only then does `act` run. Anything else, a no
// included, is passed back as it came, and nothing changes on GitHub.
const askThenAct = async <E, R>(e: E, next: (e: E) => Promise<ToolCallResult>, act: () => Promise<R>): Promise<R | ToolCallResult> => {
  const asked = await next(e)
  return approvedOf(asked) ? act() : asked
}

// One of the board's tools at work: its gh calls count under tool, and its answer as context Claude reads.
const asTool = async <R,>(tool: string, work: () => Promise<R>): Promise<R> => {
  // Claude called the tool, so its definition is in context now, if ToolSearch hadn't loaded it already.
  loadTool(stats, tool)
  const answer = await within('tool', work)
  countText('tool results', answerText(answer))
  return answer
}

// The text Claude reads of a tool's answer: what it says, or why it was refused.
const answerText = (answer: unknown): string => {
  const { result, deny } = (answer ?? {}) as { result?: unknown; deny?: unknown }
  if (typeof deny === 'string') return deny
  if (typeof result === 'string') return result
  return result === undefined ? '' : JSON.stringify(result)
}

// What project_adopt's permission check answers when it fails. Falling back to the verdict beneath could let an allow
// rule adopt a project without a prompt, so it refuses, and says why.
const adoptCheckFailed = ($: EngineInterface, next: Caught) => {
  $.ui.log(`issue-board: the project_adopt permission check failed: ${failureOf(next.error)}`, { to: 'debug' })
  return { decision: 'deny' as const, reason: `The issue board couldn't check the project_adopt call: ${failureOf(next.error)}` }
}

// How a command that couldn't start says so, as against one that ran too long.
const MISSING = /ENOENT|not found|no such file/i
// A gh error that may come from a missing permission rather than from the request itself.
const ACCESS_ERROR = /scope|credentials|not accessible|gh auth login|HTTP 40[13]|permission/i

// What one of the board's write tools answers when its work fails: why, and when the error may come from a missing
// permission, what the access check then finds missing.
const deniedBy = async ($: EngineInterface, what: string, cause: unknown): Promise<{ deny: string }> => {
  const message = messageOf(cause)
  const problems = ACCESS_ERROR.test(message) ? await checkAccess($, message) : []
  return { deny: `${what}: ${message}${problems.length > 0 ? `\n${problemsText(problems)}` : ''}` }
}

// What a press that failed shows: a toast saying why, and the access check run when the error may come from a missing
// permission, so the pane says what to fix.
const toastFailure = ($: EngineInterface, what: string, cause: unknown): void => {
  const message = messageOf(cause)
  $.ui.toast(`${what}: ${message}`)
  if (ACCESS_ERROR.test(message)) void checkAccess($, message)
}

// Asks gh who it is signed in as and what it may do in this repository, and keeps what is missing. `message` is an
// error gh just gave, which may name a permission the token lacks. One at a time, so a check asked for during another
// runs after it with its own message.
let checking: Promise<unknown> = Promise.resolve()
const checkAccess = ($: EngineInterface, message?: string): Promise<Problem[]> => {
  const run = checking.then(async () => {
    let installed = true
    // The check runs after whatever asked for it, so it takes no cause from what else is under way.
    const ask = (args: string[]) => {
      countCall(stats, 'other', kindOf(args))
      return $.process.run(['gh', ...args], { timeoutMs: 30_000 }).catch((cause: unknown) => {
        if (MISSING.test(messageOf(cause))) installed = false
        return null
      })
    }
    const [status, view] = await Promise.all([
      ask(['auth', 'status', '--active', '--json', 'hosts']),
      ask(['repo', 'view', '--json', 'nameWithOwner,hasIssuesEnabled,viewerPermission,isArchived,visibility']),
    ])
    const auth = status?.exitCode === 0 ? authOf(status.stdout) : null
    const repo = view?.exitCode === 0 ? repoOf(view.stdout) : null
    // A folder whose repository isn't on GitHub has nothing for the board to show, so nothing is missing there.
    const onGitHub = repo !== null || /github/i.test((await $.session.repo().catch(() => null))?.remote ?? '')
    // The last project refusal counts until Check again clears it, so its fix stays shown while the board reads labels.
    const said = [message, projectRefusal].filter(Boolean).join('\n')
    const problems = onGitHub ? problemsOf({ installed, auth, repo, ...(said ? { message: said } : {}) }) : []
    // The project's "Item closed" workflow marks every closed issue Done, which the board does only for completed ones.
    // A limit, not a blocker: it can be waved off. It only counts when the board moves closed issues to Done itself:
    // with autoMove off, or a project it may not write to, turning the workflow off would leave Done empty.
    const project = (await read($, board))?.project
    if (project?.closesToDone && settings.autoMove && (await mayWrite($, project))) {
      problems.push({
        id: 'item-closed',
        title: `${project.title}'s Item closed workflow is on`,
        detail: 'It marks every closed issue Done, even one closed as not planned or as a duplicate, so Done stops meaning shipped.',
        fix: 'Turn it off in the project\'s Workflows settings: the board moves issues closed as completed to Done by itself.',
        url: `${project.url}/workflows`,
        blocks: false,
      })
    }
    const login = auth?.state === 'signed-in' && auth.login ? auth.login : null
    await update($, access, () => ({ login, repo: repo?.name ?? null, permission: repo?.permission ?? null, problems, checkedAt: Date.now() }))
    if (login && (await read($, viewer)) === null) await update($, viewer, () => login)
    return problems
  })
  checking = run.catch(() => undefined)
  return run
}

// How the dismissed list names a problem waved off from the band.
const accessKey = (problem: Problem): string => `access-${problem.id}`

// The branch the session's folder has checked out; null on a detached head or outside git.
const currentBranch = async ($: EngineInterface): Promise<string | null> => {
  try {
    const { exitCode, stdout } = await $.process.run(['git', 'branch', '--show-current'])
    return exitCode === 0 ? stdout.trim() || null : null
  } catch {
    return null
  }
}

// The /config row for Claude Code's own PR footer ("Show PR status footer"), as `$.config.list()` names it.
const PR_FOOTER = 'prStatus'

// The branch whose pull request Claude Code's footer shows at the start of the hint row: the checked-out one, while
// the footer's row is on. null when it is off or can't be read, so the hint's tail lists every pull request as before.
const footerBranch = async ($: EngineInterface): Promise<string | null> => {
  const here = await read($, branch)
  if (!here) return null
  const rows = await $.config.list().catch(() => [])
  return rows.find(row => row.key === PR_FOOTER)?.value === true ? here : null
}

// How many times Claude ran git or gh this session, and how many it had when the board last began reading GitHub: a
// turn that ends with more reads it again.
let touches = 0
let readTouches = 0

// The next step the prompt box suggests after Claude's last turn, if any. The engine's own guess gives way to it.
let nextStep: string | null = null

// Makes an issue the one Claude is on in this session: the system prompt names it, and the next prompts note what
// changes on it from here.
const track = async ($: EngineInterface, issue: Issue, started = false): Promise<void> => {
  const sessionId = await $.session.id().catch(() => undefined)
  const known = knownOf(issue, (await read($, board))?.prs ?? [])
  await update($, working, () => ({ number: issue.number, title: issue.title, updatedAt: issue.updatedAt, ...(sessionId ? { sessionId } : {}), known, ...(started ? { started } : {}) }))
  await save($)
}

// The branch the folder has checked out. Moving to a branch named for an issue open on the board, such as
// `fix/315-glide`, makes that issue the one Claude is on, unless it already is in this session.
const followBranch = async ($: EngineInterface, name: string | null): Promise<void> => {
  const was = await read($, branch)
  await update($, branch, () => name)
  // Turned off, the branch still marks its pull request, but names no issue for Claude.
  const number = name === was || !settings.followBranch ? null : issueOfBranch(name)
  const issue = number === null ? undefined : (await read($, board))?.issues.find(one => one.number === number)
  if (!issue) return
  const doing = await read($, working)
  if (doing?.number === issue.number && doing.sessionId !== undefined && doing.sessionId === (await $.session.id().catch(() => undefined))) return
  await track($, issue)
  $.ui.toast(`Working on #${issue.number} now: the branch ${name} is for it`)
}

// The next look at GitHub: soon while a pull request's CI runs, every five minutes otherwise (or as often as set), and
// once the rate limit resets after it ran out. Each look sets the next one. Set to only when asked, there is none: the
// board reads on /issues refresh, r, and after Claude's turns that ran git or gh.
let timer: Timer | undefined
const schedule = async ($: EngineInterface, now: Board | null): Promise<void> => {
  timer?.cancel()
  if (settings.refresh === null) return
  const watching = now?.prs.some(pr => pr.ci === 'pending') ?? false
  const clock = await nowOf($)
  const wait = pausedUntil > clock ? pausedUntil - clock + 5_000 : watching ? WATCH_MS : settings.refresh * 60 * 1000
  timer = $.clock.after(wait, () => void poll($))
}

// Until when GitHub's rate limit has run out for the account, if it has. Every session and agent shares the limit, so
// the board reads nothing until then rather than spend what is left.
let pausedUntil = 0
const RATE_LIMITED = /rate limit/i

// The ETag GitHub last answered each cheap check with, by path. A check sends it back, and an answer of 304, nothing
// changed, doesn't count against the rate limit.
const etags = new Map<string, string>()

// What the cheap checks look at: the repo's issues and pull requests by their last change, which moves on a new one, an
// edit, a comment, a label or a close, and the check runs of each pull request whose CI is running.
const cheapChecksOf = (now: Board): string[] => [
  `repos/${now.repo}/issues?state=all&sort=updated&direction=desc&per_page=10`,
  ...now.prs.filter(pr => pr.ci === 'pending' && pr.sha).map(pr => `repos/${now.repo}/commits/${pr.sha}/check-runs?per_page=100`),
]

// Whether a REST read of `path` changed since the board last asked. True when it can't tell, so the board reads.
const changed = async ($: EngineInterface, path: string): Promise<boolean> => {
  const known = etags.get(path)
  // Taken as the call goes out: the cause may be another by the time GitHub answers.
  const cause = causeNow()
  try {
    const { stdout } = await $.process.run(['gh', 'api', '-i', ...(known ? ['-H', `If-None-Match: ${known}`] : []), path], { timeoutMs: 30_000 })
    const status = /^HTTP\/[\d.]+ (\d{3})/m.exec(stdout)?.[1]
    countCall(stats, cause, status === '304' ? 'rest304' : 'rest')
    if (status === '304') return false
    const tag = /^etag: *(.+)$/im.exec(stdout)?.[1]?.trim()
    if (status === '200' && tag) etags.set(path, tag)
    return true
  } catch {
    return true
  }
}

// The timer's look at GitHub. A full read costs GraphQL points; the cheap checks cost none when nothing changed. So the
// board reads in full when a check saw a change, or when its last full read is FULL_MS old. Another session's newer read
// of the same repo is taken as it is.
const poll = ($: EngineInterface): Promise<void> => within('poll', () => look($))

const look = async ($: EngineInterface): Promise<void> => {
  readTouches = touches
  const now = await read($, board)
  const clock = await nowOf($)
  if (pausedUntil > clock) return schedule($, now)
  if (!now || clock - now.fetchedAt >= FULL_MS) return refresh($)
  const shared = await adopt($, now)
  if (shared) return schedule($, shared)
  const seen = await Promise.all(cheapChecksOf(now).map(path => changed($, path)))
  if (seen.some(Boolean)) return refresh($)
  schedule($, now)
}

// After a full read: the cheap checks learn GitHub's answer now, so the next look can tell whether it changed since.
const prime = async ($: EngineInterface, now: Board): Promise<void> => {
  await Promise.all(cheapChecksOf(now).map(path => changed($, path)))
}

// Another session's read of the same repo, saved since this one's: the board takes it rather than read GitHub again.
// The saved copy has no bodies, so each issue keeps the body this board has for it while it is unchanged.
const adopt = async ($: EngineInterface, now: Board): Promise<Board | null> => {
  try {
    const saved = ((await $.store.get(await keyOf($))) as Partial<Saved> | undefined)?.board
    if (!saved || saved.repo !== now.repo || saved.fetchedAt <= now.fetchedAt) return null
    const issues = saved.issues.map(issue => {
      const mine = now.issues.find(one => one.number === issue.number)
      return issue.body === '' && mine && mine.updatedAt === issue.updatedAt ? { ...issue, body: mine.body } : issue
    })
    const taken = { ...saved, issues }
    await land($, now, taken, false)
    return taken
  } catch (cause) {
    $.ui.log(`issue-board: couldn't read another session's board: ${messageOf(cause)}`, { to: 'debug' })
    return null
  }
}

// When the rate limit resets, as GraphQL itself says: it still answers this once the limit has run out. A minute from
// now for a limit on how fast calls come, which resets sooner, or when GraphQL can't say.
const resetOf = async ($: EngineInterface, message: string): Promise<number> => {
  const soon = (await nowOf($)) + 60_000
  if (/secondary/i.test(message)) return soon
  try {
    const data = graphqlData(await gh($, ['api', 'graphql', '-f', 'query={ rateLimit { resetAt } }'])) as { rateLimit?: { resetAt?: string } }
    const at = Date.parse(data.rateLimit?.resetAt ?? '')
    return Number.isNaN(at) ? soon : at
  } catch {
    return soon
  }
}

// What one page of the issues query says about the rate limit: what it cost, and what is left.
const costOf = (page: string): { cost: number; remaining: number; resetAt: string } | null => {
  try {
    const limit = (JSON.parse(page) as { data?: { rateLimit?: { cost: number; remaining: number; resetAt: string } } }).data?.rateLimit
    return limit ?? null
  } catch {
    return null
  }
}

// What the board keeps between sessions, one entry per repository: a cache of what it can read from GitHub again, and
// nothing else. Every session on the repo rewrites this entry whole, so what the board may write to is a setting
// (writeProjects), and the person's choices live under a key of their own (see Choices). `version` is SAVED_VERSION
// when the entry was written; restore skips an entry of another version, whose board may lack fields this one needs.
type Saved = {
  version?: number
  board: Board | null
  working: Working | null
  dismissed: string[]
  viewer: string | null
  sections?: Record<string, boolean>
}
// Raise this when Saved or the Board it holds changes shape, so a new session reads GitHub rather than paint an old board.
const SAVED_VERSION = 1

// The person's choices for the repo, kept apart from the shared entry, which is only a cache: `declined` the projects
// whose prompt the person turned down, `statuses` the Status mapping setup, /issues statuses or Looks right saved, by
// project id, and `guessSeen` the guessed mappings the person answered (the Bugs and Later guesses among them).
// `markers` are the Bugs and Later labels /issues labels or Looks right saved. `preferred` is the project setup last
// applied to, which the board reads when the repo has several.
type Choices = {
  declined?: string[]
  statuses?: Record<string, Roles>
  guessSeen?: string[]
  markers?: Partial<Markers>
  preferred?: string
}

// The setting that lists the projects the board may write to, as `$.config.set` names it.
const WRITE_PROJECTS = 'issue-board.writeProjects'
// The project last adopted in this module, so the board can name it before it reads it, as after setup made it.
let lastAdopted: Adopted | null = null

let storeRoot: string | undefined
const rootOf = async ($: EngineInterface): Promise<string> => {
  if (storeRoot === undefined) {
    const repo = await $.session.repo().catch(() => null)
    storeRoot = repo?.root ?? (await $.session.root())
  }
  return storeRoot
}
const keyOf = async ($: EngineInterface): Promise<string> => `repo:${await rootOf($)}`
const choicesKeyOf = async ($: EngineInterface): Promise<string> => `choices:${await rootOf($)}`

// The person's choices, read fresh. Empty when none are saved.
const choicesOf = async ($: EngineInterface): Promise<Choices> => ((await $.store.get(await choicesKeyOf($))) as Choices | null | undefined) ?? {}

// The person's choices for the readers that carry on without them: empty when the store can't be read.
const savedChoices = async ($: EngineInterface): Promise<Choices> => {
  try {
    return await choicesOf($)
  } catch {
    return {}
  }
}

// The project of this repo the board may write to: the one it reads, when it may write there, or else the one this
// module adopted last, while it still may. Null when neither. `granted` says this repo's own settings grant it.
const adoptedNow = async ($: EngineInterface): Promise<Adopted | null> => {
  const grants = await grantsNow($)
  const reads = (await read($, board))?.project
  const record = reads ? adoptedOf(reads) : null
  const found =
    record && grants.all.includes(record.key)
      ? record
      : lastAdopted && grants.all.includes(lastAdopted.key)
        ? lastAdopted
        : null
  return found && grants.repo.includes(found.key) ? { ...found, granted: true } : found
}

// The board's options one settings file holds, under each name Claude Code keys the board by. Empty when it holds
// none, or can't be read.
const storedIn = async ($: EngineInterface, source: 'user' | 'project' | 'local'): Promise<Record<string, unknown>[]> => {
  try {
    const configs = ((await $.settings.read({ source })) as { pluginConfigs?: Record<string, { options?: Record<string, unknown> }> }).pluginConfigs ?? {}
    return Object.entries(configs).flatMap(([name, config]) => (name === 'issue-board' || name.startsWith('issue-board@') ? [config.options ?? {}] : []))
  } catch {
    // A source that can't be read holds nothing the board could tell.
    return []
  }
}

// The writeProjects values one settings file holds. Empty when it holds none, or can't be read.
const grantsIn = async ($: EngineInterface, source: 'user' | 'project' | 'local'): Promise<string[]> =>
  (await storedIn($, source)).flatMap(options => projectKeysOf(options.writeProjects))

// The board's options as the settings files hold them, a later source over an earlier one, as Claude Code merges them.
// Unlike the options the board is loaded with, they keep keys plugin.json no longer declares, which withOldKeys reads.
const storedOptions = async ($: EngineInterface): Promise<Record<string, unknown>> =>
  Object.assign({}, ...(await storedIn($, 'user')), ...(await storedIn($, 'project')), ...(await storedIn($, 'local')))

// The one answer to which projects the board may write to, for the write gate, the prompt, setup and project_adopt
// alike. The repo's own .claude/settings.json and settings.local.json count, read straight from the files: Claude Code
// may not pass a value to the board's options that it can't show in /config, as with the list the setting used to be.
const grantsNow = async ($: EngineInterface): Promise<Grants> => {
  const repo = [...(await grantsIn($, 'project')), ...(await grantsIn($, 'local'))]
  return grantsOf(settings.writeProjects, await grantsIn($, 'user'), repo)
}

// Sets writeProjects. A plugin's options are fixed for each load, and Claude Code reloads the board with the new value
// after the change, so the module goes by it from here: the change counts at once in this session, before and after
// the reload. Other sessions see it by the next time they load the board.
const writeSetting = async ($: EngineInterface, keys: string[]): Promise<void> => {
  const done = await $.config.set({ key: WRITE_PROJECTS, value: projectKeysText(keys) })
  if (done.deny !== undefined) throw new Error(done.deny)
  settings = { ...settings, writeProjects: keys }
  await loadAdoption($)
}

// The adoption as the setting has it and the declines as the store does, for the prompt and setup to draw.
const loadAdoption = async ($: EngineInterface): Promise<void> => {
  const saved = await savedChoices($)
  const adopted = await adoptedNow($)
  const next = { adopted, declined: saved.declined ?? [] }
  const was = await read($, adoption)
  if (JSON.stringify(was.adopted) !== JSON.stringify(next.adopted) || was.declined.join() !== next.declined.join()) await update($, adoption, () => next)
  const seen = saved.guessSeen ?? []
  if ((await read($, guessSeen)).join() !== seen.join()) await update($, guessSeen, () => seen)
  const marks = saved.markers ?? {}
  if (JSON.stringify(await read($, chosenMarkers)) !== JSON.stringify(marks)) await update($, chosenMarkers, () => marks)
}

// Changes the person's choices: turning a prompt down, a Status mapping, an answered guess. It reads the choices key just
// before writing it, so a change another session made meanwhile to a different field stays.
const changeChoices = async ($: EngineInterface, change: (was: Choices) => Choices): Promise<void> => {
  const was = await choicesOf($)
  await $.store.set(await choicesKeyOf($), change(was))
  await loadAdoption($)
}

// The person let the board write to a project, through its prompt, Apply in setup or project_adopt: writeProjects gets
// its owner/number, and keeps the others. The setting is written last, since the reload it brings may cut short what
// the module does after. Apply passes `later` and writes it once its steps are done, going by the project meanwhile.
const adoptProject = async ($: EngineInterface, project: { id: string; number: number; title: string; url: string }, later = false): Promise<void> => {
  const record = adoptedOf(project)
  if (!record) throw new Error(`the board can't tell who owns ${project.title} from its page, ${project.url || 'which it has none of'}`)
  const key = record.key
  await changeChoices($, was => ({ ...was, declined: (was.declined ?? []).filter(id => id !== project.id) }))
  lastAdopted = record
  const keys = [...(await grantsNow($)).own.filter(one => one !== key), key]
  if (!later) return writeSetting($, keys)
  settings = { ...settings, writeProjects: keys }
  await loadAdoption($)
}

// Release, in setup or project_adopt: that project leaves writeProjects, the others stay, and the board only reads it
// again. A project this repo's own settings grant can't be released here.
const releaseProject = async ($: EngineInterface, project: Adopted): Promise<void> => {
  const grants = await grantsNow($)
  if (grants.repo.includes(project.key)) throw new Error(grantedText(project.title))
  await writeSetting($, grants.own.filter(one => one !== project.key))
}

// Why Release can't take away a project the repo's own settings grant.
const grantedText = (title: string): string =>
  `This repo's .claude/settings.json lets the board write to ${title}, so it can't be released here. To release it, take it out of writeProjects in that file.`

// Keep read-only on the prompt: it isn't asked again for that project. Setup can still adopt it.
const declineProject = async ($: EngineInterface, project: { id: string }): Promise<void> => {
  await changeChoices($, was => ({ ...was, declined: [...(was.declined ?? []).filter(id => id !== project.id), project.id].slice(-20) }))
}

// The one way the board writes to a project. Every mutation, from Start, triage, the tools, the moves a read makes and
// setup, comes here, and is refused unless its project is the one adopted for this repo.
const projectWrite = async (
  $: EngineInterface,
  target: { number: number; title: string; url: string } | 'new',
  query: string,
  variables: Record<string, string | number | boolean | null | object>,
): Promise<Record<string, any>> => {
  const refusal = writeRefusal((await grantsNow($)).all, target)
  if (refusal) throw new Error(refusal)
  return postGraphql($, query, variables, true)
}

// The one way the board sends GraphQL with variables: the query and its variables as JSON on stdin, which carries
// lists and nulls as they are, and the answer's errors thrown. A read goes through gh(), which refuses a mutation; only
// projectWrite passes `write`, once its check has let the write through.
const postGraphql = async ($: EngineInterface, query: string, variables: Record<string, unknown>, write = false): Promise<Record<string, any>> => {
  const args = ['api', 'graphql', '--input', '-']
  const stdin = JSON.stringify({ query, variables })
  return graphqlData(await (write ? runGh($, args, stdin) : gh($, args, stdin)))
}

// A GraphQL read sent as gh's `-f` fields, as the issues pages and the review threads are, answered as gh gave it once
// its errors are checked.
const getGraphql = async ($: EngineInterface, args: string[]): Promise<string> => {
  const out = await gh($, args)
  graphqlData(out)
  return out
}

// Whether the board may write to a project, for the work it does by itself, which skips a project it may not write
// to without a word: /issues check and /issues help say so.
const mayWrite = async ($: EngineInterface, project: { number: number; title: string; url: string }): Promise<boolean> => writeRefusal((await grantsNow($)).all, project) === null

// Why the board may not write to the project it reads for this repo, or null when it may or reads none. The write tools
// check this before they ask, so the person never approves a change the gate would refuse straight after. A caller
// that has read the board already passes it, so the answer is about the same board it goes on to work with.
const boardRefusal = async ($: EngineInterface, known?: Pick<Board, 'project'> | null): Promise<string | null> => {
  const project = (known === undefined ? await read($, board) : known)?.project
  return project ? writeRefusal((await grantsNow($)).all, project) : null
}

// What the pane and the band ask about the project the board reads, or null: nothing once the board may write to it, or
// once the person kept it read-only.
const adoptAsk = (project: Project, now: Adoption): { title: string; lines: string[] } | null =>
  (now.adopted && now.adopted.key === projectKeyOf(project)) || now.declined.includes(project.id) ? null : adoptText(project, settings.refresh)

// Let it write, on the prompt.
const adoptFromPrompt = async ($: EngineInterface, project: Project): Promise<void> => {
  try {
    await adoptProject($, project)
    $.ui.toast(`The board may write to ${project.title} now. Release it in /issues setup.`)
  } catch (cause) {
    $.ui.toast(`Couldn't save that the board may write to ${project.title}: ${messageOf(cause)}`)
  }
}

// Keep read-only, on the prompt.
const declineFromPrompt = async ($: EngineInterface, project: Project): Promise<void> => {
  try {
    await declineProject($, project)
    $.ui.toast(`The board only reads ${project.title}. To let it write later, run /issues setup and press Apply.`)
  } catch (cause) {
    $.ui.toast(`Couldn't save that: ${messageOf(cause)}`)
  }
}

// Saves which Status option plays each part for a project, in the store only: nothing goes to GitHub, and saving a
// mapping isn't letting the board write to the project. The board goes by it at once.
const saveRoles = async ($: EngineInterface, project: { id: string }, roles: Roles): Promise<void> => {
  await changeChoices($, was => ({ ...was, statuses: { ...(was.statuses ?? {}), [project.id]: roles } }))
  await update($, board, now => (now?.project?.id === project.id ? { ...now, project: { ...now.project, roles: rolesFor(now.project.status, roles), guessed: false } } : now))
}

// A guessed mapping the person answered: the band doesn't show it again, in this session or another.
const seeGuess = async ($: EngineInterface, key: string): Promise<void> => {
  try {
    await changeChoices($, was => ({ ...was, guessSeen: [...(was.guessSeen ?? []).filter(one => one !== key), key].slice(-20) }))
  } catch (cause) {
    $.ui.toast(`Couldn't save that: ${messageOf(cause)}`)
  }
}

// Looks right, on the band's guess: the board keeps going by it, saved so it isn't a guess any more.
const confirmGuess = async ($: EngineInterface, project: Project): Promise<void> => {
  const key = guessKey(project, guessOf(project))
  try {
    await saveRoles($, project, project.roles ?? {})
    await seeGuess($, key)
    $.ui.toast(`Saved which Status is which for ${project.title}. Change it with /issues statuses.`)
  } catch (cause) {
    $.ui.toast(`Couldn't save which Status is which: ${messageOf(cause)}`)
  }
}

// `/issues statuses`, and Change on the band's guess: the Which Status is which step alone, at the top of the pane,
// starting from what the board goes by now. Null when the board has no project with a Status field to map.
const openStatuses = async ($: EngineInterface): Promise<Project | null> => {
  if ((await read($, board)) === null) await refresh($)
  const project = (await read($, board))?.project
  if (!project?.status) return null
  const picks = { ...(project.roles ?? rolesFor(project.status, undefined)) }
  await update($, statusPicks, () => ({ project: { id: project.id, title: project.title }, options: project.status?.options ?? [], picks }))
  await $.ui.open(OPEN)
  return project
}

// Save, in /issues statuses.
const saveStatuses = async ($: EngineInterface): Promise<void> => {
  const shown = await read($, statusPicks)
  if (!shown) return
  try {
    await saveRoles($, shown.project, shown.picks)
    await update($, statusPicks, () => null)
    $.ui.toast(`Saved which Status is which for ${shown.project.title}. Nothing changed on GitHub.`)
  } catch (cause) {
    $.ui.toast(`Couldn't save which Status is which: ${messageOf(cause)}`)
  }
}

// Saves the Bugs and Later markers the person chose, in the store only: nothing goes to GitHub. The board goes by them at
// once, in this session and the next.
const saveMarkers = async ($: EngineInterface, chosen: Partial<Markers>): Promise<void> => {
  await changeChoices($, was => ({ ...was, markers: { ...(was.markers ?? {}), ...chosen } }))
}

// Looks right, on the band's Bugs and Later guess: saved, so it isn't a guess any more.
const confirmMarkers = async ($: EngineInterface, ask: Partial<Markers>): Promise<void> => {
  try {
    await saveMarkers($, ask)
    await seeGuess($, markerKey(ask))
    $.ui.toast('Saved which labels Bugs and Later go by. Change them with /issues labels.')
  } catch (cause) {
    $.ui.toast(`Couldn't save which labels Bugs and Later go by: ${messageOf(cause)}`)
  }
}

// `/issues labels`, and Change on the band's guess: which label or issue type Bugs goes by, and without a project which
// label Later does, at the top of the pane, starting from what the board goes by now.
const openMarkers = async ($: EngineInterface): Promise<void> => {
  if ((await read($, board)) === null) await refresh($)
  const now = await read($, board)
  const picks = await markersNow($, now)
  await update($, markerPicks, () => ({ ...markerOptionsOf(now, picks), later: !now?.project, picks }))
  await $.ui.open(OPEN)
}

// Save, in /issues labels.
const saveMarkerPicks = async ($: EngineInterface): Promise<void> => {
  const shown = await read($, markerPicks)
  if (!shown) return
  try {
    await saveMarkers($, shown.later ? shown.picks : { bug: shown.picks.bug })
    await update($, markerPicks, () => null)
    $.ui.toast('Saved which labels Bugs and Later go by. Nothing changed on GitHub.')
  } catch (cause) {
    $.ui.toast(`Couldn't save which labels Bugs and Later go by: ${messageOf(cause)}`)
  }
}

// Releases the adopted project, and has setup, when it shows, offer to adopt it once more. Release in setup and the
// project_adopt tool both come here.
const releaseNow = async ($: EngineInterface, project: Adopted): Promise<void> => {
  await releaseProject($, project)
  await update($, setup, now =>
    now && 'facts' in now && now.phase !== 'applying'
      ? { ...now, phase: 'ready' as const, facts: { ...now.facts, adopted: null }, steps: stepsOf({ ...now.facts, adopted: null }, now.chosen, now.areas, now.roles) }
      : now,
  )
}

// Release, in setup, of the linked project it says the board may write to: the board only reads it again, and the plan
// offers to adopt it once more.
const releaseFromSetup = async ($: EngineInterface, project: SetupProject | undefined): Promise<void> => {
  const was = project && adoptedOf(project)
  if (!was) return
  try {
    await releaseNow($, was)
  } catch (cause) {
    $.ui.toast(`Couldn't release ${was.title}: ${messageOf(cause)}`)
    return
  }
  $.ui.toast(`Released ${was.title}: the board only reads it now.`)
}

// What a project_adopt call would do: release the adopted project, adopt one, or nothing, with why. It is worked out
// afresh for the permission check and again for the call, so the prompt and the change name the same project.
type AdoptPlan = { release: Adopted } | { adopt: Linked } | { refusal: string }
const adoptPlan = async ($: EngineInterface, input: unknown): Promise<AdoptPlan> => {
  const ask = (input ?? {}) as { number?: unknown; release?: unknown }
  const was = await adoptedNow($)
  if (ask.release === true) {
    if (!was) return { refusal: "The board writes to no project for this repo, so there's nothing to release." }
    return was.granted ? { refusal: grantedText(was.title) } : { release: was }
  }
  const number = ask.number
  if (number !== undefined && !(typeof number === 'number' && Number.isInteger(number) && number > 0)) return { refusal: 'number is a project number, such as 8.' }
  const now = await read($, board)
  if (!now) return { refusal: NOT_READ_SENTENCE }
  const reads = now.project ? { id: now.project.id, number: now.project.number, title: now.project.title, url: now.project.url } : null
  // The linked projects are read only for a number other than the one the board reads.
  let linked: Linked[] = []
  if (number !== undefined && reads?.number !== number) {
    const [owner = '', name = ''] = now.repo.split('/')
    linked = linkedOf(await postGraphql($, LINKED_QUERY, { owner, name }))
  }
  const target = adoptTarget(reads, linked, number, now.repo)
  if (typeof target === 'string') return { refusal: target }
  const key = projectKeyOf(target)
  if (key && (await grantsNow($)).all.includes(key)) return { refusal: `The board already writes to ${target.title}; nothing changed.` }
  return { adopt: target }
}

// The permission mode as the classic hooks last gave it, for project_adopt and project_plan to tell whether their
// prompt would be seen. Undefined until one says.
let permissionMode: string | undefined

// The mode in force when it is one that settles prompts unseen, else undefined.
const unseenMode = (): string | undefined => (permissionMode && UNSEEN_MODES.has(permissionMode) ? permissionMode : undefined)

// What project_plan answers in such a mode. The plan is on the card by then, so the person can still apply it.
const planUnseen = (mode: string): string =>
  `The ${mode} permission mode settles prompts without showing them, and a plan needs the person to read it. ` +
  'The plan is on the card in /issues: ask the person to apply it there with Apply, or to switch to a mode that asks, and try again.'

const save = async ($: EngineInterface): Promise<void> => {
  try {
    // Without the issues' bodies, which the next refresh brings back, to keep the store small.
    const now = await read($, board)
    const kept = now && { ...now, issues: now.issues.map(issue => ({ ...issue, body: '' })) }
    const saved: Saved = {
      version: SAVED_VERSION,
      board: kept,
      working: await read($, working),
      dismissed: await read($, dismissed),
      viewer: await read($, viewer),
      sections: await read($, sections),
    }
    await $.store.set(await keyOf($), saved)
  } catch (cause) {
    $.ui.log(`issue-board: couldn't save the board: ${messageOf(cause)}`, { to: 'debug' })
  }
}

// A new session paints the last board at once and still knows the issue Claude was on; a reload keeps its own. What a
// refresh wrote meanwhile stays: it is newer than the saved copy.
const restore = async ($: EngineInterface): Promise<void> => {
  await loadAdoption($)
  if ((await read($, board)) !== null) return
  try {
    const saved = (await $.store.get(await keyOf($))) as Partial<Saved> | undefined
    if (!saved || saved.version !== SAVED_VERSION) return
    if (saved.board) await update($, board, now => now ?? saved.board ?? null)
    if (saved.working) await update($, working, now => now ?? saved.working ?? null)
    if (saved.dismissed) await update($, dismissed, now => (now.length > 0 ? now : (saved.dismissed ?? [])))
    if (saved.viewer) await update($, viewer, now => now ?? saved.viewer ?? null)
    if (saved.sections) await update($, sections, now => (Object.keys(now).length > 0 ? now : (saved.sections ?? {})))
  } catch (cause) {
    $.ui.log(`issue-board: couldn't read the saved board: ${messageOf(cause)}`, { to: 'debug' })
  }
}

// GitHub refusing to show projects for want of a permission, which reading issues without them answers.
const PROJECT_REFUSED = /read:project|\bproject\b.*\bscope|projectsV2|projectItems/i
const PAGES = 3

// The error GitHub last gave for projects. Until Check again clears it, the board reads issues without projects rather
// than be refused each time, and the permission check keeps saying how to fix it.
let projectRefusal: string | undefined

// The open issues over GraphQL, up to 300, with the repo's project when gh may read it.
const fetchIssues = async ($: EngineInterface, nameWithOwner: string): Promise<{ issues: Issue[]; project: Project | null; types: string[]; labels?: string[] }> => {
  const [owner = '', name = ''] = nameWithOwner.split('/')
  const kept = await savedChoices($)
  const preferred = kept.preferred
  // Another session may have adopted or released the project meanwhile; the prompt follows.
  await loadAdoption($)
  const pull = async (withProject: boolean, fields: readonly string[] = []): Promise<{ issues: Issue[]; project: Project | null; types: string[]; labels?: string[] }> => {
    const pages: string[] = []
    let after: string | null = null
    do {
      const page: string = await getGraphql($, ['api', 'graphql', '-f', `owner=${owner}`, '-f', `name=${name}`, ...(after ? ['-f', `after=${after}`] : []), ...(withProject ? ['-f', `order=${orderFilter(owner, name)}`] : []), '-f', `query=${issuesQuery(withProject, fields)}`])
      pages.push(page)
      after = nextPageOf(page)
    } while (after && pages.length < PAGES)
    const limits = pages.map(costOf).filter(limit => limit !== null)
    for (const limit of limits) countPoints(stats, limit)
    const last = limits.at(-1)
    if (last) {
      const cost = limits.reduce((sum, limit) => sum + limit.cost, 0)
      $.ui.log(`issue-board: the issues query cost ${cost} GraphQL points over ${pages.length} ${pages.length === 1 ? 'page' : 'pages'}; ${last.remaining} left until ${last.resetAt}`, { to: 'debug' })
    }
    const parsed = parseGraph(pages, preferred, fields)
    // The project's views may filter or group by fields beyond Status and Priority. Their values are read with the
    // issues, named from the views the last read found. When the views now name a field that read didn't ask for, as on
    // the first read or after a view changed, the issues are read once more with it.
    const wanted = viewFieldsOf(parsed.project)
    if (withProject && wanted.some(field => !fields.includes(field))) return pull(true, wanted)
    // The board goes by the roles saved for the project it reads, by setup or /issues statuses, or else by the names,
    // which is a guess for the band to confirm.
    if (!parsed.project) return parsed
    const roles = kept.statuses?.[parsed.project.id]
    return { ...parsed, project: { ...parsed.project, roles: rolesFor(parsed.project.status, roles), guessed: roles === undefined } }
  }
  const unread = projectRefusal !== undefined || ((await read($, access))?.problems.some(problem => problem.id === 'scope-project') ?? false)
  if (!unread) {
    try {
      const last = viewFieldsOf((await read($, board))?.project)
      return await pull(true, last)
    } catch (cause) {
      const message = messageOf(cause)
      if (!PROJECT_REFUSED.test(message)) throw cause
      projectRefusal = message
      void checkAccess($, message)
    }
  }
  return pull(false)
}

// The refresh under way, if any. A module variable, not state: /clear empties the state while a refresh may still run,
// and a reload starts the module over while the state stays. Neither must leave the board waiting on a refresh that
// nobody runs.
let refreshing: Promise<void> | undefined

// How many times the session started over in this process, and whether it did since the board last read its saved copy
// and GitHub. A /clear (or /new, its alias) or a /resume starts a new session in the same process: the host empties
// every plugin's state, and no `session.start` follows.
let restarts = 0
let restarted = false

// The copies of issues and pull requests sent with a prompt in this session, by number, each with what it stood for
// (copyKeyOf). Kept in memory, not in state or the store: a compaction or /clear empties it, as Claude no longer has
// those copies, and a reload starting it over only means a copy goes once more.
const sentCopies = new Map<number, string>()

// How many `#123`s of one prompt the board looks at: past the copies it carries, the rest are named in one line.
const MENTIONS_READ = 20

// Reads GitHub into the board. A refresh asked for while one runs waits for that one. `seen`: the refresh follows
// Claude's own gh write, so the issue it is on changed by its hand, not news.
const refresh = ($: EngineInterface, seen = false): Promise<void> => {
  if (refreshing) return refreshing
  const began = restarts
  const run = within('full read', () => readGitHub($, seen)).finally(() => {
    refreshing = undefined
  })
  refreshing = run
  // The session started over while it ran, so some of what it wrote went with the old state: read GitHub again.
  return run.then(() => (restarts === began ? undefined : refresh($, seen)))
}

// A new session in the same process: the board shows its saved copy at once, checks access again, and reads GitHub.
const begin = async ($: EngineInterface): Promise<void> => {
  restarted = false
  await restore($)
  void checkAccess($)
  await refresh($)
}

// The repository the folder is, as gh names it: read once a session, since it doesn't change.
let repoInfo: { nameWithOwner: string; hasIssuesEnabled: boolean } | undefined
const repoNow = async ($: EngineInterface): Promise<{ nameWithOwner: string; hasIssuesEnabled: boolean }> =>
  (repoInfo ??= JSON.parse(await gh($, ['repo', 'view', '--json', 'nameWithOwner,hasIssuesEnabled'])) as { nameWithOwner: string; hasIssuesEnabled: boolean })

const readGitHub = async ($: EngineInterface, seen: boolean): Promise<void> => {
  // The rate limit ran out: the timer set for its reset reads then.
  if (pausedUntil > (await nowOf($))) return
  await update($, loading, () => true)
  readTouches = touches
  // What the board had spent when the read began, so the stats can say what this read cost.
  const spent = { calls: { ...(stats.calls['full read'] ?? zero()) }, points: stats.points }
  const before = await read($, board)
  let after = before
  try {
    const from = since(Date.now())
    const known = await read($, viewer)
    // First, so a folder that isn't a GitHub repo stops at one call, and a repo with issues turned off skips them.
    const repo = await repoNow($)
    const listIssues = (args: string[]) => (repo.hasIssuesEnabled ? gh($, ['issue', 'list', ...args]) : Promise.resolve('[]'))
    const [owner = '', name = ''] = repo.nameWithOwner.split('/')
    // The weekly counts change a little a day, and reading them takes up to ten GraphQL searches: kept for an hour.
    const kept = before?.repo === repo.nameWithOwner && before.velocityAt !== undefined && (await nowOf($)) - before.velocityAt < VELOCITY_MS ? before : null
    const [graph, prs, threads, closed, merged, login, current, milestones] = await Promise.all([
      repo.hasIssuesEnabled ? fetchIssues($, repo.nameWithOwner) : Promise.resolve({ issues: [], project: null, types: [], labels: undefined }),
      gh($, [
        'pr',
        'list',
        '--state',
        'open',
        '--limit',
        '50',
        '--json',
        'number,title,url,author,headRefName,headRefOid,isDraft,statusCheckRollup,reviewDecision,additions,deletions,updatedAt,body,closingIssuesReferences,mergeStateStatus,reviewRequests',
      ]),
      // Review threads still open on each pull request; without them, the rows just don't count threads.
      getGraphql($, ['api', 'graphql', '-f', `owner=${owner}`, '-f', `name=${name}`, '-f', `query=${THREADS_QUERY}`]).then(threadsOf, () => new Map<number, number>()),
      kept ? null : listIssues(['--state', 'closed', '--search', `closed:>=${from}`, '--limit', '500', '--json', 'closedAt']),
      kept ? null : gh($, ['pr', 'list', '--state', 'merged', '--search', `merged:>=${from}`, '--limit', '500', '--json', 'mergedAt']),
      // Who Mine means: asked once, then kept.
      known ?? gh($, ['api', 'user', '--jq', '.login']).then(out => out.trim() || null, () => null),
      currentBranch($),
      // The open milestones, over REST; the last read's stand when they can't be read.
      repoMilestones($, repo.nameWithOwner).catch(() => before?.milestones ?? []),
    ])
    // Each open epic's sub-issues in GitHub's order, over REST; an epic whose order can't be read keeps the board's own.
    const issues = await Promise.all(
      graph.issues.map(async issue => {
        if ((issue.subIssues?.total ?? 0) === 0) return issue
        try {
          const listed = JSON.parse(await gh($, ['api', `repos/${repo.nameWithOwner}/issues/${issue.number}/sub_issues?per_page=100`])) as { number: number }[]
          return { ...issue, subOrder: listed.map(one => one.number) }
        } catch {
          return issue
        }
      }),
    )
    const fetchedAt = await nowOf($)
    const next: Board = {
      repo: repo.nameWithOwner,
      issues,
      prs: parsePrs(prs).map(pr => ({ ...pr, openThreads: threads.get(pr.number) ?? 0 })),
      velocity:
        kept && closed === null && merged === null
          ? kept.velocity
          : { closed: weekly(timesOf(closed ?? '[]', 'closedAt'), fetchedAt), merged: weekly(timesOf(merged ?? '[]', 'mergedAt'), fetchedAt) },
      velocityAt: kept?.velocityAt ?? fetchedAt,
      milestones,
      issueTypes: graph.types,
      ...(graph.labels ? { labels: graph.labels } : {}),
      fetchedAt,
      project: graph.project,
    }
    after = next
    if (login !== known) await update($, viewer, () => login)
    await land($, before, next, seen)
    await followBranch($, current)
    // The branch's pull request has CI running: the board watches the run for its progress.
    if (current && next.prs.some(pr => pr.branch === current && pr.ci === 'pending')) void watchRuns($)
    // GitHub answers again: look again too, so a problem fixed since the last check goes.
    if (((await read($, access))?.problems.length ?? 0) > 0) void checkAccess($)
    void prime($, next)
    const calls = stats.calls['full read'] ?? spent.calls
    stats.lastRead = { at: fetchedAt, calls: minus(calls, spent.calls), points: stats.points - spent.points }
  } catch (cause) {
    const message = messageOf(cause)
    repoInfo = undefined
    if (RATE_LIMITED.test(message)) {
      const was = pausedUntil
      const clock = await nowOf($)
      pausedUntil = await resetOf($, message)
      const at = new Date(pausedUntil).toTimeString().slice(0, 5)
      await update($, error, () => `GitHub's rate limit for this account ran out. The board reads again at ${at}.`)
      if (was <= clock) $.ui.toast(`GitHub's rate limit ran out; the issue board waits until ${at}`)
    } else {
      await update($, error, () => message)
      void checkAccess($, message)
    }
  } finally {
    await update($, loading, () => false)
    schedule($, after)
  }
}

// Lets go of the confirm waiting on a second press when it is of this kind; one of another kind stays armed.
const disarm = async ($: EngineInterface, kind: NonNullable<Armed>['kind']): Promise<void> => {
  await update($, armed, was => (was?.kind === kind ? null : was))
}

// A new read of the board, this session's or another's: it goes on the board, and what follows from the change does.
const land = async ($: EngineInterface, before: Board | null, next: Board, seen: boolean): Promise<void> => {
  await update($, board, () => next)
  // A plan whose every change the board now shows as made, as when Claude made them another way, leaves the card. One
  // being applied is left to its Apply.
  await update($, proposal, was => (was && !was.applying && rowsToMake(was.rows, next).length === 0 ? null : was))
  // Merge all's confirm waits on pull requests that are all gone now.
  if (next.prs.length === 0) await disarm($, 'merge-all')
  const green = wentGreen(before, next)
  if (green.length > 0) await update($, greened, list => [...list.slice(-50), ...green.map(greenKey)])
  if (seen) {
    await update($, working, was => {
      const issue = was && next.issues.find(one => one.number === was.number)
      return was && issue ? { ...was, updatedAt: issue.updatedAt } : was
    })
  }
  await update($, error, () => null)
  await save($)
  // The project the board reads now names the adopted one.
  await loadAdoption($)
  // New issues in the Inbox while it shows: Claude suggests for them too, unless its last answer failed, which waits
  // for Suggest again.
  // The Inbox shows only while it is a tab, which it isn't once the project's views are the tabs.
  const inboxShown = tabOf(filtersFor(next.project), await read($, filter)).id === 'inbox'
  if (inboxShown && !(await read($, triage)).failed) void suggestInbox($)
  void moveToDone($, before, next)
  void moveToVerification($, before, next)
  // Epic lines that no longer hold on this read go before advanceEpics raises new ones.
  const clock = await nowOf($)
  await update($, epicNotes, list => liveEpicNotes(list, next, clock))
  void advanceEpics($, before, next)
}

// What the board moved on its own since the last prompt, which the next prompt notes for Claude.
let moved: string[] = []

// An issue a merged pull request refers to with `Refs #N`, not `Closes`, moves to Verification: merging didn't complete
// its acceptance, so it waits on a check or sign-off. REST says whether the pull request merged; only the move spends
// GraphQL. An issue already at Verification or Done, or a project without Verification, is left alone.
const moveToVerification = async ($: EngineInterface, before: Board | null, next: Board): Promise<void> => {
  const project = next.project
  const verify = roleOf(project, 'verification')
  if (!settings.autoMove || !project?.status || !verify || !(await mayWrite($, project))) return
  const merged = new Map<number, boolean>()
  const verified: number[] = []
  const failed: { number: number; message: string }[] = []
  for (const left of leftForVerification(before, next)) {
    try {
      if (!merged.has(left.pr)) merged.set(left.pr, !/^(null)?$/.test((await gh($, ['api', `repos/${next.repo}/pulls/${left.pr}`, '--jq', '.merged_at'])).trim()))
      if (!merged.get(left.pr)) continue
      await projectWrite($, project, SET_FIELD, { project: project.id, item: left.item, field: project.status.id, option: verify.id })
      await update($, board, was => was && { ...was, issues: was.issues.map(one => (one.number === left.number ? { ...one, status: verify.name } : one)) })
      moved.push(`#${left.number} moved to ${verify.name}: pull request #${left.pr}, which refers to it without closing it, merged.`)
      verified.push(left.number)
    } catch (cause) {
      failed.push({ number: left.number, message: messageOf(cause) })
    }
  }
  if (verified.length > 0) {
    $.ui.toast(movedText(verify.name, verified, 'a pull request that refers to it merged without closing it', 'pull requests that refer to them merged without closing them'))
  }
  if (failed.length > 0) $.ui.toast(unmovedText(verify.name, failed))
}

// An issue that closed as completed since the last read moves to Done in the project, wherever it was closed: by a
// merge, by Claude, or on GitHub. One closed as not planned stays where it was. REST says how it closed; only the move
// spends GraphQL.
const moveToDone = async ($: EngineInterface, before: Board | null, next: Board): Promise<void> => {
  const project = next.project
  const done = roleOf(project, 'done')
  // Turned off, the board neither moves closed issues nor asks GitHub how they closed.
  if (!settings.autoMove || !project?.status || !done || !(await mayWrite($, project))) return
  const done$: number[] = []
  const failed: { number: number; message: string }[] = []
  for (const left of leftForDone(before, next)) {
    try {
      const how = JSON.parse(await gh($, ['api', `repos/${next.repo}/issues/${left.number}`, '--jq', '{state, state_reason}'])) as { state?: string; state_reason?: string | null }
      if (how.state !== 'closed' || how.state_reason !== 'completed') continue
      await projectWrite($, project, SET_FIELD, { project: project.id, item: left.item, field: project.status.id, option: done.id })
      done$.push(left.number)
      moved.push(`#${left.number} moved to ${done.name}: it closed as completed.`)
    } catch (cause) {
      failed.push({ number: left.number, message: messageOf(cause) })
    }
  }
  // The person sees what the board did on its own, once a read, and what it couldn't.
  if (done$.length > 0) $.ui.toast(movedText(done.name, done$, 'it closed as completed', 'they closed as completed'))
  if (failed.length > 0) $.ui.toast(unmovedText(done.name, failed))
}

// An epic follows its sub-issues. When a read sees an epic's last open sub-issue close, its "Every sub-issue is closed"
// box is ticked. With every box then ticked, it closes as completed and moves to Done here, since it leaves the board
// now and moveToDone would never see it go. With other boxes open, it moves to Verification, where a person checks what
// is left, and the band and the next prompt say why. A sub-issue open again under an epic is only noted: reopening an
// epic or moving it back is a person's call.
const advanceEpics = async ($: EngineInterface, before: Board | null, next: Board): Promise<void> => {
  if (!settings.autoMove) return
  const { finished, reopened, orphaned } = epicChanges(before, next)
  const titleOf = (number: number) => next.issues.find(one => one.number === number)?.title ?? next.issues.find(one => one.parent?.number === number)?.parent?.title ?? ''
  const at = await nowOf($)
  const notes: EpicNote[] = [
    ...reopened.map(one => ({ key: `epic-reopened-${one.epic}-${one.number}`, kind: 'reopened' as const, epic: one.epic, number: one.number, title: titleOf(one.epic), text: `#${one.number} reopened under it`, at })),
    ...orphaned.map(one => ({ key: `epic-orphaned-${one.epic}-${one.number}`, kind: 'orphaned' as const, epic: one.epic, number: one.number, title: titleOf(one.epic), text: `#${one.number} is open under it, and it is closed`, at })),
  ]
  // Closing and ticking are the issue's own; the Status moves wait until the person lets the board write to the project.
  const project = next.project && (await mayWrite($, next.project)) ? next.project : null
  for (const number of finished) {
    const epic = next.issues.find(one => one.number === number)
    if (!epic) continue
    try {
      // The body as GitHub has it now, so a box ticked meanwhile counts. The tick takes the same read.
      const { body } = await readBody($, next.repo, number)
      const checks = checksOf(body)
      const box = subIssuesBoxOf(checks)
      if (box > 0 && !checks[box - 1]?.done) await tick($, number, [box], true, body)
      const open = checks.filter((check, index) => !check.done && index !== box - 1).length
      if (open === 0) {
        for (const command of commandsOf(number, { close: 'completed' })) await gh($, command.argv, command.stdin)
        const done = project?.status ? roleOf(project, 'done') : undefined
        if (project?.status && done && epic.status !== done.name) await setField($, epic, 'status', done.name)
        moved.push(`#${number} closed as completed${done ? ` and moved to ${done.name}` : ''}: every sub-issue is closed and every box is ticked.`)
        await update($, board, was => was && { ...was, issues: was.issues.filter(one => one.number !== number) })
        await save($)
        $.ui.toast(`Closed epic #${number}: every sub-issue is closed and every box is ticked.`)
        continue
      }
      const verify = roleOf(project, 'verification')
      const left = open === 1 ? '1 box is still open' : `${open} boxes are still open`
      const further = !!epic.status && [verify?.name, roleOf(project, 'done')?.name].includes(epic.status)
      const moving = !!project?.status && !!verify && !further
      if (moving && verify) await setField($, epic, 'status', verify.name)
      moved.push(`#${number} ${moving && verify ? `moved to ${verify.name}` : 'stays open'}: every sub-issue is closed, but ${left}.`)
      notes.push({ key: `epic-verify-${number}`, kind: 'verify', epic: number, title: epic.title, text: `every sub-issue is closed, but ${left}`, at })
    } catch (cause) {
      $.ui.toast(`Couldn't move epic #${number} on: ${messageOf(cause)}. /issues check may say why.`)
    }
  }
  // A note raised again replaces the old one, so it shows once.
  if (notes.length > 0) await update($, epicNotes, list => [...list.filter(one => !notes.some(note => note.key === one.key)), ...notes].slice(-20))
}

// Puts an issue read straight from GitHub on the board. The change is the person's or Claude's own, so the issue
// Claude is on takes its new time and the band doesn't call it news.
const take = async ($: EngineInterface, fresh: Partial<Issue> & Pick<Issue, 'number' | 'updatedAt'>): Promise<void> => {
  // Neither `gh issue view` nor a REST write gives project or sub-issue fields, so the board's own stay.
  await update($, board, now => now && { ...now, issues: now.issues.map(one => (one.number === fresh.number ? { ...one, ...fresh } : one)) })
  await update($, working, was => (was && was.number === fresh.number ? { ...was, updatedAt: fresh.updatedAt } : was))
  await save($)
}

// An issue's body as GitHub has it now, and when the issue last changed, over REST. Every change made to a body starts
// from this read, so an edit made meanwhile isn't lost.
const readBody = async ($: EngineInterface, repo: string, number: number): Promise<{ body: string; updatedAt: string }> => {
  const raw = JSON.parse(await gh($, ['api', `repos/${repo}/issues/${number}`, '--jq', '{body, updated_at}'])) as { body: string | null; updated_at: string }
  return { body: raw.body ?? '', updatedAt: raw.updated_at }
}

// Writes an issue's body, with its title when one is given, over REST, and puts what GitHub then has on the board.
const writeBody = async ($: EngineInterface, repo: string, number: number, fields: { title?: string; body?: string }): Promise<void> => {
  const raw = JSON.parse(await gh($, ['api', '-X', 'PATCH', `repos/${repo}/issues/${number}`, '--input', '-'], JSON.stringify(fields))) as {
    title: string
    body: string | null
    updated_at: string
  }
  await take($, { number, title: raw.title, body: raw.body ?? '', checks: checksOf(raw.body), updatedAt: raw.updated_at })
}

// Ticks or unticks boxes in an issue's body, read fresh from GitHub so an edit made meanwhile isn't lost, unless the
// caller has just read it and passes it as `known`. One at a time: two presses in a row would otherwise each write the
// body the other read. Answers what it did, and the boxes as GitHub had them just before.
let ticking: Promise<unknown> = Promise.resolve()
const tick = ($: EngineInterface, number: number, boxes: number[], done: boolean, known?: string): Promise<{ text: string; before: Check[] }> => {
  const run = ticking.then(async () => {
    const repo = (await read($, board))?.repo
    if (!repo) throw new Error(NOT_READ)
    const body = known ?? (await readBody($, repo, number)).body
    const before = checksOf(body)
    const edit = tickBody(body, boxes, done)
    if (edit.missing.length > 0) throw new Error(noBoxText(number, before.length, edit.missing))
    if (edit.changed.length > 0) await writeBody($, repo, number, { body: edit.body })
    const step = progress(checksOf(edit.body))
    const tally = `#${number} has ${step.done}/${step.total} ticked.`
    if (edit.changed.length === 0) return { text: `Nothing changed: ${boxes.length === 1 ? 'that box was' : 'those boxes were'} already ${done ? 'ticked' : 'unticked'}. ${tally}`, before }
    return { text: `${done ? 'Ticked' : 'Unticked'} ${edit.changed.length === 1 ? 'box' : 'boxes'} ${edit.changed.join(', ')}. ${tally}`, before }
  })
  ticking = run.catch(() => undefined)
  return run
}

// Check again: look, say what is left, and read GitHub once nothing is.
const recheck = async ($: EngineInterface): Promise<void> => {
  projectRefusal = undefined
  const left = await checkAccess($)
  $.ui.toast(left.length === 0 ? 'The issue board has what it needs.' : `Still missing: ${left.map(problem => problem.title).join(' · ')}`)
  if (left.length === 0) void refresh($)
}

// Copies a problem's command, or the page its fix happens on, for the person to run or open.
const copyFix = async ($: EngineInterface, problem: Problem, surface?: UiCopyArgs['surface']): Promise<void> => {
  const text = problem.command ?? problem.url ?? problem.fix
  const copied = await $.ui.copy({ text, ...(surface ? { surface } : {}) })
  if (!copied.isCopied) $.ui.toast(`Couldn't copy it. ${problem.fix}`)
  else $.ui.toast(problem.command ? `Copied \`${text}\`. Run it in a terminal, then press Check again.` : `Copied ${text}. Open it in the browser, then press Check again.`)
}

const dismissProblem = async ($: EngineInterface, problem: Problem): Promise<void> => {
  await update($, dismissed, list => [...list.slice(-50), accessKey(problem)])
  await save($)
}

// How the pane opens: Esc steps back through it, a card first, then the pane (the ui.close hook).
const OPEN = { id: PANE, title: 'Issues', focus: true, closeOnEscape: true } as const

// What setting an issue's fields in the project needs of it: its number, its node, and its item there if it has one. An
// issue on the board has them; one that isn't, such as one already closed, is read from GitHub.
type Target = Pick<Issue, 'number' | 'id' | 'item'>

// Sets Status or Priority on an issue in the repo's project, adding the issue to the project first when it isn't in it.
// An issue's item in the project, added to the project first when it has none.
const itemFor = async ($: EngineInterface, issue: Target, project: Project): Promise<string> => {
  if (issue.item) return issue.item
  if (!issue.id) throw new Error(`#${issue.number} hasn't been read with its project yet; refresh and try again`)
  const item = await addItem($, project, issue.id)
  await update($, board, was => was && { ...was, issues: was.issues.map(one => (one.number === issue.number ? { ...one, item } : one)) })
  return item
}

// Adds an issue to the project and answers its item. A project with an auto-add workflow may have added a new issue
// already, and GitHub then refuses the add: the item the project has is taken instead.
const addItem = async ($: EngineInterface, project: Project, content: string): Promise<string> => {
  try {
    const added = (await projectWrite($, project, ADD_ITEM, { project: project.id, content })) as { addProjectV2ItemById?: { item?: { id?: string } | null } | null }
    const item = added.addProjectV2ItemById?.item?.id
    if (item) return item
  } catch (cause) {
    if (!/already exists/i.test(messageOf(cause))) throw cause
  }
  const found = (await postGraphql($, ISSUE_ITEMS, { issue: content })) as { node?: { projectItems?: { nodes?: { id: string; project: { id: string } }[] } } }
  const item = found.node?.projectItems?.nodes?.find(one => one.project.id === project.id)?.id
  if (!item) throw new Error(`couldn't add it to ${project.title}`)
  return item
}

// An issue's values for the project's fields, by name, read from GitHub: one item at a time, when its card opens or a
// tool asks, so the board's main read stays cheap.
const readValues = async ($: EngineInterface, issue: Target): Promise<FieldValues> => {
  if (!issue.item) return {}
  try {
    const read$ = itemValuesOf(await postGraphql($, ITEM_VALUES, { item: issue.item }))
    await update($, values, was => ({ ...was, [issue.number]: read$ }))
    return read$
  } catch (cause) {
    $.ui.log(`issue-board: couldn't read #${issue.number}'s fields: ${messageOf(cause)}`, { to: 'debug' })
    return {}
  }
}

// Sets the project's other fields on an issue, by name, each value checked against the field's kind first; null clears
// one. Status and Priority have their own options.
const setFields = async ($: EngineInterface, issue: Target, given: Record<string, string | number | null>): Promise<void> => {
  const project = (await read($, board))?.project
  if (!project) throw new Error("the board reads no project for this repo, so it can't set its fields")
  // A field the board doesn't know may be new since its last read, which a field's change doesn't trigger: read again once.
  const known = (one: Project | null | undefined) => Object.keys(given).every(name => /^(status|priority)$/i.test(name) || one?.fields?.some(field => field.name.toLowerCase() === name.toLowerCase()))
  if (!known(project)) {
    await settle($)
    await refresh($)
  }
  const fresh = (await read($, board))?.project ?? project
  const plan = Object.entries(given).map(([name, value]) => {
    if (/^(status|priority)$/i.test(name)) throw new Error(`set ${name} with ${name.toLowerCase()}, not fields`)
    const field = fresh.fields?.find(one => one.name.toLowerCase() === name.toLowerCase())
    if (!field) throw new Error(`${fresh.title} has no field called ${name}${fresh.fields?.length ? `; it has ${fresh.fields.map(one => one.name).join(', ')}` : ''}`)
    if (value === null) return { field, value: null }
    const fits = fieldValueOf(field, value)
    if (typeof fits === 'string') throw new Error(fits)
    return { field, value: fits.value }
  })
  const item = await itemFor($, issue, fresh)
  for (const one of plan) {
    if (one.value === null) await projectWrite($, fresh, CLEAR_VALUE, { project: fresh.id, item, field: one.field.id })
    else await projectWrite($, fresh, SET_VALUE, { project: fresh.id, item, field: one.field.id, value: one.value })
  }
  await readValues($, { ...issue, item })
}

// Sets Status or Priority on an issue, by the option's name, and answers the option's name as the project spells it.
const setField = async ($: EngineInterface, issue: Target, field: 'status' | 'priority', name: string): Promise<string> => {
  const project = (await read($, board))?.project
  const target = field === 'status' ? project?.status : project?.priority
  const option = optionOf(target, name)
  if (!project || !target || !option) throw new Error(`the project has no ${field === 'status' ? 'Status' : 'Priority'} called ${name}`)
  const item = await itemFor($, issue, project)
  await projectWrite($, project, SET_FIELD, { project: project.id, item, field: target.id, option: option.id })
  const placed = item
  await update($, board, now => now && { ...now, issues: now.issues.map(one => (one.number === issue.number ? { ...one, item: placed, [field]: option.name } : one)) })
  await save($)
  return option.name
}

// Start, on GitHub too: the issue moves to In progress in the project and is assigned to the person, so the project
// says who is on what. Then the issue is read again, so the band doesn't call these changes news. Its epic follows, by
// its own setting.
const claim = async ($: EngineInterface, issue: Issue): Promise<void> => {
  // Turned off, Start leaves the issue's assignees and Status as they are.
  if (settings.claimOnStart) await claimIssue($, issue)
  await startEpic($, issue)
}

// A sub-issue started: its epic, still waiting in the Inbox, Backlog or Ready, moves to In progress with it, so the
// project shows the epic under way. An epic further along stays where it is.
const startEpic = async ($: EngineInterface, issue: Issue): Promise<void> => {
  if (!settings.autoMove) return
  const now = await read($, board)
  const epic = now ? epicToStart(now.issues, issue, now.project) : undefined
  const started = startedOf(now?.project)
  if (!epic || !started || !now?.project || !(await mayWrite($, now.project))) return
  try {
    await setField($, epic, 'status', started.name)
    moved.push(`#${epic.number} moved to ${started.name}: its sub-issue #${issue.number} was started.`)
  } catch (cause) {
    $.ui.toast(unmovedText(started.name, [{ number: epic.number, message: messageOf(cause) }]))
  }
}

const claimIssue = async ($: EngineInterface, issue: Issue): Promise<void> => {
  const failures: string[] = []
  const project = (await read($, board))?.project
  // The Status moves only in a project the person let the board write to; the issue is assigned either way.
  const started = project && (await mayWrite($, project)) ? startedOf(project) : undefined
  if (started && issue.status !== started.name) await setField($, issue, 'status', started.name).catch((cause: unknown) => void failures.push(messageOf(cause)))
  const me = await read($, viewer)
  if (!me || !issue.assignees.includes(me)) {
    await gh($, ['issue', 'edit', String(issue.number), '--add-assignee', '@me']).catch((cause: unknown) => void failures.push(messageOf(cause)))
  }
  try {
    const [fresh] = parseIssues(`[${await gh($, ['issue', 'view', String(issue.number), '--json', ISSUE_FIELDS])}]`)
    if (fresh) await take($, fresh)
  } catch (cause) {
    failures.push(messageOf(cause))
  }
  if (failures.length === 0) return
  $.ui.toast(`Started #${issue.number}, but couldn't update GitHub: ${failures[0]}`)
  if (failures.some(failure => ACCESS_ERROR.test(failure))) void checkAccess($, failures.join('\n'))
}

// An issue's REST id, by number. An issue that doesn't exist fails by its number, so Claude reads which one it was.
const restIssueId = async ($: EngineInterface, repo: string, number: number): Promise<string> => {
  try {
    return (await gh($, ['api', `repos/${repo}/issues/${number}`, '--jq', '.id'])).trim()
  } catch (cause) {
    throw new Error(notFoundText(messageOf(cause), repo, number))
  }
}

// Moves a sub-issue just before or just after a sibling in its epic, over REST, and the epic's order on the board with it.
const reorder = async ($: EngineInterface, repo: string, number: number, beside: number, before: boolean): Promise<void> => {
  const issues = (await read($, board))?.issues ?? []
  const issue = issues.find(one => one.number === number)
  const epic = issue?.parent?.number
  if (!issue || !epic) throw new Error(`#${number} isn't a sub-issue of an open epic on the board`)
  if (issues.find(one => one.number === beside)?.parent?.number !== epic) throw new Error(`#${beside} isn't a sub-issue of #${epic}, as #${number} is`)
  const [id, other] = await Promise.all([number, beside].map(one => restIssueId($, repo, one)))
  await gh($, ['api', '-X', 'PATCH', `repos/${repo}/issues/${epic}/sub_issues/priority`, '-F', `sub_issue_id=${id}`, '-F', `${before ? 'before_id' : 'after_id'}=${other}`])
  await update($, board, was => {
    if (!was) return was
    const siblings = was.issues.filter(one => one.parent?.number === epic).map(one => one.number)
    return { ...was, issues: was.issues.map(one => (one.number === epic ? { ...one, subOrder: reordered(one.subOrder ?? siblings, number, beside, before) } : one)) }
  })
  await save($)
}

// Moves an issue in the project's own order, the one the pane's rows follow: straight after `beside`, or before it, or
// to the top for null. The pane shows the new order at once; the next read confirms it.
const moveInProject = async ($: EngineInterface, number: number, beside: number | null, before: boolean): Promise<void> => {
  const now = await read($, board)
  const project = now?.project
  if (!now || !project) throw new Error("the board reads no project for this repo, so it can't move items in its order")
  const move = projectMoveOf(now.issues, number, beside, before)
  if (typeof move === 'string') throw new Error(move)
  await projectWrite($, project, MOVE_ITEM, { project: project.id, item: move.item, after: move.after?.item ?? null })
  await update($, board, was => was && { ...was, issues: placedAfter(was.issues, number, move.after?.number ?? null) })
  await save($)
}

// The repo an issue moves to, as `owner/name`: a bare name is the same owner's, and another owner's is refused, so an
// issue doesn't leave the owner's hands by a slip.
const sameOwner = (repo: string, target: string): string => {
  const owner = repo.split('/')[0] ?? ''
  const [first = '', second] = target.split('/')
  const full = second === undefined ? `${owner}/${first}` : target
  if (full.split('/')[0]?.toLowerCase() !== owner.toLowerCase()) throw new Error(`an issue moves only to another of ${owner}'s repos, not to ${target}`)
  if (full.toLowerCase() === repo.toLowerCase()) throw new Error(`the issue is in ${repo} already`)
  return full
}

// The repo's issue type a name stands for, ignoring case; or why it can't be one.
const typeOf = async ($: EngineInterface, name: string): Promise<string> => {
  const types = (await read($, board))?.issueTypes ?? []
  if (types.length === 0) throw new Error("the repo has no issue types; they come with an organization's settings")
  const found = types.find(one => one.toLowerCase() === name.toLowerCase())
  if (!found) throw new Error(`the repo has no issue type called ${name}; it has ${types.join(', ')}`)
  return found
}

// Sets or takes off an issue's type, over REST, and shows it on the board at once.
const setType = async ($: EngineInterface, repo: string, number: number, name: string | null): Promise<void> => {
  const type = name === null ? null : await typeOf($, name)
  await gh($, ['api', '-X', 'PATCH', `repos/${repo}/issues/${number}`, '--input', '-'], JSON.stringify({ type }))
  await update($, board, was => was && { ...was, issues: was.issues.map(one => (one.number === number ? { ...one, type } : one)) })
  await save($)
}

// Posts a comment on an issue: the one way the board comments, as a change's comment does too.
const postComment = async ($: EngineInterface, repo: string, number: number, body: string): Promise<void> => {
  const command = commentCommand(repo, number, body)
  await gh($, command.argv, command.stdin)
}

// Closes an issue as a duplicate of another, over REST: a `Duplicate of #N` comment, which GitHub turns into the link
// between them, then the close with GitHub's duplicate reason, or not planned where GitHub refuses it. The issue leaves
// the board at once. The other issue must exist.
const closeAsDuplicate = async ($: EngineInterface, repo: string, number: number, of: number): Promise<void> => {
  await restIssueId($, repo, of)
  await postComment($, repo, number, `Duplicate of #${of}`)
  const close = (reason: string) => gh($, ['api', '-X', 'PATCH', `repos/${repo}/issues/${number}`, '-f', 'state=closed', '-f', `state_reason=${reason}`])
  await close('duplicate').catch(() => close('not_planned'))
  await update($, board, was => was && { ...was, issues: was.issues.filter(one => one.number !== number) })
  await save($)
}

// The repo's labels with their colors, over REST, which spends nothing of the GraphQL limit. Every label list the board
// reads outside its main query comes from here, up to the same 100 that query reads.
const repoLabels = async ($: EngineInterface, repo: string): Promise<{ name: string; color?: string }[]> =>
  JSON.parse(await gh($, ['api', `repos/${repo}/labels?per_page=100`])) as { name: string; color?: string }[]

// The repo's milestones, the open ones or all of them, over REST, up to 100: every milestone list the board reads.
const repoMilestones = async ($: EngineInterface, repo: string, state: 'open' | 'all' = 'open'): Promise<Milestone[]> =>
  milestonesOf(JSON.parse(await gh($, ['api', `repos/${repo}/milestones?state=${state}&per_page=100`])) as unknown[])

// Makes the labels a change asks for that the repo hasn't got yet, over REST: an `area:` one takes the color the repo's
// other areas have. Answers the names it made, so the answer says so; the card's label picker offers them from then.
const ensureLabels = async ($: EngineInterface, repo: string, names: string[]): Promise<string[]> => {
  let existing: { name: string; color?: string }[]
  try {
    existing = await repoLabels($, repo)
  } catch (cause) {
    // Without the list, nothing is made: the change goes on, and GitHub names a label it hasn't got.
    $.ui.log(`issue-board: couldn't read the repo's labels: ${messageOf(cause)}`, { to: 'debug' })
    return []
  }
  const made: string[] = []
  for (const name of missingLabels(names, existing)) {
    await gh($, ['api', '-X', 'POST', `repos/${repo}/labels`, '-f', `name=${name}`, '-f', `color=${labelColorFor(name, existing)}`])
    made.push(name)
  }
  if (made.length > 0) await update($, palette, was => was && { ...was, labels: [...new Set([...was.labels, ...made])].sort() })
  return made
}

// A new title or body, over REST. Boxes added or reworded go into the body as GitHub has it now, so nothing else in it is
// lost. A whole new body goes in only while GitHub's body is still the one the board read: one changed meanwhile isn't
// overwritten. The board shows the new title and boxes at once.
const rewrite = async ($: EngineInterface, repo: string, number: number, changes: IssueChanges): Promise<void> => {
  let body: string | undefined
  if (changes.body !== undefined || changes.addBoxes?.length || changes.rewordBoxes?.length) {
    const fresh = await readBody($, repo, number)
    body = fresh.body
    if (changes.body !== undefined) {
      const known = (await read($, board))?.issues.find(one => one.number === number)
      if (!known) throw new Error(`the board doesn't hold #${number}, so it can't tell whether its body changed meanwhile; add or reword its boxes instead`)
      // A board saved between sessions has no bodies: then the time of the last change tells.
      const same = known.body ? known.body === body : known.updatedAt === fresh.updatedAt
      if (!same) throw new Error(`#${number}'s body changed on GitHub since the board read it, so it wasn't overwritten. Read it again with the issues tool, then change it`)
      body = changes.body
    }
    if (changes.rewordBoxes?.length) {
      const reworded = rewordBoxes(body, changes.rewordBoxes)
      if (reworded.missing.length > 0) throw new Error(noBoxText(number, checksOf(body).length, reworded.missing))
      body = reworded.body
    }
    if (changes.addBoxes?.length) body = addBoxes(body, changes.addBoxes)
  }
  await writeBody($, repo, number, { ...(changes.title ? { title: changes.title } : {}), ...(body !== undefined ? { body } : {}) })
}

// Makes or takes away an issue's blocked-by links, over REST, which spends none of the GraphQL limit, and shows them on
// the board at once. A blocker that doesn't exist fails, by its number, before any link is made.
const block = async ($: EngineInterface, repo: string, number: number, blockers: number[], on: boolean): Promise<void> => {
  const ids = await Promise.all(blockers.map(async one => ({ number: one, id: await restIssueId($, repo, one) })))
  const path = `repos/${repo}/issues/${number}/dependencies/blocked_by`
  for (const one of ids) await gh($, on ? ['api', '-X', 'POST', path, '-F', `issue_id=${one.id}`] : ['api', '-X', 'DELETE', `${path}/${one.id}`])
  // The board lists the open issues an issue is blocked by: a new link to one it holds shows, a removed one goes.
  await update($, board, was => {
    if (!was) return was
    const open = new Set(was.issues.map(one => one.number))
    const issues = was.issues.map(one => {
      if (one.number !== number) return one
      const kept = (one.blockedBy ?? []).filter(blocker => !blockers.includes(blocker))
      return { ...one, blockedBy: on ? [...kept, ...blockers.filter(blocker => open.has(blocker))] : kept }
    })
    return { ...was, issues }
  })
  await save($)
}

// GitHub's search over every issue of the repo, for the issues tool: one line each, and how many more there are. REST,
// so it spends none of the GraphQL limit.
const searchIssues = async ($: EngineInterface, repo: string, ask: { state?: string; search?: string; label?: string; assignee?: string; milestone?: string }): Promise<string> => {
  const terms = searchTerms(repo, ask)
  const answer = JSON.parse(await gh($, ['api', '-X', 'GET', 'search/issues', '-f', `q=${terms}`, '-f', 'per_page=30', '-f', 'sort=updated'])) as { total_count: number; items: unknown[] }
  const found = foundOf(answer.items)
  if (found.length === 0) return `No issues match \`${terms}\`.`
  const clock = await nowOf($)
  const more = answer.total_count > found.length ? `\nShowing ${found.length} of ${answer.total_count}; narrow the search to see the rest.` : ''
  return `${found.map(one => foundLine(one, clock)).join('\n')}${more}`
}

// An issue the board doesn't hold, read from GitHub over REST: closed, most often, with how and when, and its boxes.
const readClosed = async ($: EngineInterface, repo: string, number: number): Promise<string> => {
  let raw: {
    title: string
    html_url: string
    body: string | null
    state: string
    state_reason: string | null
    closed_at: string | null
    labels: { name: string }[]
    assignees: { login: string }[]
    comments?: number
    pull_request?: unknown
  }
  try {
    raw = JSON.parse(await gh($, ['api', `repos/${repo}/issues/${number}`]))
  } catch (cause) {
    // The reason stands alone here, so it starts with a capital, and a missing issue's words end with a full stop.
    const why = notFoundText(messageOf(cause), repo, number)
    return why.startsWith('#') ? `${why}.` : `${why.charAt(0).toUpperCase()}${why.slice(1)}`
  }
  if (raw.pull_request) return `#${number} is a pull request that isn't open. Read it with \`gh pr view ${number}\`.`
  const [found] = foundOf([{ ...raw, number }])
  const checks = checksOf(raw.body)
  return [
    `#${number} ${raw.title} (${found ? standing(found, await nowOf($)) : raw.state})`,
    raw.html_url,
    `Labels: ${raw.labels.map(label => label.name).join(', ') || 'none'}`,
    `Assignees: ${raw.assignees.map(user => user.login).join(', ') || 'none'}`,
    ...(checks.length > 0 ? [`Boxes (${checks.filter(check => check.done).length}/${checks.length} ticked):`, ...checks.map((check, index) => `${index + 1}. [${check.done ? 'x' : ' '}] ${check.text}`)] : []),
    `Read the whole issue with \`gh issue view ${number}\`.`,
    await latestComments($, repo, number, raw.comments),
  ].join('\n')
}

// An issue's latest comments, for the issues tool, over REST: only the page that holds the latest ones is read, when the
// count is known. A thread that can't be read says so rather than failing the answer.
const latestComments = async ($: EngineInterface, repo: string, number: number, total?: number): Promise<string> => {
  try {
    if (total === 0) return 'No comments.'
    const page = total ? Math.max(1, Math.ceil(total / 100)) : 1
    const read$ = async (at: number) => restCommentsOf(JSON.parse(await gh($, ['api', `repos/${repo}/issues/${number}/comments?per_page=100&page=${at}`])) as unknown[])
    let comments = await read$(page)
    // The last page may hold fewer than are shown: the one before fills it up.
    if (page > 1 && comments.length < TOOL_COMMENTS) comments = [...(await read$(page - 1)), ...comments]
    return commentsText(comments, total ?? comments.length, await nowOf($))
  } catch (cause) {
    return `Couldn't read its comments: ${messageOf(cause)}`
  }
}

// Makes or changes a milestone for Claude's milestone tool, over REST. By its title: one the repo hasn't got is made, and
// one it has, open or closed, is changed. The board's list follows at once.
const saveMilestone = async (
  $: EngineInterface,
  repo: string,
  ask: { title: string; newTitle?: string; due?: string; description?: string; close?: boolean; reopen?: boolean },
): Promise<string> => {
  if (ask.due && !/^\d{4}-\d{2}-\d{2}$/.test(ask.due)) throw new Error('give the due date as YYYY-MM-DD, or an empty string to clear it')
  const all = await repoMilestones($, repo, 'all')
  const found = all.find(one => one.title.toLowerCase() === ask.title.toLowerCase())
  const fields = {
    ...(ask.newTitle ? { title: ask.newTitle } : {}),
    // GitHub keeps a due date in US Pacific time, so midnight UTC would fall on the day before: noon UTC is the same day.
    ...(ask.due !== undefined ? { due_on: ask.due ? `${ask.due}T12:00:00Z` : null } : {}),
    ...(ask.description !== undefined ? { description: ask.description } : {}),
    ...(ask.close ? { state: 'closed' } : ask.reopen ? { state: 'open' } : {}),
  }
  const said = [
    ask.newTitle ? `renamed ${ask.newTitle}` : '',
    ask.due !== undefined ? (ask.due ? `due ${ask.due}` : 'no due date') : '',
    ask.description !== undefined ? 'described' : '',
    ask.close ? 'closed' : ask.reopen ? 'reopened' : '',
  ].filter(Boolean)
  let text: string
  if (!found) {
    if (ask.close || ask.reopen) throw new Error(`the repo has no milestone called ${ask.title}`)
    await gh($, ['api', '-X', 'POST', `repos/${repo}/milestones`, '--input', '-'], JSON.stringify({ title: ask.title, ...fields }))
    text = `Made the milestone ${ask.newTitle ?? ask.title}${said.length > 0 ? `: ${said.join(', ')}` : ''}.`
  } else {
    if (Object.keys(fields).length === 0) return `Nothing to change on the milestone ${found.title}.`
    await gh($, ['api', '-X', 'PATCH', `repos/${repo}/milestones/${found.number}`, '--input', '-'], JSON.stringify(fields))
    text = `Changed the milestone ${found.title}: ${said.join(', ')}.`
  }
  const open = await repoMilestones($, repo)
  await update($, board, was => was && { ...was, milestones: open })
  await update($, palette, was => was && { ...was, milestones: open.map(one => one.title) })
  await save($)
  return text
}

// The project's items over REST, one page of 100, with the Status field's values.
const projectItems = async ($: EngineInterface, path: string, project: Project): Promise<unknown[]> => {
  const fields = JSON.parse(await gh($, ['api', `${path}/fields?per_page=50`])) as { id: number; name: string }[]
  const field = fields.find(one => one.name === 'Status')
  if (!field) throw new Error(`${project.title} has no Status field`)
  return JSON.parse(await gh($, ['api', `${path}/items?per_page=100&fields=${field.id}`])) as unknown[]
}

// Archives project items for the project_archive tool: one issue's, or every one at Done that closed before a date. The
// first call only says how many and which; the archive waits for a call with `confirm`.
const archiveItems = async ($: EngineInterface, project: Project, ask: { number?: number; doneBefore?: string; confirm: boolean }): Promise<string> => {
  const path = projectPathOf(project.url)
  if (!path) throw new Error(`couldn't tell where ${project.title} lives on GitHub`)
  if (ask.number === undefined && !ask.doneBefore) throw new Error('give an issue number, or doneBefore a date')
  if (ask.doneBefore && !/^\d{4}-\d{2}-\d{2}$/.test(ask.doneBefore)) throw new Error('give doneBefore as a date, YYYY-MM-DD')
  const done = roleOf(project, 'done')
  if (ask.number === undefined && !done) throw new Error(`${project.title} has no Done option set; pick one in /issues statuses`)
  const items = await projectItems($, path, project)
  const chosen = toArchive(items, ask, done?.name)
  const what = ask.number !== undefined ? `#${ask.number}` : `the items at ${done?.name ?? 'Done'} that closed before ${ask.doneBefore}`
  if (chosen.length === 0) return ask.number !== undefined ? `#${ask.number} isn't in ${project.title}, or is archived already.` : `Nothing in ${project.title} to archive: no ${what.slice(4)}.`
  const listed = chosen.map(one => `#${one.number} ${one.title}`).join('\n')
  const count = `${chosen.length} ${chosen.length === 1 ? 'item' : 'items'}`
  const partial = items.length >= 100 ? ' Only the first 100 items of the project were read.' : ''
  if (!ask.confirm) return `Archiving ${what} takes ${count} out of the views of ${project.title}:\n${listed}\nThe issues stay as they are.${partial} Call again with confirm: true to archive.`
  for (const one of chosen) await projectWrite($, project, ARCHIVE_ITEM, { project: project.id, item: one.node })
  return `Archived ${count} from ${project.title}:\n${listed}`
}

// Posts a status update on the project for the project_status tool, and shows it in the pane's header at once.
const postStatus = async ($: EngineInterface, project: Project, ask: { status: string; note?: string; start?: string; target?: string }): Promise<string> => {
  const status = statusEnumOf(ask.status)
  if (!status) throw new Error(`a status update is On track, At risk, Off track, Complete or Inactive, not ${ask.status}`)
  for (const [name, date] of [['start', ask.start], ['target', ask.target]] as const) {
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error(`give ${name} as a date, YYYY-MM-DD`)
  }
  const posted = await projectWrite($, project, POST_STATUS, { project: project.id, status, body: ask.note ?? null, start: ask.start ?? null, target: ask.target ?? null })
  const latest: StatusUpdate = {
    status: updateWords(status),
    body: ask.note?.trim() ?? '',
    at: (posted as { createProjectV2StatusUpdate?: { statusUpdate?: { createdAt?: string } } }).createProjectV2StatusUpdate?.statusUpdate?.createdAt ?? new Date(await nowOf($)).toISOString(),
    start: ask.start ?? null,
    target: ask.target ?? null,
  }
  await update($, board, now => (now?.project?.id === project.id ? { ...now, project: { ...now.project, update: latest } } : now))
  await save($)
  return `Posted on ${project.title}: ${updateLine(latest, await nowOf($))}.`
}

// The project's issues at a Status, open and closed, for the issues tool: the board's copy holds open issues only, so
// the project is read over REST, with its Status field's values. One page of 100 items.
const readProject = async ($: EngineInterface, project: Project, status: string, since?: string): Promise<string> => {
  const path = projectPathOf(project.url)
  if (!path) return `Couldn't tell where ${project.title} lives on GitHub.`
  if (since && !/^\d{4}-\d{2}-\d{2}$/.test(since)) return 'Give since as a date, YYYY-MM-DD.'
  try {
    const items = await projectItems($, path, project)
    const found = itemsAt(items, status, since)
    const clock = await nowOf($)
    const scope = `${project.title} at ${status}${since ? `, closed since ${since}` : ''}`
    const more = items.length >= 100 ? '\nRead the first 100 items of the project; there may be more.' : ''
    return found.length > 0 ? `${scope} (${found.length}):\n${found.map(one => foundLine(one, clock)).join('\n')}${more}` : `Nothing in ${scope}.${more}`
  } catch (cause) {
    return `Couldn't read ${project.title}: ${messageOf(cause)}`
  }
}

// The issues closed lately, for the pane's Closed filter: read when the filter is chosen, over REST.
const readRecent = async ($: EngineInterface): Promise<void> => {
  const repo = (await read($, board))?.repo
  if (!repo) return
  try {
    const items = JSON.parse(await gh($, ['api', `repos/${repo}/issues?state=closed&sort=updated&direction=desc&per_page=30`])) as unknown[]
    await update($, recent, () => ({ items: foundOf(items), at: Date.now() }))
  } catch (cause) {
    await update($, recent, was => ({ items: was?.items ?? [], at: Date.now(), failed: messageOf(cause) }))
  }
}

// Files an issue for Claude's issue_create tool. REST does what it can, which spends nothing of the GraphQL limit the
// board reads with: the issue with its labels, assignees and milestone in one call, then its place under an epic. Only
// the project needs GraphQL: adding the item and setting its Status and Priority. Once the issue exists, a later step
// that fails is named in the answer, and nothing is undone. The issue goes on the board at once, without a read.
const fileIssue = async ($: EngineInterface, spec: NewIssue, quiet = false): Promise<string> => {
  if (!spec.subIssues?.length) return (await fileOne($, spec, quiet)).text
  const epic = await fileOne($, { ...spec, body: withSubIssuesBox(spec.body) }, quiet)
  // An epic's parts, in order, each under it. One that fails leaves the others to be filed.
  const parts: string[] = []
  for (const [index, part] of spec.subIssues.entries()) {
    try {
      parts.push((await fileOne($, { ...part, parent: epic.number }, quiet)).text)
    } catch (cause) {
      parts.push(`Couldn't file sub-issue ${index + 1}, “${part.title}”: ${messageOf(cause)}`)
    }
  }
  return [epic.text, `Its sub-issues:`, ...parts.map(text => `- ${text}`)].join('\n')
}

// Files one issue, as fileIssue says, and answers its number and what to tell Claude. `quiet` leaves the toast to the
// caller, as a capture says its own.
const fileOne = async ($: EngineInterface, spec: NewIssue, quiet = false): Promise<{ number: number; text: string }> => {
  const now = await read($, board)
  if (!now) throw new Error(NOT_READ)
  const repo = now.repo
  const me = await read($, viewer)
  let milestone: { number: number; title: string } | undefined
  if (spec.milestone) {
    // The board's own list first, as its last read had it; GitHub's when that lacks it, as for one made since.
    const named = (list: readonly Milestone[]) => list.find(one => one.title.toLowerCase() === spec.milestone?.toLowerCase())
    milestone = named(now.milestones ?? []) ?? named(await repoMilestones($, repo))
    if (!milestone) throw new Error(`the repo has no open milestone called ${spec.milestone}`)
  }
  const assignees = (spec.assign ?? []).flatMap(login => (login === '@me' ? (me ? [me] : []) : [login]))
  const type = spec.type ? await typeOf($, spec.type) : undefined
  const made = spec.labels?.length ? await ensureLabels($, repo, spec.labels) : []
  const fields = { title: spec.title, body: spec.body, labels: spec.labels ?? [], assignees, ...(milestone ? { milestone: milestone.number } : {}), ...(type ? { type } : {}) }
  const raw = JSON.parse(await gh($, ['api', '-X', 'POST', `repos/${repo}/issues`, '--input', '-'], JSON.stringify(fields))) as {
    number: number
    id: number
    node_id: string
    html_url: string
    updated_at: string
    labels: { name: string; color?: string }[]
    assignees: { login: string }[]
  }
  const did = [`“${spec.title}”`]
  const failed: string[] = []
  if (raw.labels.length > 0) did.push(`labelled ${raw.labels.map(label => label.name).join(', ')}`)
  if (raw.assignees.length > 0) did.push(`assigned ${raw.assignees.map(user => user.login).join(', ')}`)
  if (milestone) did.push(`on ${milestone.title}`)
  if (type) did.push(`typed ${type}`)
  if (made.length > 0) did.push(`with the new ${made.length === 1 ? 'label' : 'labels'} ${made.join(', ')}`)

  let parent: Issue['parent'] = null
  if (spec.parent) {
    try {
      await gh($, ['api', '-X', 'POST', `repos/${repo}/issues/${spec.parent}/sub_issues`, '-F', `sub_issue_id=${raw.id}`])
      const above = now.issues.find(one => one.number === spec.parent)
      parent = { number: spec.parent, title: above?.title ?? '', total: (above?.subIssues?.total ?? 0) + 1, completed: above?.subIssues?.completed ?? 0 }
      did.push(`under #${spec.parent}`)
    } catch (cause) {
      failed.push(`put it under #${spec.parent} (${messageOf(cause)})`)
    }
  }

  if (spec.blockedBy?.length) {
    try {
      // The issue isn't on the board yet: the links show with it, below.
      await block($, repo, raw.number, spec.blockedBy, true)
      did.push(`blocked by ${spec.blockedBy.map(one => `#${one}`).join(', ')}`)
    } catch (cause) {
      failed.push(`mark it blocked by ${spec.blockedBy.map(one => `#${one}`).join(', ')} (${messageOf(cause)})`)
    }
  }

  // Into the project, at the Status asked for, or the Inbox where the project has one, to be triaged.
  const project = now.project
  let item: string | null = null
  const set: { status?: string; priority?: string } = {}
  // A project the person hasn't let the board write to gets nothing: the issue is filed, and Claude reads why.
  const refusal = await boardRefusal($, now)
  if (project && refusal) {
    if (spec.status || spec.priority) failed.push(`set its Status or Priority: ${refusal}`)
    else did.push(`not added to ${project.title}, which the board only reads`)
  } else if (project) {
    try {
      item = await addItem($, project, raw.node_id)
      for (const [field, wanted] of [['status', spec.status ?? roleOf(project, 'inbox')?.name], ['priority', spec.priority]] as const) {
        if (!wanted) continue
        try {
          set[field] = await setField($, { number: raw.number, id: raw.node_id, item }, field, wanted)
        } catch (cause) {
          failed.push(`set its ${field === 'status' ? 'Status' : 'Priority'} (${messageOf(cause)})`)
        }
      }
      did.push([`in ${project.title}`, set.status, set.priority].filter(Boolean).join(', '))
    } catch (cause) {
      failed.push(`add it to ${project.title} (${messageOf(cause)})`)
    }
  } else if (spec.status || spec.priority) {
    failed.push('set its Status or Priority: the board reads no project for this repo')
  }

  const issue: Issue = {
    number: raw.number,
    title: spec.title,
    url: raw.html_url,
    labels: raw.labels.map(label => ({ name: label.name, color: label.color ?? '' })),
    assignees: raw.assignees.map(user => user.login),
    checks: checksOf(spec.body),
    updatedAt: raw.updated_at,
    body: spec.body,
    id: raw.node_id,
    item,
    status: set.status ?? null,
    priority: set.priority ?? null,
    milestone: milestone?.title ?? null,
    ...(type ? { type } : {}),
    parent,
    blockedBy: did.some(said => said.startsWith('blocked by')) ? (spec.blockedBy ?? []).filter(one => now.issues.some(issue => issue.number === one)) : [],
  }
  await update($, board, was => {
    if (!was) return was
    // The epic's count, on the epic and on each of its sub-issues, which carry it too.
    const counted = (one: Issue): Issue =>
      !parent
        ? one
        : one.number === parent.number
          ? { ...one, subIssues: { total: parent.total, completed: parent.completed } }
          : one.parent?.number === parent.number
            ? { ...one, parent: { ...one.parent, total: parent.total, completed: parent.completed } }
            : one
    const issues = was.issues.map(counted)
    return { ...was, issues: [issue, ...issues.filter(one => one.number !== issue.number)] }
  })
  await save($)
  if (!quiet) $.ui.toast(`Filed #${raw.number}`)
  return { number: raw.number, text: filedText(raw.number, did, failed) }
}

// How far back a capture looks for the same work among closed issues.
const CLOSED_LOOKBACK_MS = 30 * 24 * 60 * 60 * 1000

// An issue that is already the work a capture names: an open one from the board's copy, or else one closed in the last
// 30 days, read over REST, which spends nothing of the GraphQL limit. Null when there is none.
const sameWork = async ($: EngineInterface, repo: string, issues: Issue[], title: string): Promise<{ number: number; title: string; closed: boolean } | null> => {
  const open = sameWorkOf(title, issues)
  if (open) return { number: open.number, title: open.title, closed: false }
  const since = new Date((await nowOf($)) - CLOSED_LOOKBACK_MS).toISOString()
  type Closed = { number: number; title: string; closed_at?: string | null; pull_request?: unknown }
  // Work found is kept even when the closed issues can't be read: a duplicate can be closed in triage, a lost capture
  // can't be found again.
  let raw: Closed[] = []
  try {
    raw = JSON.parse(await gh($, ['api', `repos/${repo}/issues?state=closed&since=${since}&sort=updated&direction=desc&per_page=100`])) as Closed[]
  } catch (cause) {
    $.ui.log(`issue-board: couldn't read the closed issues to compare a capture with: ${messageOf(cause)}`, { to: 'debug' })
  }
  const closed = (Array.isArray(raw) ? raw : []).filter(one => !one.pull_request && one.closed_at && Date.parse(one.closed_at) >= Date.parse(since))
  const found = sameWorkOf(title, closed)
  return found ? { number: found.number, title: found.title, closed: true } : null
}

// Captures work found in conversation, for the capture tool and `/issues new`: files it as issue_create does with no
// Status asked for, so it lands in the Inbox for the person to triage, under an epic when one is given. When an open issue, or one closed in the last
// 30 days, is already that work, it goes there as a comment instead, and the answer says so. A toast says which, and
// the band counts what was filed until the person opens the Inbox.
const capture = async ($: EngineInterface, spec: NewIssue): Promise<string> => {
  const now = await read($, board)
  if (!now) throw new Error(NOT_READ)
  const found = await sameWork($, now.repo, now.issues, spec.title)
  if (found) {
    const parts = (spec.subIssues ?? []).map(part => `- ${part.title}`).join('\n')
    const note = [`Captured again from a conversation: **${spec.title}**`, spec.body.trim(), parts].filter(Boolean).join('\n\n')
    await postComment($, now.repo, found.number, note)
    $.ui.toast(`Added to #${found.number} as a comment: it looks like the same work`)
    return `Not filed: #${found.number} “${found.title}”${found.closed ? ', closed lately,' : ''} looks like the same work, so this went there as a comment instead.`
  }
  const filed = await fileIssue(
    $,
    {
      title: spec.title,
      body: spec.body,
      ...(spec.labels?.length ? { labels: spec.labels } : {}),
      ...(spec.parent ? { parent: spec.parent } : {}),
      ...(spec.subIssues?.length ? { subIssues: spec.subIssues } : {}),
    },
    true,
  )
  const parts = spec.subIssues?.length ?? 0
  await update($, captured, was => was + 1 + parts)
  const number = /^Filed #(\d+)/.exec(filed)?.[1] ?? '?'
  $.ui.toast(parts > 0 ? `Captured epic #${number} and ${parts} sub-issues to the Inbox` : `Captured #${number} to the Inbox`)
  return `Captured to the Inbox for the person to triage. ${filed}`
}

// `/issues new`: Claude writes the issue, or with `epic` a parent and its sub-issues, over the conversation so far,
// and it is captured to the Inbox at once. Toasts say how it went.
const captureFromTalk = async ($: EngineInterface, what: string, epic = false): Promise<void> => {
  const labels = labelsOf((await read($, board))?.issues ?? [])
  const prompt = draftPrompt(what, labels, epic)
  let reply: ModelForkResult = await $.model.fork({ prompt })
  if (!reply.isAnswered && reply.reason === 'nothing-to-fork' && what) reply = await $.model.complete({ model: 'sonnet', prompt, maxTokens: epic ? 4096 : 1024 })
  if (!reply.isAnswered) {
    $.ui.toast(reply.reason === 'nothing-to-fork' ? `Nothing to capture from yet. Say what it is about: /issues new ${epic ? 'epic ' : ''}<what>` : `Couldn't write the issue: ${reply.reason}`)
    return
  }
  const made = parseDraft(reply.text, labels)
  if (!made) {
    $.ui.toast(`Claude's answer didn't come back as ${epic ? 'an epic' : 'an issue'}. Try /issues new again.`)
    return
  }
  try {
    await capture($, made)
  } catch (cause) {
    $.ui.toast(`Couldn't capture the issue: ${messageOf(cause)}`)
  }
}

// Opens the pane at the Inbox, from the band's capture line: the built-in Inbox tab, or the project view whose filter
// is the Inbox. Without one, the pane opens as it was. Either way the count of captures starts again.
const openInbox = async ($: EngineInterface): Promise<void> => {
  const project = (await read($, board))?.project ?? null
  const tab = inboxTabOf(filtersFor(project), project)
  if (tab) await pickTab($, tab, project)
  await update($, captured, () => 0)
  await $.ui.open(OPEN)
}

// Claude starting on an issue in the conversation, by the issue_update tool's `start`: as Start does, the issue becomes
// the one this session is on, moves to In progress and is assigned to the person. A pull request's number starts the
// issue it is for. An epic starts its next ready sub-issue, as the Start button does.
const startHere = async ($: EngineInterface, number: number): Promise<string> => {
  const now = await read($, board)
  const pr = now?.prs.find(one => one.number === number)
  const target = pr ? pr.issues.find(one => now?.issues.some(issue => issue.number === one)) : number
  const asked = now?.issues.find(one => one.number === target)
  if (!asked) throw new Error(pr ? `pull request #${number} names no issue open on the board` : `#${number} isn't open on the board`)
  const issue = startTargetOf(now?.issues ?? [], asked, now?.project ?? null, await markersNow($, now))
  if (!issue) throw new Error(noReadyText(asked.number))
  const epic = issue.number !== asked.number ? `, the next ready sub-issue of epic #${asked.number}` : ''
  await track($, issue, true)
  await claim($, issue)
  $.ui.toast(`Working on #${issue.number} now`)
  const started = now?.project && (await mayWrite($, now.project)) ? startedOf(now.project) : undefined
  const claimed = settings.claimOnStart ? (started ? `, ${started.name} and assigned` : ', assigned') : ''
  return `Started #${issue.number}${pr ? `, the issue pull request #${number} is for` : ''}${epic}: it is the issue this session is on${claimed}.`
}

// The repo's folders, for the area labels setup suggests: its top level, and the parts under plugins/, packages/ and
// the like.
const foldersOf = async ($: EngineInterface, root: string): Promise<{ top: string[]; nested: Record<string, string[]> }> => {
  const dirs = async (path: string) => (await $.fs.list(path).catch(() => [])).filter(entry => entry.kind === 'dir').map(entry => entry.name)
  const top = await dirs(root)
  const nested: Record<string, string[]> = {}
  for (const group of ['plugins', 'packages', 'apps', 'services', 'src']) if (top.includes(group)) nested[group] = await dirs(`${root}/${group}`)
  return { top, nested }
}

// Whether the repo has an issue template with an Acceptance list already.
const hasTemplate = async ($: EngineInterface, root: string): Promise<boolean> => {
  const folder = `${root}/.github/ISSUE_TEMPLATE`
  for (const entry of await $.fs.list(folder).catch(() => [])) {
    if (entry.kind !== 'file') continue
    const text = await $.fs.read(`${folder}/${entry.name}`).catch(() => '')
    if (typeof text === 'string' && /acceptance/i.test(text)) return true
  }
  return false
}

// `/issues setup`: reads the repo, its projects, labels and open issues, and puts what it would change in the pane.
// Nothing changes until Apply.
const readSetup = async ($: EngineInterface): Promise<void> => {
  await update($, setup, () => ({ phase: 'reading' as const }))
  try {
    const repoName = (await repoNow($)).nameWithOwner
    const [owner = '', name = ''] = repoName.split('/')
    const facts = await postGraphql($, FACTS_QUERY, { owner, name })
    const pages: string[] = []
    let after: string | null = null
    do {
      const page: string = JSON.stringify({ data: await postGraphql($, ITEMS_QUERY, { owner, name, after }) })
      pages.push(page)
      after = nextItemsOf(page)
    } while (after && pages.length < PAGES)
    const root = (await $.session.repo().catch(() => null))?.root ?? (await $.session.root())
    const labels = ((facts.repository?.labels?.nodes ?? []) as { name: string }[]).map(label => label.name)
    const kept = await savedChoices($)
    const read$ = factsOf(JSON.stringify({ data: facts }), pages, suggestAreas(labels, await foldersOf($, root)), await hasTemplate($, root))
    // The project the board already reads, when setup saved one and it's still linked; else the first linked.
    const chosen = read$.projects.find(one => one.id === kept.preferred)?.id ?? read$.projects[0]?.id ?? null
    // The linked project the board may write to: the chosen one when it may write there, else the first it may.
    const grants = await grantsNow($)
    const listed = read$.projects.filter(one => grants.all.includes(projectKeyOf(one) ?? ''))
    const writes = listed.find(one => one.id === chosen) ?? listed[0]
    const granted = writes ? grants.repo.includes(projectKeyOf(writes) ?? '') : false
    const known = { ...read$, adopted: writes?.id ?? null, ...(granted ? { granted } : {}) }
    // The mapping saved for it, by an earlier setup or by /issues statuses, which setup starts from.
    const roles$ = chosen ? kept.statuses?.[chosen] : undefined
    const found = chosen && roles$ ? { ...known, saved: { project: chosen, roles: roles$ } } : known
    const areas = found.suggested.join(', ')
    const roles = picksFor(found, chosen)
    await update($, setup, () => ({ phase: 'ready' as const, facts: found, chosen, areas, roles, steps: stepsOf(found, chosen, areas, roles) }))
  } catch (cause) {
    const message = messageOf(cause)
    await update($, setup, () => ({ phase: 'failed' as const, message }))
    if (ACCESS_ERROR.test(message) || PROJECT_REFUSED.test(message)) void checkAccess($, message)
  }
}

// Apply: each step in turn, marked running, done, failed or skipped as it goes, so the pane shows how far it got. A step
// that fails doesn't stop the ones after it, save those that need what it would have made.
const applySetup = async ($: EngineInterface): Promise<void> => {
  const now = await read($, setup)
  if (now?.phase !== 'ready') return
  const { facts } = now
  const mark = (id: SetupStep['id'], state: NonNullable<SetupStep['state']>, message?: string) =>
    update($, setup, was => (was && 'steps' in was ? { ...was, steps: was.steps.map(step => (step.id === id ? { ...step, state, ...(message ? { message } : {}) } : step)) } : was))
  const run = async (id: SetupStep['id'], work: () => Promise<unknown>): Promise<void> => {
    if (!now.steps.some(step => step.id === id)) return
    await mark(id, 'running')
    try {
      await work()
      await mark(id, 'done')
    } catch (cause) {
      await mark(id, 'failed', messageOf(cause))
    }
  }
  const reread = async (id: string): Promise<SetupProject> => projectOf((await postGraphql($, PROJECT_QUERY, { id })).node)
  await update($, setup, was => (was?.phase === 'ready' ? { ...was, phase: 'applying' as const } : was))

  let project: SetupProject | null = facts.projects.find(one => one.id === now.chosen) ?? null
  // First, since the steps that change the project go through the board's write check. Pressing Apply on the plan that
  // says so is the person letting the board write to the project.
  const chosen = project
  // The project Apply adopted, whose setting it writes once its steps are done.
  let adopted: { number: number; title: string } | null = null
  if (chosen) {
    await run('adopt', async () => {
      await adoptProject($, chosen, true)
      adopted = chosen
    })
  }
  await run('issues', async () => {
    await gh($, ['repo', 'edit', facts.repo.name, '--enable-issues'])
    // The repo read setup used says issues are off, so the next read asks GitHub again.
    repoInfo = undefined
  })
  await run('project', async () => {
    const title = facts.repo.name.split('/')[1] ?? facts.repo.name
    const made = await projectWrite($, 'new', CREATE_PROJECT, { owner: facts.repo.ownerId, title, repo: facts.repo.id })
    project = await reread(made.createProjectV2.projectV2.id)
    // The person asked setup to make it, so the board may write to it, which the steps after need.
    await adoptProject($, project, true)
    adopted = project
  })
  // Without a project, the steps that work in one can't run.
  const needsProject = ['status', 'priority', 'items', 'inbox'] as const
  if (!project) {
    for (const id of needsProject) if (now.steps.some(step => step.id === id)) await mark(id, 'skipped', 'There is no project to change.')
  } else {
    let current: SetupProject = project
    await run('status', async () => {
      if (!current.status) throw new Error('the project has no Status field')
      const { options } = mergeStatuses(current.status.options, now.roles)
      await projectWrite($, current, UPDATE_FIELD, { field: current.status.id, options: options.map(one => ({ ...(one.id ? { id: one.id } : {}), name: one.name, color: one.color, description: one.description })) })
      current = await reread(current.id)
    })
    // The roles are saved with the rest once Apply ends.
    await run('roles', async () => undefined)
    await run('priority', async () => {
      await projectWrite($, current, CREATE_FIELD, { project: current.id, name: 'Priority', options: PRIORITIES })
      current = await reread(current.id)
    })
    // Each open issue's item in the project, the ones already there and the ones added now.
    const items = new Map(facts.issues.flatMap(issue => issue.items.filter(item => item.project === current.id).map(item => [issue.number, item] as const)))
    await run('items', async () => {
      for (const issue of facts.issues) {
        if (items.has(issue.number)) continue
        const added = await projectWrite($, current, ADD_ITEM, { project: current.id, content: issue.id })
        items.set(issue.number, { project: current.id, item: added.addProjectV2ItemById.item.id, status: null })
      }
    })
    await run('inbox', async () => {
      const picked = now.roles.inbox
      const inbox = picked === null ? undefined : current.status?.options.find(option => option.name.toLowerCase() === picked.toLowerCase())
      if (!current.status || !inbox?.id) throw new Error(`the project has no ${picked ?? 'Inbox'} status`)
      for (const { item, status } of items.values()) {
        if (status) continue
        await projectWrite($, current, SET_FIELD, { project: current.id, item, field: current.status.id, option: inbox.id })
      }
    })
    project = current
  }
  await run('bug', () => gh($, ['label', 'create', 'bug', '-R', facts.repo.name, '--color', 'd73a4a', '--description', "Something isn't working"]))
  await run('areas', async () => {
    for (const area of areasOf(now.areas, facts.labels)) {
      await gh($, ['label', 'create', `area:${area}`, '-R', facts.repo.name, '--color', '1d76db', '--description', `The ${area} part`])
    }
  })

  // The board reads the project setup ended with from now on, and knows which Status means what.
  const ended: SetupProject | null = project
  if (ended) {
    const status = ended.status
    await changeChoices($, was => ({
      ...was,
      preferred: ended.id,
      ...(status ? { statuses: { ...(was.statuses ?? {}), [ended.id]: rolesOf(status.options, now.roles) } } : {}),
    }))
  }
  // The project Apply adopted, in the setting now that its steps are done.
  // Set inside the steps' callbacks, which the compiler can't follow.
  const wrote = adopted as { number: number; title: string } | null
  if (wrote) {
    try {
      await writeSetting($, (await grantsNow($)).own)
    } catch (cause) {
      $.ui.toast(`Couldn't save that the board may write to ${wrote.title}: ${messageOf(cause)}`)
    }
  }
  // Done: the pane shows the project as it now is, a new one included, so its automations still off can be linked.
  const adoptedId = (await adoptedNow($))?.id ?? null
  await update($, setup, was =>
    was?.phase === 'applying'
      ? {
          ...was,
          phase: 'done' as const,
          ...(ended
            ? {
                chosen: ended.id,
                facts: {
                  ...was.facts,
                  projects: [...was.facts.projects.filter(one => one.id !== ended.id), ended],
                  adopted: adoptedId,
                  ...(ended.status ? { saved: { project: ended.id, roles: rolesOf(ended.status.options, now.roles) } } : {}),
                },
              }
            : {}),
        }
      : was,
  )
  projectRefusal = undefined
  void refresh($)
}

// A Status or Priority picked on a card.
const pick = async ($: EngineInterface, issue: Issue, field: 'status' | 'priority', name: string): Promise<void> => {
  try {
    await setField($, issue, field, name)
    $.ui.toast(`#${issue.number} is ${name} now`)
  } catch (cause) {
    toastFailure($, `Couldn't change #${issue.number}`, cause)
  }
}

// Reads GitHub again straight after a change, waiting out a refresh already under way, which may have read GitHub
// before the change. `seen`: the change was the person's or Claude's own, so the band doesn't call it news.
const refreshAfter = async ($: EngineInterface): Promise<void> => {
  await settle($)
  await refresh($, true)
}

// Waits out a refresh under way, up to ten seconds.
const settle = async ($: EngineInterface): Promise<void> => {
  for (let tries = 0; tries < 50 && refreshing; tries += 1) await $.clock.sleep(200)
}

// The issue Claude is on, when this session started it: the one the notes and the next step are about.
const doingHere = async ($: EngineInterface): Promise<Working | null> => {
  const doing = await read($, working)
  return doing?.sessionId && doing.sessionId === (await $.session.id().catch(() => undefined)) ? doing : null
}

// The board's copy of the issue Claude is on, as Claude's own change to it begins; null before Claude knows it.
const copyOf = async ($: EngineInterface): Promise<Known | null> => {
  const now = await read($, board)
  const doing = await read($, working)
  return now && doing?.known ? knownOf(now.issues.find(one => one.number === doing.number), now.prs) : null
}

// Claude's own change to the issue it is on isn't news to it: what changed from `before` to `after` (the board's copy
// now, when not given) goes into what Claude knows.
const absorb = async ($: EngineInterface, before: Known | null, after?: Known): Promise<void> => {
  const now = await read($, board)
  if (!now || !before) return
  await update($, working, was =>
    was?.known ? { ...was, known: absorbed(was.known, before, after ?? knownOf(now.issues.find(one => one.number === was.number), now.prs)) } : was,
  )
  await save($)
}

// The comments of an issue, when the board counts more than Claude knows of; none when gh can't say in ten seconds,
// and the note then says how to read them.
const newComments = async ($: EngineInterface, number: number, was: Known, now: Known): Promise<Comment[]> => {
  if (now.comments === null || was.comments === null || now.comments <= was.comments) return []
  try {
    return commentsOf(await gh($, ['issue', 'view', String(number), '--json', 'comments'], undefined, 10_000))
  } catch {
    return []
  }
}

// What changed on GitHub to the issue Claude is on since its last prompt, as a note for the next one; what Claude knows
// then moves on to the board's copy. Null with nothing to say, or before Claude knows anything of it.
const newsFor = async ($: EngineInterface, now: Board): Promise<string | null> => {
  const doing = await doingHere($)
  if (!doing) return null
  const current = knownOf(now.issues.find(one => one.number === doing.number), now.prs)
  const note = doing.known ? newsOf(doing.number, doing.known, current, await newComments($, doing.number, doing.known, current)) : null
  if (JSON.stringify(doing.known) !== JSON.stringify(current)) {
    await update($, working, was => (was?.number === doing.number ? { ...was, known: current } : was))
    await save($)
  }
  return note
}

// Start makes a task in Claude's task list for each open box that has none yet, so the list follows the issue; when
// Claude completes one, the band asks whether to tick its box. Answers how many tasks the issue has: none where the
// session keeps no task list.
const makeTasks = async ($: EngineInterface, issue: Issue): Promise<number> => {
  const had = (await read($, tasks)).filter(one => one.number === issue.number)
  const made: BoxTask[] = []
  for (const [index, check] of issue.checks.entries()) {
    if (check.done || had.some(one => one.text === check.text)) continue
    try {
      const answer = await $.tool.call({
        tool: 'TaskCreate',
        subject: fit(check.text, 80),
        description: `Box ${index + 1} of #${issue.number}, ${issue.title}: ${check.text}`,
        metadata: { issue: issue.number, box: index + 1 },
      })
      const id = answer.deny === undefined && !answer.isError ? (answer.result as { task?: { id?: unknown } } | undefined)?.task?.id : undefined
      if (typeof id !== 'string') break
      made.push({ id, number: issue.number, box: index + 1, text: check.text, done: false })
    } catch (cause) {
      $.ui.log(`issue-board: couldn't make a task for a box of #${issue.number}: ${messageOf(cause)}`, { to: 'debug' })
      break
    }
  }
  if (made.length > 0) await update($, tasks, list => [...list, ...made])
  return had.length + made.length
}

// After Claude's turn: the board looks at GitHub again if Claude ran git or gh since it last did, reading in full only
// when the cheap checks see a change (a write to GitHub reads at once by itself). Then the prompt box suggests the next
// step for the issue Claude is on, such as opening its pull request once every box is ticked.
const afterTurn = async ($: EngineInterface): Promise<void> => {
  await settle($)
  if (touches > readTouches) await poll($)
  const now = await read($, board)
  // Turned off, the prompt box keeps Claude Code's own suggestion.
  const step = now && settings.suggestNextStep ? nextStepOf(now, await doingHere($)) : null
  nextStep = step
  // The box takes a suggestion once the turn has wound down: a few tries, while no new prompt has come.
  for (let tries = 0; step && nextStep === step && tries < 3; tries += 1) {
    if ((await $.prompt.suggest({ text: step }).catch(() => ({ isShown: false }))).isShown) break
    await $.clock.sleep(1000)
  }
}

// A GitHub event for a subscribed pull request (CI finished, merged, reviewed, commented): the board reads GitHub at
// once, when the event is about this repo, rather than at its next poll.
const eventArrived = async ($: EngineInterface, data: Record<string, unknown>): Promise<void> => {
  const repo = (await read($, board))?.repo
  const named = eventRepoOf(data)
  if (!repo || (named && named.toLowerCase() !== repo.toLowerCase())) return
  await settle($)
  await refresh($)
}

// The CI runs being watched, by id: one `gh run watch` each, for as long as the run goes. Unloading the module ends
// them, and a new load starts with none.
const watching = new Set<number>()

// Looks for CI runs under way on the branch checked out, and watches each it isn't watching yet. Answers whether any is
// under way.
const watchRuns = async ($: EngineInterface): Promise<boolean> => {
  const here = await read($, branch)
  if (!here) return false
  try {
    const live = liveRunsOf(await gh($, ['run', 'list', '--branch', here, '--limit', '10', '--json', 'databaseId,status,workflowName']))
    for (const run of live.slice(0, 3)) if (!watching.has(run.id)) void watchRun($, run, here)
    return live.length > 0
  } catch (cause) {
    $.ui.log(`issue-board: couldn't list the CI runs on ${here}: ${messageOf(cause)}`, { to: 'debug' })
    return false
  }
}

// A push starts CI a few seconds later: the board looks a few times, until a run turns up.
const lookForRuns = async ($: EngineInterface): Promise<void> => {
  try {
    for (let tries = 0; tries < 4; tries += 1) {
      await $.clock.sleep(15_000)
      if (await watchRuns($)) return
    }
  } catch {
    // The module unloaded while it waited: the next load looks again when CI shows as running.
  }
}

// Watches one run with `gh run watch`, which draws it again every 15 seconds until it ends: each drawing updates the
// run's progress on the board. Its end reads GitHub again, so the pull request shows how it went. Each drawing costs
// about three REST calls, from the same hourly limit as the cheap checks, so it doesn't draw more often.
const watchRun = async ($: EngineInterface, run: { id: number; workflow: string }, runBranch: string): Promise<void> => {
  watching.add(run.id)
  const fresh: RunWatch = { id: run.id, workflow: run.workflow, branch: runBranch, done: 0, total: 0, failed: 0, running: null, step: null }
  await update($, runs, list => [...list.filter(one => one.id !== run.id), fresh])
  try {
    let seen = ''
    for await (const { text } of $.process.spawn({ argv: ['gh', 'run', 'watch', String(run.id), '--interval', '15'] })) {
      // Each drawing opens with this line, and counts as the three REST calls it takes.
      const drawings = text.match(/Refreshing run status/g)?.length ?? 0
      for (let call = 0; call < drawings * 3; call++) countCall(stats, 'other', 'rest')
      seen = (seen + text).slice(-20_000)
      const progress = runProgressOf(seen)
      if (progress) await update($, runs, list => list.map(one => (one.id === run.id ? { ...one, ...progress } : one)))
    }
  } catch (cause) {
    $.ui.log(`issue-board: couldn't watch CI run ${run.id}: ${messageOf(cause)}`, { to: 'debug' })
  } finally {
    watching.delete(run.id)
    await update($, runs, list => list.filter(one => one.id !== run.id))
    await settle($)
    await refresh($)
  }
}

// While a background agent works, the board asks where each stands every 10 seconds, and stops once none works. An
// agent the list shows ended may still answer; when no answer has come 10 seconds later, the board says how it ended
// without one.
let workerTimer: Timer | undefined
const checkWorkers = async ($: EngineInterface): Promise<void> => {
  const listed = await $.agent.list().catch(() => [])
  const moved = (await read($, workers)).flatMap(one => {
    const info = listed.find(agent => agent.id === one.agentId)
    return info && one.status !== info.status && ACTIVE.includes(one.status) ? [{ agentId: one.agentId, status: info.status }] : []
  })
  if (moved.length > 0) await update($, workers, list => list.map(one => ({ ...one, status: moved.find(to => to.agentId === one.agentId)?.status ?? one.status })))
  for (const { agentId, status } of moved) {
    if (status === 'completed' || status === 'failed' || status === 'killed') $.clock.after(10_000, () => void handOff($, agentId, status, null))
  }
  if (!(await read($, workers)).some(one => ACTIVE.includes(one.status))) {
    workerTimer?.cancel()
    workerTimer = undefined
  }
}
const pollWorkers = ($: EngineInterface): void => {
  if (!workerTimer) workerTimer = $.clock.every(10_000, () => void checkWorkers($))
}

// The Starts pressed and not yet under way, read at once so a second press finds the first; `launching` draws them.
const pressed = new Set<string>()

// A Start on an issue is under way, or failed to get there: its button comes back.
const landed = async ($: EngineInterface, number: number, how: Launch['how']): Promise<void> => {
  pressed.delete(`${how}-${number}`)
  await update($, launching, list => list.filter(one => one.number !== number || one.how !== how))
}

// A Start on an issue, from the press until the work is under way: its button says so meanwhile, and another press of
// it does nothing. `work` resolves true once the work is under way, or false when it waits on something else to land it.
const launch = async ($: EngineInterface, issue: Issue, how: Launch['how'], work: () => Promise<boolean>): Promise<void> => {
  const key = `${how}-${issue.number}`
  if (pressed.has(key)) return
  pressed.add(key)
  await update($, launching, list => [...list, { number: issue.number, how }])
  let done = true
  try {
    done = await work()
  } finally {
    if (done) await landed($, issue.number, how)
  }
}

// Whether the start message Edit first fills for the issue will go with the board's copy of it: copies are on and the
// board has the issue. The person sends it, so the prompt.submit hook sees it, and the message leaves the boxes to the
// copy.
const copyGoes = async ($: EngineInterface, issue: Issue): Promise<boolean> => {
  if (!settings.issueCopies) return false
  const now = await read($, board)
  return now ? copyKeyOf(now, issue.number) !== null : false
}

// The person's own prompt, sent after Edit first filled the box with Start's message: when it still names the issue,
// the issue becomes the one Claude is on and gets its tasks, as Start does. Rewritten so it no longer names the issue,
// it is a plain prompt. Answers the issue started, and whether it has tasks, for the hook to claim once it is sent.
const draftedStart = async ($: EngineInterface, e: { text: string; origin: { kind: string } }): Promise<{ issue: Issue; listed: boolean } | null> => {
  if (e.origin.kind !== 'composer' && e.origin.kind !== 'bridge') return null
  const number = await read($, drafted)
  if (number === null) return null
  await update($, drafted, () => null)
  const issue = (await read($, board))?.issues.find(one => one.number === number)
  if (!issue || !namesIssue(e.text, number)) return null
  // The message leans on the issue's copy for its boxes, so it carries a fresh one even if an earlier prompt did.
  sentCopies.delete(number)
  try {
    await track($, issue, true)
    return { issue, listed: (await makeTasks($, issue)) > 0 }
  } catch (cause) {
    $.ui.log(`issue-board: couldn't start #${number} from its edited message: ${messageOf(cause)}`, { to: 'debug' })
    return null
  }
}

// Start in background: the board starts an agent of its own type on the issue, to work it in a git worktree of its own,
// in the background, and leave a pull request. Claude gets no message: the agent's prompt goes to the agent alone. The
// button says it is starting until the agent starts or the spawn is refused or fails, which a toast explains. Once it
// starts, the issue's row follows it, and the issue moves to In progress and is assigned, as Start does.
const startInBackground = ($: EngineInterface, issue: Issue): Promise<void> =>
  launch($, issue, 'background', async () => {
    const description = `#${issue.number} ${issue.title}`
    let started: AgentSpawnResult
    try {
      started = await $.agent.spawn({ subagentType: WORKER, description, prompt: startPrompt(issue) })
    } catch (cause) {
      $.ui.toast(`Couldn't start a background agent on #${issue.number}: ${messageOf(cause)}`)
      return true
    }
    if (started.deny !== undefined) {
      $.ui.toast(`Couldn't start a background agent on #${issue.number}: ${started.deny}`)
      return true
    }
    try {
      const agentId = started.agentId ?? (await workerIdOf($, description))
      if (!agentId) throw new Error('no agent id')
      await workerStarted($, issue.number, agentId, false)
    } catch (cause) {
      $.ui.toast(`Started a background agent on #${issue.number}, but the board couldn't follow it: ${messageOf(cause)}`)
    }
    await claim($, issue)
    return true
  })

// The id of a board agent that just started, when core didn't name it: the session's list does, by the name it was
// given, or by its description when it has none. An earlier agent on the issue may match too, so one that hasn't ended
// comes first.
const workerIdOf = async ($: EngineInterface, description: string, name?: string): Promise<string | undefined> => {
  const matching = (await $.agent.list()).filter(agent => agent.type === WORKER && (name ? agent.name === name : agent.description === description))
  return (matching.findLast(agent => !['completed', 'failed', 'killed'].includes(agent.status)) ?? matching.at(-1))?.id
}

// A spawn of the board's agent, by Claude or anyone: once it starts, the issue's row follows it.
const workerStarted = async ($: EngineInterface, number: number, agentId: string, byClaude: boolean): Promise<void> => {
  const title = (await read($, board))?.issues.find(one => one.number === number)?.title
  const worker: Worker = { number, ...(title ? { title } : {}), agentId, status: 'running', startedAt: Date.now(), answer: null, ...(byClaude ? { byClaude } : {}) }
  await update($, workers, list => [...list.filter(one => one.number !== number), worker])
  pollWorkers($)
  $.ui.toast(`Started a background agent on #${number}`)
}

// A background agent's answer is its loop's last turn: it is done, stopped or failed.
const workerEnded = ($: EngineInterface, agentId: string, answer: string, reason: string): Promise<void> =>
  handOff($, agentId, reason === 'answer' ? 'completed' : reason === 'aborted' ? 'killed' : 'failed', answer)

// The agents whose end the conversation was told of, read at once so the answer and the list's word don't both tell it.
const told = new Set<string>()

// A background agent ended: the board reads GitHub, where it may have opened a pull request, then a line in the
// conversation tells the person how it ended, with what it said and its pull request. When something other than
// Claude's own Agent tool call started it, Claude gets the same as a prompt of the board's, so it can follow up; when
// Claude started it, Claude Code already gives Claude its result, and a second message would only repeat it. An agent
// the board spawned itself gets no task notification from Claude Code, so the hand-off keeps the start of its answer.
const handOff = async ($: EngineInterface, agentId: string, status: Ended, answer: string | null): Promise<void> => {
  if (told.has(agentId)) return
  told.add(agentId)
  const worker = (await read($, workers)).find(one => one.agentId === agentId)
  if (!worker || worker.told) return
  const said = answer?.trim() || null
  await update($, workers, list => list.map(one => (one.agentId === agentId ? { ...one, status, answer: said ? fit(said, 600) : one.answer, told: true } : one)))
  $.ui.toast(`The background agent on #${worker.number} ${status === 'completed' ? 'finished' : status === 'killed' ? 'was stopped' : 'failed'}`)
  await settle($)
  await refresh($)
  const now = await read($, board)
  const issue = { number: worker.number, title: worker.title ?? now?.issues.find(one => one.number === worker.number)?.title ?? '' }
  const pr = workerPrOf(worker.number, now?.prs ?? [], said ?? '')
  $.ui.log(endedLine(issue, status, said, pr))
  if (worker.byClaude) return
  try {
    const sent = await submit($, 'hand-offs', { text: handoffPrompt(issue, status, said, pr, settings.startMode) })
    if (sent.drop !== undefined) throw new Error(sent.drop)
  } catch (cause) {
    $.ui.log(`issue-board: couldn't tell Claude the background agent on #${worker.number} ended: ${messageOf(cause)}`, { to: 'debug' })
  }
}

// The task Claude completed, its box ticked from the band.
const tickTask = async ($: EngineInterface, task: BoxTask): Promise<void> => {
  const issue = (await read($, board))?.issues.find(one => one.number === task.number)
  const at = issue && boxOf(issue, task)
  try {
    if (!at) throw new Error(`#${task.number} has no box "${fit(task.text, 40)}" open on the board`)
    await tick($, task.number, [at.box], true)
    await update($, tasks, list => list.filter(one => one.id !== task.id))
    $.ui.toast(`Ticked box ${at.box} on #${task.number}`)
  } catch (cause) {
    toastFailure($, `Couldn't tick the box on #${task.number}`, cause)
  }
}

// An issue the board doesn't hold, such as one a merge just closed: its node and its item in the board's project, read
// from GitHub. It has no item when it was never in the project; setting a field adds it.
const offBoard = async ($: EngineInterface, number: number): Promise<Target> => {
  const project = (await read($, board))?.project
  if (!project) throw new Error("the board reads no project for this repo, so it can't set its fields")
  const { id } = JSON.parse(await gh($, ['issue', 'view', String(number), '--json', 'id'])) as { id: string }
  const found = (await postGraphql($, ISSUE_ITEMS, { issue: id })) as { node?: { projectItems?: { nodes?: { id: string; project: { id: string } }[] } } }
  return { number, id, item: found.node?.projectItems?.nodes?.find(one => one.project.id === project.id)?.id ?? null }
}

// Makes a change to an issue, from its card or from Claude's issue_update tool: Status and Priority in the project,
// then the gh edit, comment and close, then the board read again so it shows. Answers what it did. A plan makes many
// changes and reads the board once after them all, so it passes `refresh` false.
const applyChanges = async ($: EngineInterface, number: number, changes: IssueChanges, refresh$ = true): Promise<string> => {
  const issue = (await read($, board))?.issues.find(one => one.number === number)
  const fields = changes.fields && Object.keys(changes.fields).length > 0 ? changes.fields : null
  // A closed issue is set through its item in the project all the same. Its Status or Priority may already be what was
  // asked, as when the board moved it to Done as it closed: that is said, and nothing is written.
  const target = issue ?? (changes.status || changes.priority || fields ? await offBoard($, number) : null)
  const current = !issue && target?.item ? itemValuesOf(await postGraphql($, ITEM_VALUES, { item: target.item })) : {}
  const already: string[] = []
  const skipped: ('status' | 'priority')[] = []
  for (const field of ['status', 'priority'] as const) {
    const value = changes[field]
    if (!value || !target) continue
    const name = field === 'status' ? 'Status' : 'Priority'
    if (current[name] && current[name].toLowerCase() === value.toLowerCase()) {
      already.push(`#${number}'s ${name} is already ${current[name]}.`)
      skipped.push(field)
      continue
    }
    await setField($, target, field, value)
  }
  if (fields && target) await setFields($, target, fields)
  const repo = (await read($, board))?.repo
  if (repo && (changes.title || changes.body !== undefined || changes.addBoxes?.length || changes.rewordBoxes?.length)) await rewrite($, repo, number, changes)
  const made = repo && changes.addLabels?.length ? await ensureLabels($, repo, changes.addLabels) : []
  if (repo && changes.transferTo) {
    changes.transferTo = sameOwner(repo, changes.transferTo)
    // GitHub moves an issue from a public repo to a private one, but not back: that takes a second, confirmed call.
    const [from, to] = await Promise.all([repo, changes.transferTo].map(async one => (await gh($, ['api', `repos/${one}`, '--jq', '.private'])).trim() === 'true'))
    if (!from && to && !changes.confirmTransfer) {
      throw new Error(`${changes.transferTo} is private and ${repo} is public, so GitHub won't move #${number} back once it's there. Call again with confirmTransfer: true to move it anyway`)
    }
  }
  for (const command of commandsOf(number, changes, repo)) await gh($, command.argv, command.stdin)
  if (changes.transferTo) {
    await update($, board, was => was && { ...was, issues: was.issues.filter(one => one.number !== number) })
    await save($)
  }
  if (repo && changes.type !== undefined) await setType($, repo, number, changes.type)
  if (repo && (changes.moveBefore || changes.moveAfter)) await reorder($, repo, number, (changes.moveBefore ?? changes.moveAfter) as number, Boolean(changes.moveBefore))
  if (changes.projectAfter !== undefined) await moveInProject($, number, changes.projectAfter || null, false)
  if (repo && changes.duplicateOf) await closeAsDuplicate($, repo, number, changes.duplicateOf)
  if (repo && changes.addBlockedBy?.length) await block($, repo, number, changes.addBlockedBy, true)
  if (repo && changes.removeBlockedBy?.length) await block($, repo, number, changes.removeBlockedBy, false)
  if (refresh$) await refreshAfter($)
  const left = { ...changes }
  for (const field of skipped) delete left[field]
  const done = changesText(number, left)
  const said = [...already, ...(already.length > 0 && done.startsWith('Nothing to change') ? [] : [done])].join(' ')
  return `${said}${made.length > 0 ? ` Created the ${made.length === 1 ? 'label' : 'labels'} ${made.join(', ')}, new to the repo.` : ''}`
}

// A change made on a card: said in a toast, and an error that may be a missing permission checked.
const change = async ($: EngineInterface, number: number, changes: IssueChanges): Promise<void> => {
  try {
    $.ui.toast(await applyChanges($, number, changes))
  } catch (cause) {
    toastFailure($, `Couldn't change #${number}`, cause)
  }
}

// The plan project_plan's input asks for, checked against the board as it is now. A plan that changes the project is
// refused here, before anything is asked, when the board may not write to it; each write checks again as it goes.
// `count` has each label delete count the issues that carry the label, for its row on the card.
const planFor = async ($: EngineInterface, input: unknown, count = false): Promise<Planned> => {
  const now = await read($, board)
  if (!now) return { problems: [NOT_READ_SENTENCE] }
  const refusal = await boardRefusal($, now)
  const planned = planOf(input, { issues: now.issues, project: now.project, milestones: now.milestones, refusal, labels: now.labels, markers: await read($, chosenMarkers) })
  if (!count || 'problems' in planned) return planned
  const changes = await Promise.all(
    planned.changes.map(async one => (one.change.kind === 'label' && one.change.action === 'delete' ? { ...one, change: { ...one.change, uses: await labelUses($, now.repo, one.change.name) } } : one)),
  )
  return { changes }
}

// How many open and closed issues carry a label, from GitHub's search counts; null when it couldn't count.
const labelUses = async ($: EngineInterface, repo: string, name: string): Promise<{ open: number; closed: number } | null> => {
  try {
    const [open, closed] = await Promise.all(
      (['open', 'closed'] as const).map(async state =>
        Number((await gh($, ['api', '-X', 'GET', 'search/issues', '-f', `q=repo:${repo} is:issue state:${state} label:"${name.replace(/"/g, '')}"`, '-f', 'per_page=1', '--jq', '.total_count'])).trim()),
      ),
    )
    return Number.isFinite(open) && Number.isFinite(closed) ? { open: open as number, closed: closed as number } : null
  } catch (cause) {
    $.ui.log(`issue-board: couldn't count the issues with the label ${name}: ${messageOf(cause)}`, { to: 'debug' })
    return null
  }
}

// Makes, edits or deletes one of the repo's labels over REST, then moves or clears the saved markers that go by it and
// keeps the card's label picker in step. GitHub keeps a renamed label on its issues. Answers what it did.
const applyLabel = async ($: EngineInterface, change: LabelChange): Promise<string> => {
  const repo = (await read($, board))?.repo
  if (!repo) throw new Error(NOT_READ)
  const path = `repos/${repo}/labels/${encodeURIComponent(change.name)}`
  const fields = [
    ...(change.rename ? ['-f', `new_name=${change.rename}`] : []),
    ...(change.color ? ['-f', `color=${change.color}`] : []),
    ...(change.description !== undefined ? ['-f', `description=${change.description}`] : []),
  ]
  let done: string
  if (change.action === 'create') {
    const color = change.color ?? labelColorFor(change.name, ((await read($, board))?.labels ?? []).map(name => ({ name })))
    await gh($, ['api', '-X', 'POST', `repos/${repo}/labels`, '-f', `name=${change.name}`, '-f', `color=${color}`, ...(change.description !== undefined ? ['-f', `description=${change.description}`] : [])])
    done = `Created the label ${change.name}.`
  } else if (change.action === 'delete') {
    await gh($, ['api', '-X', 'DELETE', path])
    done = `Deleted the label ${change.name}.`
  } else {
    await gh($, ['api', '-X', 'PATCH', path, ...fields])
    done = `${change.rename ? `Renamed the label ${change.name} to ${change.rename}` : `Changed the label ${change.name}`}${change.color ? `, its color now #${change.color}` : ''}.`
  }
  const markers = change.markers ?? []
  if (markers.length > 0) {
    const to = change.action === 'edit' ? change.rename : undefined
    await changeChoices($, was => {
      const saved = { ...(was.markers ?? {}) }
      if (markers.includes('bug')) {
        if (to) saved.bug = { label: to }
        else delete saved.bug
      }
      if (markers.includes('later')) {
        if (to) saved.later = to
        else delete saved.later
      }
      return { ...was, markers: saved }
    })
    const names = markers.map(one => (one === 'bug' ? 'Bugs' : 'Later')).join(' and ')
    done += to ? ` The saved ${names} marker goes by ${to} now.` : ` The saved ${names} marker is cleared, so the board guesses it again.`
  }
  await update($, palette, was => {
    if (!was) return was
    const kept = was.labels.filter(name => change.action === 'create' || name.toLowerCase() !== change.name.toLowerCase())
    const added = change.action === 'create' ? [change.name] : change.rename ? [change.rename] : change.action === 'edit' ? [change.name] : []
    return { ...was, labels: [...new Set([...kept, ...added])].sort() }
  })
  return done
}

// Makes a plan's change to one of the project's views, through the project write check. An existing view is found by
// its number, as the board read it. A new view's filter goes in by a change straight after it is made, since creating
// takes none. The board's next read has the views, so the pane's tabs show them. Answers what it did.
const applyView = async ($: EngineInterface, change: ViewChange): Promise<string> => {
  const project = (await read($, board))?.project
  if (!project) throw new Error("the board reads no project for this repo, so it can't change its views")
  const { view, to } = change
  let id: string | undefined
  if (view) {
    const found = (await postGraphql($, VIEW_ID, { project: project.id, number: view.number })) as { node?: { view?: { id?: string } | null } | null }
    id = found.node?.view?.id
    if (!id) throw new Error(`${project.title} has no view ${view.name} any more`)
  }
  if (!to) {
    await projectWrite($, project, DELETE_VIEW, { view: id ?? '' })
    return viewDoneText(change)
  }
  if (!id) {
    const made = (await projectWrite($, project, CREATE_VIEW, { input: { projectId: project.id, name: to.name, layout: LAYOUT_NAMES[to.layout] } })) as {
      createProjectV2View?: { projectV2View?: { id?: string } | null } | null
    }
    const madeId = made.createProjectV2View?.projectV2View?.id
    if (to.filter && !madeId) throw new Error(`GitHub made the view ${to.name} but didn't say which it is, so its filter isn't set`)
    if (to.filter && madeId) await projectWrite($, project, UPDATE_VIEW, { input: { viewId: madeId, filter: to.filter } })
    return viewDoneText(change)
  }
  const was = view as NonNullable<typeof view>
  const input = {
    viewId: id,
    ...(to.name !== was.name ? { name: to.name } : {}),
    ...(to.layout !== was.layout ? { layout: LAYOUT_NAMES[to.layout] } : {}),
    ...(to.filter !== was.filter ? { filter: to.filter } : {}),
  }
  await projectWrite($, project, UPDATE_VIEW, { input })
  return viewDoneText(change)
}

// Puts a plan on the pane's card, every row ticked, in place of any plan before it. Answers its id, which tells it from
// the plan that may replace it while the permission prompt waits.
const propose = async ($: EngineInterface, changes: Extract<Planned, { changes: unknown }>['changes']): Promise<number> => {
  const id = ((await read($, proposal))?.id ?? 0) + 1
  await update($, proposal, () => ({ id, rows: rowsOf(changes), applying: false, note: null }))
  return id
}

// Applies the plan's ticked rows in order, each the way issue_update makes that change, through the project write check
// for the project's fields. The board is read once, after them all. Rows that went through leave the card, as do rows
// left unticked; a row that failed stays, ticked, with why, and the card says how it went. A ticked row the board shows
// as made already, as when Claude made it another way after proposing the plan, is skipped and named. Answers what
// happened.
const applyPlan = async ($: EngineInterface, id: number): Promise<string> => {
  const now = await read($, proposal)
  if (!now || now.id !== id) return 'That plan is gone: it was applied, discarded or replaced meanwhile.'
  if (now.applying) return 'That plan is being applied already.'
  const picked = now.rows.filter(row => row.picked)
  if (picked.length === 0) return 'No change of the plan is ticked, so nothing was applied.'
  const mine = (was: Plan | null): was is Plan => was !== null && was.id === id
  const current = await read($, board)
  const chosen = current ? rowsToMake(picked, current) : picked
  const skipped = picked.filter(row => !chosen.includes(row))
  if (chosen.length === 0) {
    await update($, proposal, was => (mine(was) ? null : was))
    return appliedText([], [], skipped)
  }
  await update($, proposal, was => (mine(was) ? { ...was, applying: true, note: null } : was))
  const done: string[] = []
  const failed: { row: PlanRow; message: string }[] = []
  try {
    for (const row of chosen) {
      try {
        const change = row.change
        done.push(
          change.kind === 'label' ? await applyLabel($, change) : change.kind === 'view' ? await applyView($, change) : await applyChanges($, change.number, issueChangesOf(change), false),
        )
      } catch (cause) {
        failed.push({ row, message: messageOf(cause) })
      }
    }
    await refreshAfter($)
  } finally {
    await update($, proposal, was => (mine(was) && was.applying ? { ...was, applying: false } : was))
  }
  const text = appliedText(done, failed, skipped)
  await update($, proposal, was => (mine(was) ? (failed.length === 0 ? null : { ...was, rows: failed.map(({ row, message }) => ({ ...row, failed: message })), note: text.split('\n')[0] ?? null }) : was))
  const access$ = failed.find(one => ACCESS_ERROR.test(one.message))
  if (access$) void checkAccess($, access$.message)
  return text
}

// Apply on the plan card: the person's own press, so it asks nothing more. A toast says how it went.
const applyFromCard = async ($: EngineInterface, id: number): Promise<void> => {
  try {
    $.ui.toast((await applyPlan($, id)).split('\n')[0] ?? '')
  } catch (cause) {
    $.ui.toast(`Couldn't apply the plan: ${messageOf(cause)}`)
  }
}

// How many Inbox issues one ask covers; more are asked about in turn.
const TRIAGE_BATCH = 15

// The repo's areas, the `area:` labels without the prefix: from the labels the board's last read had, else as GitHub
// lists them, else the ones on the board's issues.
const repoAreas = async ($: EngineInterface, now: Board): Promise<string[]> => {
  const names =
    now.labels ??
    (await repoLabels($, now.repo)
      .then(list => list.map(one => one.name))
      .catch(() => labelsOf(now.issues)))
  return names.filter(name => name.startsWith('area:')).map(name => name.slice('area:'.length)).sort()
}

// Asks Claude for a Priority, an area and a Status for each issue in the Inbox it has no suggestion for since the issue
// last changed, a batch at a time. One ask at a time; the pane shows the suggestions as they come.
let suggesting = false
const suggestInbox = async ($: EngineInterface): Promise<void> => {
  if (suggesting) return
  suggesting = true
  try {
    for (;;) {
      const now = await read($, board)
      const project = now?.project
      if (!now || !project) return
      const known = (await read($, triage)).suggestions
      const due = now.issues.filter(issue => isInbox(issue, now.project) && !known.some(one => one.number === issue.number && one.updatedAt === issue.updatedAt)).slice(0, TRIAGE_BATCH)
      if (due.length === 0) return
      await update($, triage, was => ({ ...was, asking: true, failed: null }))
      // Kept first, so the person can pick any of them should Claude not answer.
      const areas = await repoAreas($, now)
      await update($, triage, was => ({ ...was, areas }))
      const priorities = (project.priority?.options ?? []).map(option => ({ name: option.name, description: PRIORITIES.find(one => one.name === option.name)?.description ?? '' }))
      const reply = await $.model.complete({ model: 'sonnet', prompt: triagePrompt(now.repo, due, priorities, areas), maxTokens: 4096, effort: 'low' })
      if (!reply.isAnswered) throw new Error(`Claude didn't answer (${reply.reason})`)
      const made = parseTriage(reply.text, due, priorities.map(one => one.name), areas, project)
      if (made.length === 0) throw new Error("Claude's answer didn't come back as suggestions")
      await update($, triage, was => ({ ...was, suggestions: [...was.suggestions.filter(one => !made.some(fresh => fresh.number === one.number)), ...made] }))
      // Claude left some out: they wait for Suggest again rather than be asked about over and over.
      if (made.length < due.length) return
    }
  } catch (cause) {
    const message = messageOf(cause)
    await update($, triage, was => ({ ...was, failed: message }))
  } finally {
    suggesting = false
    await update($, triage, was => ({ ...was, asking: false }))
  }
}

// Suggest again: Claude's suggestions for the Inbox are dropped and asked for afresh; the person's picks stay.
const suggestAgain = async ($: EngineInterface): Promise<void> => {
  const now = await read($, board)
  const inbox = (now?.issues ?? []).filter(issue => isInbox(issue, now?.project)).map(issue => issue.number)
  await update($, triage, was => ({ ...was, suggestions: was.suggestions.filter(one => !inbox.includes(one.number)) }))
  await suggestInbox($)
}

// The project's option for Ready or Backlog, by name, if it has one.
const triageTarget = (project: Project | null | undefined, status: 'Ready' | 'Backlog'): string | undefined => roleOf(project, status === 'Ready' ? 'ready' : 'backlog')?.name

// Accept on an Inbox issue: its Priority and area as picked, Claude's suggestion unless changed, and its Status moved
// on to Ready or Backlog, so it leaves the Inbox, where the project has that option. Another area label it had comes off.
// On a project the board only reads, the labels still change, since they are the repo's, not the project's. The Status
// and Priority are skipped and the toast says why. The issue stays in the Inbox then, so the person's picks stay too.
const acceptTriage = async ($: EngineInterface, issue: Issue, choice: { priority: string | null; area: string | null }, status: 'Ready' | 'Backlog'): Promise<void> => {
  const label = choice.area ? `area:${choice.area}` : null
  const others = label ? issue.labels.map(one => one.name).filter(name => name.startsWith('area:') && name !== label) : []
  const project = (await read($, board))?.project
  const refusal = await boardRefusal($, { project })
  const target = triageTarget(project, status)
  const fields: IssueChanges = {
    ...(target ? { status: target } : {}),
    ...(choice.priority && choice.priority !== issue.priority ? { priority: choice.priority } : {}),
  }
  const labels: IssueChanges = {
    ...(label && !issue.labels.some(one => one.name === label) ? { addLabels: [label] } : {}),
    ...(others.length > 0 ? { removeLabels: others } : {}),
  }
  try {
    if (refusal) {
      const done = labels.addLabels || labels.removeLabels ? await applyChanges($, issue.number, labels) : ''
      const skipped = fields.status || fields.priority ? `Skipped its Status and Priority: ${refusal}` : ''
      $.ui.toast([done || (skipped ? `Nothing changed on #${issue.number}.` : `Nothing to change on #${issue.number}.`), skipped].filter(Boolean).join(' '))
      return
    }
    $.ui.toast(await applyChanges($, issue.number, { ...fields, ...labels }))
    await update($, triage, was => ({ ...was, picks: was.picks.filter(one => one.number !== issue.number) }))
  } catch (cause) {
    toastFailure($, `Couldn't triage #${issue.number}`, cause)
  }
}

// How many of an issue's comments a card shows: the latest.
const SHOWN_COMMENTS = 3

// Reads an issue's comments for its card. One card is open at a time, so this holds only its comments; a card opened
// meanwhile keeps the comments it asked for.
const loadComments = async ($: EngineInterface, number: number): Promise<void> => {
  await update($, talk, was => (was?.number === number ? was : { number, comments: null, total: 0 }))
  try {
    const all = commentsOf(await gh($, ['issue', 'view', String(number), '--json', 'comments']))
    await update($, talk, was => (was?.number === number ? { number, comments: all.slice(-SHOWN_COMMENTS), total: all.length } : was))
  } catch (cause) {
    await update($, talk, was => (was?.number === number ? { number, comments: [], total: 0 } : was))
    $.ui.log(`issue-board: couldn't read the comments on #${number}: ${messageOf(cause)}`, { to: 'debug' })
  }
}

// Choosing a tab of the pane. A view's tab takes the view's grouping, as GitHub shows it, when the board can group
// that way; the person can pick another after.
const pickTab = async ($: EngineInterface, tab: Tab, project: Project | null): Promise<void> => {
  await update($, filter, () => tab.id)
  const grouping = viewGroupingOf(tab.view, project)
  if (grouping) await update($, groupBy, () => grouping.by)
  // The Inbox seen: the band stops counting what was captured to it.
  if (inboxTabOf([tab], project)) await update($, captured, () => 0)
  if (tab.id === 'inbox') await suggestInbox($)
  else if (tab.id === 'closed') await readRecent($)
}

// What the card's editor offers: the repo's labels and open milestones, when it opens. The board's last read has both,
// the labels unless the repo's project read failed; only then are the labels read from GitHub.
const loadPalette = async($: EngineInterface): Promise<void> => {
  try {
    const now = await read($, board)
    if (!now) return
    const labels = [...(now.labels ?? (await repoLabels($, now.repo)).map(one => one.name))].sort()
    const milestones = (now.milestones ?? []).map(one => one.title)
    await update($, palette, () => ({ labels, milestones }))
  } catch (cause) {
    $.ui.toast(`Couldn't read the repo's labels and milestones: ${messageOf(cause)}`)
  }
}

// The text of each section the board last added to the system prompt, by id. A section is counted as context when it
// first goes in and each time its text changes, not on every request that carries it again.
const composedSections = new Map<string, string>()
const countSection = (id: string, text: string, source: ContextSource): void => {
  if (composedSections.get(id) === text) return
  composedSections.set(id, text)
  countText(source, text)
}

// Sends Claude a prompt of the board's. What reaches Claude counts as context, and as a prompt, since the board's own
// prompt.submit hook doesn't see it.
const submit = async ($: EngineInterface, source: ContextSource, args: Parameters<EngineInterface['prompt']['submit']>[0]) => {
  const sent = await $.prompt.submit(args)
  if (sent.drop === undefined) {
    countText(source, args.text)
    countPrompt(stats)
  }
  return sent
}

// Registers one of the board's tools. Its name, description and schema count as context only once Claude Code puts
// them in front of Claude: see the tool.describe and tool.call hooks.
const registerTool = ($: EngineInterface, tool: Parameters<EngineInterface['tool']['register']>[0]) => {
  defineTool(stats, `mcp__issue-board__${tool.name}`, JSON.stringify(tool).length)
  return $.tool.register(tool)
}

// The small pieces the pane's and the band's rows are built from, made with the surface's own elements.
const partsOf = ({ Box, Text, Button, Link }: Pick<ElementTable, 'Box' | 'Text' | 'Button' | 'Link'>) => ({
  // A link in a row stays on one line: squeezed, it ends in an ellipsis rather than breaking down the pane a letter a
  // line. A click still opens the whole address.
  link: (href: string, label = '↗ GitHub') => (
    <Text wrap="truncate-end">
      <Link href={href} label={label} />
    </Text>
  ),
  // A part of a one-line row that keeps its width: a number, a badge, a count or a button. A row short of room
  // squeezes only the part left to shrink, which cuts its text, rather than breaking `#252` into `#25` over `2`.
  keep: (part: RenderChildren) => <Box flexShrink={0}>{part}</Box>,
  // One option of a set, the chosen one drawn as the primary and the others dim. `extra` carries a tab's hotkey.
  choice: (key: string, label: string, chosen: boolean, onPress: ButtonProps['onPress'], extra: Pick<ButtonProps, 'hotkey'> = {}) => (
    <Button key={key} {...extra} variant={chosen ? 'primary' : undefined} dimColor={!chosen} onPress={onPress}>
      {label}
    </Button>
  ),
})

export const register: Register = (on, options) => {
  settings = settingsOf(options)
  on('session.start', async ($, e, next) => {
    stats.startedAt = await nowOf($)
    // Before the background agent is registered, as its prompt follows closesWhenTicked.
    settings = withOldKeys(settings, await storedOptions($))
    await $.command.register({
      name: 'issues',
      description: 'Show open issues and pull requests in a pane',
      argumentHint: `[${SUBCOMMANDS.map(one => one.name.replace(' <what>', '')).filter((one, index, all) => all.indexOf(one) === index).join(' | ')}]`,
    })
    for (const { name, description, inputSchema } of TOOL_SPECS) await registerTool($, { name, description, inputSchema })
    // The agent Start in background runs: in its own worktree, in the background. Claude reads its description among the
    // agent types.
    const workerDescription = "Works one GitHub issue of this repository end to end in its own git worktree, for the issue board's Start in background."
    countText('agent type', workerDescription)
    await $.agent
      .register({
        name: 'worker',
        description: workerDescription,
        prompt: workerPrompt(settings.closesWhenTicked),
        isolation: 'worktree',
        background: true,
      })
      .catch((cause: unknown) => $.ui.log(`issue-board: couldn't register the background agent: ${messageOf(cause)}`, { to: 'debug' }))
    // A reload ended the CI watches; agents still working are looked at again.
    await update($, runs, () => [])
    if ((await read($, workers)).some(one => ACTIVE.includes(one.status))) pollWorkers($)
    // Earlier versions pinned the summary to the status line; a reload would leave it there.
    $.ui.status(undefined)
    await restore($)
    void checkAccess($)
    void refresh($)

    return next(e)
  })

  // A /clear (or /new, its alias) or a /resume ends this session and starts another in the same process. As the old
  // one ends, the host empties the board's state, and no session.start follows.
  on('session.end', { reason: ['clear', 'resume'] }, async ($, e, next) => {
    restarts += 1
    restarted = true
    sentCopies.clear()
    return next(e)
  })

  // A compaction of the main conversation that stands drops the copies earlier prompts carried, so the next prompt
  // naming one sends it again. A precompute changes nothing yet, and a subagent's own compaction isn't this one.
  on('session.compact', async ($, e, next) => {
    const compacted = await next(e)
    if (e.agentId === undefined && e.trigger !== 'precompute' && compacted.skip === undefined) sentCopies.clear()
    return compacted
  }).catch(($, e, next) => fallBack($, e, next, 'session.compact'))

  // The new session's SessionStart hooks run once its state is empty: the board fills it again.
  on('classic.SessionStart', async ($, e, next) => {
    if (e.permission_mode) permissionMode = e.permission_mode
    if (restarted) void begin($)
    return next(e)
  }).catch(($, e, next) => fallBack($, e, next, 'classic.SessionStart'))

  on('command.run', { command: 'issues' }, async ($, e) => {
    const asked = /^new\b\s*(epic\b)?\s*([\s\S]*)$/.exec(e.args.trim())
    if (asked) {
      const epic = asked[1] !== undefined
      void captureFromTalk($, (asked[2] ?? '').trim(), epic)
      return {
        text: epic
          ? 'Capturing an epic and its sub-issues from the conversation to the Inbox. A toast says when they are filed; triage them in the Inbox.'
          : 'Capturing an issue from the conversation to the Inbox. A toast says when it is filed; triage it in the Inbox.',
      }
    }
    if (e.args.trim() === 'setup') {
      await $.ui.open(OPEN)
      void within('setup', () => readSetup($))
      return { text: 'Reading the repo and its project. What setup would change shows at the top of the issues pane, and nothing changes until you press Apply.' }
    }
    if (e.args.trim() === 'statuses') {
      const project = await openStatuses($)
      if (!project) {
        const now = (await read($, board))?.project
        return { text: now ? `${now.title} has no Status field, so there is nothing to map. Add one in the project, or run /issues setup.` : 'The board reads no GitHub Project for this repo, so there are no Status options to map. /issues setup can link or make one.' }
      }
      return { text: `Which Status is which for ${project.title} shows at the top of the issues pane. Save keeps it here, and nothing changes on GitHub.` }
    }
    if (e.args.trim() === 'labels') {
      await openMarkers($)
      const now = await read($, board)
      const later = now?.project ? '' : ', and which label Later does,'
      return { text: `Which label or issue type Bugs goes by${later} shows at the top of the issues pane. Save keeps it here, and nothing changes on GitHub.` }
    }
    if (e.args.trim() === 'stats') return { text: statsText(stats, await nowOf($)) }
    if (e.args.trim() === 'help') {
      const project = (await read($, board))?.project
      const tabs = filtersFor(project)
      return { text: helpText(tabs, featuresOff(switchesOf(settings), project, !project || (await mayWrite($, project))), tabs.some(tab => tab.view)) }
    }
    if (e.args.trim() === 'check') {
      const problems = await checkAccess($)
      const found = await read($, access)
      // What is off, by a setting or for want of a Status option, is said here and in /issues help, not in the band.
      const project = (await read($, board))?.project
      const off = offText(featuresOff(switchesOf(settings), project, !project || (await mayWrite($, project))))
      // A mapping found by common names, until the person answers it, with how to change it.
      const guess = guessOf(project)
      const guessed = project && guess.length > 0 && !(await read($, guessSeen)).includes(guessKey(project, guess))
      const markerAsk = markerAskOf((await read($, board)) ?? null, await read($, chosenMarkers))
      const marked = Object.keys(markerAsk).length > 0 && !(await read($, guessSeen)).includes(markerKey(markerAsk))
      const said = [
        ...(guessed ? [`The board guessed which Status is which. ${guessText(guess)}. Press Looks right in the band to keep it, or run /issues statuses to change it.`] : []),
        ...(marked ? [`The board guessed which labels Bugs and Later go by. ${markerText(markerAsk)}. Press Looks right in the band to keep it, or run /issues labels to change it.`] : []),
      ]
      const withOff = (text: string) => ({ text: [text, ...(said.length > 0 ? ['', ...said] : []), ...(off.length > 0 ? ['', ...off] : [])].join('\n') })
      if (problems.length > 0) {
        const count = problems.length === 1 ? 'one problem' : `${problems.length} problems`
        return withOff(`The issue board found ${count}:\n${problems.map(problem => `- ${problem.title}. ${problem.detail} ${problem.fix}`).join('\n')}`)
      }
      if (!found?.repo) {
        const remote = (await $.session.repo().catch(() => null))?.remote ?? ''
        return {
          text: /github/i.test(remote)
            ? "gh couldn't read this folder's GitHub repository. Check your connection, then run /issues check again."
            : "The issue board couldn't find a GitHub repository for this folder, so it has nothing to show.",
        }
      }
      void refresh($)
      const who = found.login ? `gh is signed in as ${found.login}` : 'gh is signed in'
      return withOff(`The issue board has what it needs. ${who}${found.permission ? `, with ${found.permission.toLowerCase()} access to ${found.repo}` : ''}.`)
    }
    if (e.args.trim() === 'refresh') {
      await refresh($)
      const now = await read($, board)
      return {
        text: now ? `Refreshed: ${summary(now.issues, now.prs, await markersNow($, now)) ?? 'nothing open'}.` : `Couldn't refresh: ${(await read($, error)) ?? 'unknown error'}`,
      }
    }
    // A mistyped subcommand says so, rather than opening the pane as if nothing had been asked.
    const unknown = e.args.trim().split(/\s+/)[0]
    if (unknown) return { text: `Unknown subcommand ${unknown}; /issues help lists them.` }
    await $.ui.open(OPEN)
    if ((await read($, board)) === null) void refresh($)
    // The pane opening at the Inbox is the Inbox seen: the band stops counting captures.
    const project = (await read($, board))?.project
    const inbox = inboxTabOf(filtersFor(project), project)
    if (inbox && tabOf(filtersFor(project), await read($, filter)).id === inbox.id) await update($, captured, () => 0)

    return {
      text: openedText(filtersFor((await read($, board))?.project)),
    }
  })

  // Esc, or the pane's close mark: with an issue's card or a pull request's details open it folds them and keeps the
  // pane; with nothing open the pane closes. The engine stamps both as the person's close, so they step back alike.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    if (e.origin.kind !== 'person') return next(e)
    // /issues statuses steps back first: it shows above setup, and saves nothing on the way out.
    if (await read($, statusPicks)) {
      await update($, statusPicks, () => null)
      return { value: undefined }
    }
    if (await read($, markerPicks)) {
      await update($, markerPicks, () => null)
      return { value: undefined }
    }
    // Setup showing steps back first, unless Apply is running: that keeps the pane open until it's done.
    const shown = await read($, setup)
    if (shown) {
      if (shown.phase !== 'applying') await update($, setup, () => null)
      return { value: undefined }
    }
    const folding = (await read($, expanded)) !== null || (await read($, openPr)) !== null
    if (!folding) return next(e)
    await update($, expanded, () => null)
    await update($, editing, () => null)
    await update($, openPr, () => null)
    return { value: undefined }
  }).catch(($, e, next) => fallBack($, e, next, 'ui.close'))

  // A board tool's definition goes into Claude's context when Claude Code first lists it in front, rather than behind
  // ToolSearch, for /issues stats.
  on('tool.describe', async ($, e, next) => {
    const described = await next(e)
    const deferred = described.isDeferred ?? e.isDeferred === true
    if (!deferred) loadTool(stats, e.tool)
    return described
  }).catch(($, e, next) => fallBack($, e, next, 'tool.describe'))

  // A deferred tool's definition loads when ToolSearch finds it. One Claude calls loads too: see asTool.
  on('tool.call', { tool: 'ToolSearch' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny === undefined && !ran.isError) for (const name of matchesOf(ran.result)) loadTool(stats, name)
    return ran
  }).catch(($, e, next) => fallBack($, e, next, 'tool.call on ToolSearch'))

  // Claude changing GitHub through gh or a push: show the change straight away, and a change Claude made through gh to
  // the issue it is on isn't news to it. A checkout moves the branch marker, and to a branch named for an issue, the
  // issue Claude is on, when the main session moves: a subagent's checkout is its own. Any git or gh has the board read
  // GitHub again when the turn ends.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    const command = (e as { command?: unknown }).command
    if (typeof command !== 'string') return ran
    if (/\b(git|gh)\b/.test(command)) touches += 1
    if (writesGitHub(command)) {
      // What Claude's gh changed can't be told apart from others' changes since the board last read GitHub.
      const copy = /\bgh\b/.test(command) ? await copyOf($) : null
      void refreshAfter($).then(() => absorb($, copy))
      // A push starts CI on the branch: the board watches it once it turns up.
      if (/\bgit\s+push\b/.test(command)) void lookForRuns($)
    } else if (GIT_MOVE.test(command) && e.agentId === undefined) void currentBranch($).then(now => followBranch($, now))

    return ran
  }).catch(($, e, next) => fallBack($, e, next, 'tool.call on Bash'))

  // A worktree is a checkout too: Claude Code names its branch after the worktree, such as `worktree-fix+315-glide`.
  // Only the main session's checkouts count: a subagent's, such as a background agent's in its own worktree, make its
  // issue the agent's, not the one Claude is on.
  on('tool.call', { tool: ['EnterWorktree', 'ExitWorktree'] }, async ($, e, next) => {
    const ran = await next(e)
    if (e.agentId === undefined) void currentBranch($).then(now => followBranch($, now))
    return ran
  }).catch(($, e, next) => fallBack($, e, next, 'tool.call on a worktree'))

  // Claude completing or deleting a task Start made for a box: a completed one has the band ask whether to tick it.
  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const ran = await next(e)
    const { taskId, status } = e as { taskId?: unknown; status?: unknown }
    const failed = ran.deny !== undefined || ran.isError === true || (ran.result as { success?: unknown } | undefined)?.success === false
    if (failed || typeof taskId !== 'string' || typeof status !== 'string' || !(await read($, tasks)).some(one => one.id === taskId)) return ran
    await update($, tasks, list => (status === 'deleted' ? list.filter(one => one.id !== taskId) : list.map(one => (one.id === taskId ? { ...one, done: status === 'completed' } : one))))
    return ran
  }).catch(($, e, next) => fallBack($, e, next, 'tool.call on TaskUpdate'))

  // A prompt carries, unseen by the person, the board's copy of each issue or pull request it names as `#123`, and a
  // note of what changed on GitHub to the issue Claude is on since the last prompt. The system prompt stays as it is.
  on('prompt.submit', async ($, e, next) => {
    nextStep = null
    // The session started over and no SessionStart hook has run since: the first prompt fills the board again.
    if (restarted) void begin($)
    // Each line the board adds, with where it came from for /issues stats.
    const lines: [ContextSource, string][] = []
    const add = (source: ContextSource, ...texts: string[]) => lines.push(...texts.map((text): [ContextSource, string] => [source, text]))
    let copied: [number, string][] = []
    // The person sends the start message Edit first filled: while it still names the issue, Start's steps run.
    const starting = await draftedStart($, e)
    if (starting?.listed) add('task note', `Each open acceptance box of #${starting.issue.number} is a task in your task list too: mark it completed when it is done.`)
    try {
      // What the board moved on its own since the last prompt.
      if (moved.length > 0 && e.origin.kind !== 'task-notification') {
        add('moved lines', ...moved)
        moved = []
      }
      const now = await read($, board)
      if (now) {
        const note = await newsFor($, now)
        if (note) add('news', note)
        // A background task's notice quotes its command, which may name an issue nobody asked about.
        if (e.origin.kind !== 'task-notification' && settings.issueCopies) {
          const copies = copiesFor(now, mentionsOf(e.text, MENTIONS_READ), sentCopies, Date.now())
          add('issue copies', ...copies.context)
          copied = copies.keys
        }
      }
    } catch (cause) {
      $.ui.log(`issue-board: couldn't add the board to the prompt: ${messageOf(cause)}`, { to: 'debug' })
    }
    const added = lines.map(([, text]) => text)
    const entered = await next(added.length > 0 ? { ...e, context: [...(e.context ?? []), ...added] } : e)
    // A dropped prompt never reached Claude, so its copies count as unsent, and nothing it carried counts as context.
    if (entered.drop === undefined) for (const [number, key] of copied) sentCopies.set(number, key)
    if (entered.drop === undefined) for (const [source, text] of lines) countText(source, text)
    if (entered.drop === undefined) countPrompt(stats)
    if (starting && entered.drop === undefined) {
      $.ui.toast(`Sent #${starting.issue.number} to Claude`)
      await claim($, starting.issue)
    }
    return entered
  }).catch(($, e, next) => fallBack($, e, next, 'prompt.submit'))

  on('turn.complete', async ($, e, next) => {
    const ended = await next(e)
    if (e.agentId === undefined) void afterTurn($)
    else void workerEnded($, e.agentId, e.answer, e.reason)
    return ended
  })

  // Claude dispatches the board's agent, from the conversation or Edit first in background: the issue's row follows the
  // agent it started, and the issue is claimed. Start in background spawns the agent itself and follows it from the
  // spawn's result, so its own spawn is left to it here.
  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (e.subagentType !== WORKER || next.origin.plugin === PLUGIN) return started
    const number = workerIssueOf(e)
    if (started.deny !== undefined) {
      $.ui.toast(`Couldn't start a background agent${number ? ` on #${number}` : ''}: ${started.deny}`)
      return started
    }
    if (number === undefined) return started
    try {
      const agentId = started.agentId ?? (await workerIdOf($, e.description, e.name))
      if (!agentId) throw new Error('no agent id')
      await workerStarted($, number, agentId, startedByClaude(next.origin, e))
      const issue = (await read($, board))?.issues.find(one => one.number === number)
      if (issue) await claim($, issue)
    } catch (cause) {
      $.ui.toast(`Started a background agent on #${number}, but the board couldn't follow it: ${messageOf(cause)}`)
    }
    return started
  }).catch(($, e, next) => fallBack($, e, next, 'agent.spawn'))

  // A GitHub event for a subscribed pull request reaches Claude as it would, and the board reads GitHub at once.
  on('session.receive', async ($, e, next) => {
    const received = await next(e)
    if (e.event?.source === 'github' && e.agentId === undefined) void eventArrived($, e.event.data)
    return received
  }).catch(($, e, next) => fallBack($, e, next, 'session.receive'))

  // Typing `#` in the prompt box offers the board's open issues and pull requests, from the board already in state, so
  // it costs no gh call. The rows go after any that plugins beneath gave. With no board yet, nothing is added.
  on('prompt.autocomplete', { token: /^#/ }, async ($, e, next) => {
    const now = await read($, board)
    if (!now) return next(e)
    const given = await next(e)
    return { suggestions: [...given.suggestions, ...hashRows(now, e.token)] }
  }).catch(($, e, next) => fallBack($, e, next, 'prompt.autocomplete'))

  // The engine's guess at the next prompt gives way to the board's next step for the issue Claude is on.
  on('prompt.suggest', async ($, e, next) => (e.origin.kind === 'suggestion' && nextStep ? next({ ...e, text: nextStep }) : next(e)))

  on('tool.call', { tool: ISSUES_TOOL }, async ($, e) =>
    asTool(e.tool, async () => {
      const input = e as unknown as {
        number?: number
        filter?: BuiltInFilter
        area?: string
        query?: string
        state?: string
        search?: string
        label?: string
        assignee?: string
        milestone?: string
        milestones?: boolean
        status?: string
        since?: string
      }
      if (input.status?.trim()) {
        const now = await read($, board)
        if (!now?.project) return { result: "The board reads no project for this repo, so it can't list issues by Status." }
        return { result: await readProject($, now.project, input.status.trim(), input.since?.trim()) }
      }
      if (input.milestones) {
        const listed = (await read($, board))?.milestones ?? []
        const today = new Date(await nowOf($)).toISOString().slice(0, 10)
        return { result: listed.length > 0 ? listed.map(one => milestoneLine(one, today)).join('\n') : 'The repo has no open milestones.' }
      }
      // Closed issues, and words searched in every issue, are GitHub's search to answer: the board holds open issues only.
      if (input.number === undefined && (input.state === 'closed' || input.state === 'all' || input.search?.trim())) {
        const repo = (await read($, board))?.repo ?? repoInfo?.nameWithOwner
        if (!repo) return { deny: NOT_READ_SENTENCE }
        return { result: await searchIssues($, repo, input) }
      }
      if ((await read($, board)) === null) await refresh($)
      const now = await read($, board)
      if (!now) {
        const failure = (await read($, error)) ?? 'unknown error'
        const problems = await checkAccess($, failure)
        return { deny: `The issue board couldn't read GitHub: ${failure}${problems.length > 0 ? `\n${problemsText(problems)}` : ''}` }
      }

      if (typeof input.number === 'number') {
        const issue = now.issues.find(one => one.number === input.number)
        if (issue) {
          const set = Object.entries(await readValues($, issue)).filter(([name]) => !/^(status|priority)$/i.test(name))
          const fields = set.length > 0 ? `\nFields: ${set.map(([name, value]) => `${name} ${value}`).join(', ')}` : ''
          return { result: `${issueText(issue)}${fields}\n${await latestComments($, now.repo, issue.number, issue.comments)}` }
        }
        const pr = now.prs.find(one => one.number === input.number)
        if (pr) return { result: `${prText(pr)}\nRead it in full with \`gh pr view ${pr.number}\`.` }
        return { result: await readClosed($, now.repo, input.number) }
      }
      const listed = toolListOf(now.issues, input, await read($, viewer), now.project ?? null, await markersNow($, now))
      return { result: boardText(now, listed.issues, listed.label, Date.now()) }
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'issues'))

  on('tool.call', { tool: TICK_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const input = e as unknown as { number?: unknown; boxes?: unknown; done?: unknown }
      const { number, boxes } = input
      if (typeof number !== 'number' || !Array.isArray(boxes) || boxes.length === 0 || !boxes.every(box => Number.isInteger(box))) {
        return { deny: 'Give the issue number and the boxes to tick, counted from 1.' }
      }
      return askThenAct(e, next, async () => {
        try {
          const copy = await copyOf($)
          const { text, before } = await tick($, number, boxes as number[], input.done !== false)
          // Only the boxes Claude changed: the body was read fresh, so what others changed meanwhile stays news.
          if ((await read($, working))?.number === number) await absorb($, copy && { ...copy, checks: before })
          return { result: text }
        } catch (cause) {
          return deniedBy($, `Couldn't tick boxes on #${number}`, cause)
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'tick'))

  on('tool.call', { tool: UPDATE_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const changes = changesOf(e)
      if (!changes) return { deny: 'Give the issue number, and what to change on it.' }
      // A lock the board doesn't know is refused, not dropped without a word.
      if ((e as { lock?: unknown }).lock !== undefined && changes.lock === undefined) {
        return { deny: 'lock takes true, false, or one of GitHub\'s reasons: off_topic, resolved, spam, too_heated.' }
      }
      const { number, ...asked } = changes
      const starting = (e as { start?: unknown }).start === true
      // A project the board may not write to: a call that only changes the project is refused here, before it asks, with
      // the gate's reason. One that changes the repo too asks, makes the repo's changes, and says which were skipped.
      const refusal = await boardRefusal($)
      const parts = projectPartOf(asked)
      const skipped = refusal ? parts.project : []
      if (skipped.length > 0 && !starting && !repoChangeOf(parts.repo)) return { deny: `Couldn't set #${number}'s ${namesText(skipped)}. ${refusal}` }
      const rest = skipped.length > 0 ? parts.repo : asked
      const skippedText = skipped.length > 0 ? `\nSkipped its ${namesText(skipped)}: ${refusal}` : ''
      return askThenAct(e, next, async () => {
        try {
          const started = starting ? await startHere($, number) : null
          if (started && Object.keys(rest).length === 0) return { result: `${started}${skippedText}` }
          const copy = (await read($, working))?.number === number ? await copyOf($) : null
          const result = await applyChanges($, number, rest)
          // What the tool changed that Claude is told of: a comment, and closing or reopening.
          if (copy) {
            const closed = rest.close ? true : rest.reopen ? false : copy.closed
            await absorb($, copy, { ...copy, comments: copy.comments === null ? null : copy.comments + (rest.comment ? 1 : 0), closed })
          }
          return { result: `${started ? `${started}\n${result}` : result}${skippedText}` }
        } catch (cause) {
          return deniedBy($, `Couldn't change #${number}`, cause)
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'issue_update'))

  // Claude proposing a plan. An invalid plan is refused with every problem, and nothing is shown or asked. A valid one
  // goes on the pane's card at once, then the call asks, once, with the plan summed up; a yes applies its ticked rows.
  // A no leaves it on the card, for the person to apply some of it or discard it. In a mode that settles prompts unseen,
  // it stays on the card and the call asks nothing.
  on('tool.call', { tool: PLAN_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const planned = await planFor($, e, true)
      if ('problems' in planned) return { deny: problemsOfPlan(planned.problems) }
      const id = await propose($, planned.changes)
      const mode = unseenMode()
      if (mode) return { deny: planUnseen(mode) }
      return askThenAct(e, next, async () => {
        try {
          return { result: await applyPlan($, id) }
        } catch (cause) {
          return { deny: `Couldn't apply the plan: ${messageOf(cause)}` }
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'project_plan'))

  // A plan's permission prompt says what it would change: its size and its changes by kind. A rule that allows or denies
  // still stands, as does an organization's ceiling; an invalid plan keeps the verdict, as the call refuses it anyway.
  // Where nobody would see the prompt, in auto or bypass mode, it is refused whatever the verdict beneath, rules included.
  on('tool.check', { tool: PLAN_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision === 'deny') return verdict
    const mode = unseenMode()
    if (mode) return { decision: 'deny' as const, reason: planUnseen(mode) }
    if (verdict.decision !== 'ask') return verdict
    const planned = await planFor($, e.input)
    return 'problems' in planned ? verdict : { ...verdict, reason: planAsk(planned.changes.map(one => one.change)) }
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on project_plan'))

  // Claude filing an issue. Claude Code asks first, as for any tool that changes something.
  on('tool.call', { tool: CREATE_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const spec = newIssueOf(e)
      if (typeof spec === 'string') return { deny: spec }
      return askThenAct(e, next, async () => {
        try {
          return { result: await fileIssue($, spec) }
        } catch (cause) {
          return deniedBy($, `Couldn't file the issue`, cause)
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'issue_create'))

  // Claude capturing work found in conversation to the Inbox. It goes through the permission check like the other
  // writes, which the hook below lets through.
  on('tool.call', { tool: CAPTURE_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const spec = captureOf(e)
      if (typeof spec === 'string') return { deny: spec }
      return askThenAct(e, next, async () => {
        try {
          return { result: await capture($, spec) }
        } catch (cause) {
          return deniedBy($, `Couldn't capture it`, cause)
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'capture'))

  // A capture is a small write into the Inbox, where the person triages it, so it needs no permission prompt. A rule
  // that denies it still stands, and so does an organization's ceiling that keeps the tool at asking.
  on('tool.check', { tool: CAPTURE_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    return verdict.decision === 'ask' && mayAllow(e.ceiling) ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on capture'))

  // Claude reading or posting the project's status update. Reading answers at once; posting asks, then acts.
  on('tool.call', { tool: STATUS_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const ask = e as unknown as { status?: unknown; note?: unknown; start?: unknown; target?: unknown }
      const project = (await read($, board))?.project
      if (!project) return { deny: 'The board reads no project for this repo.' }
      if (typeof ask.status !== 'string' || !ask.status.trim()) {
        const latest = project.update
        return { result: latest ? `${project.title}: ${updateLine(latest, await nowOf($))}${latest.body.includes('\n') ? `\n${latest.body}` : ''}` : `${project.title} has no status update yet.` }
      }
      const status = ask.status
      // A post is all project, so a project the board may not write to refuses it here, before anything is asked.
      const refusal = await boardRefusal($)
      if (refusal) return { deny: `Couldn't post the status update. ${refusal}` }
      return askThenAct(e, next, async () => {
        try {
          const note = textOf(ask.note)
          const start = textOf(ask.start)
          const target = textOf(ask.target)
          return { result: await postStatus($, project, { status, ...(note ? { note } : {}), ...(start ? { start } : {}), ...(target ? { target } : {}) }) }
        } catch (cause) {
          return { deny: `Couldn't post the status update: ${messageOf(cause)}` }
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'project_status'))

  // Reading the status update changes nothing, so it needs no permission prompt; posting one asks.
  on('tool.check', { tool: STATUS_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    const status = (e.input as { status?: unknown }).status
    return verdict.decision === 'ask' && mayAllow(e.ceiling) && !(typeof status === 'string' && status.trim()) ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on project_status'))

  // Claude archiving project items: the first call lists them and answers at once; the second, with confirm, asks and
  // then archives them.
  on('tool.call', { tool: ARCHIVE_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const ask = e as unknown as { number?: unknown; doneBefore?: unknown; confirm?: unknown }
      const project = (await read($, board))?.project
      if (!project) return { deny: "The board reads no project for this repo, so there's nothing to archive." }
      const confirm = ask.confirm === true
      const archive = async () => {
        try {
          return {
            result: await archiveItems($, project, {
              ...(typeof ask.number === 'number' ? { number: ask.number } : {}),
              ...(typeof ask.doneBefore === 'string' && ask.doneBefore.trim() ? { doneBefore: ask.doneBefore.trim() } : {}),
              confirm,
            }),
          }
        } catch (cause) {
          return { deny: `Couldn't archive: ${messageOf(cause)}` }
        }
      }
      // Archiving is all project, so a project the board may not write to refuses it here, before anything is asked. The
      // list changes nothing and still answers, saying the archive would be refused.
      const refusal = await boardRefusal($)
      if (confirm && refusal) return { deny: `Couldn't archive. ${refusal}` }
      if (!confirm) {
        const listed = await archive()
        return refusal && 'result' in listed ? { result: `${listed.result}\nThe archive itself would be refused: ${refusal}` } : listed
      }
      return askThenAct(e, next, archive)
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'project_archive'))

  // Listing what an archive would take changes nothing, so it needs no permission prompt; the archive itself asks. A rule
  // that denies still stands, as does an organization's ceiling.
  on('tool.check', { tool: ARCHIVE_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    return verdict.decision === 'ask' && mayAllow(e.ceiling) && (e.input as { confirm?: unknown }).confirm !== true ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on project_archive'))

  // Claude letting the board write to a project, or releasing it, when the person asked. It asks, then acts, so the
  // check below and its prompt run first, and a no changes nothing.
  on('tool.call', { tool: ADOPT_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const plan = await adoptPlan($, e)
      if ('refusal' in plan) return { deny: plan.refusal }
      return askThenAct(e, next, async () => {
        try {
          if ('release' in plan) {
            await releaseNow($, plan.release)
            return { result: `Released ${plan.release.title}: the board only reads it now.` }
          }
          await adoptProject($, plan.adopt)
          return { result: `The board may write to ${plan.adopt.title} now. Release it with project_adopt and release: true, or in /issues setup.` }
        } catch (cause) {
          return { deny: `Couldn't save that: ${messageOf(cause)}` }
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'project_adopt'))

  // Adopting or releasing a project always asks the person, whatever their rules allow, with the pane's warning in the
  // prompt: a hook's ask outranks an allow rule. A rule that denies still stands. Where nobody would see the prompt, it
  // is refused instead: in a subagent, in auto mode, where a classifier settles the ask, and in bypass mode, where nothing
  // asks.
  on('tool.check', { tool: ADOPT_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision === 'deny') return verdict
    const ask = 'Ask the person to press Let it write in /issues, or to run /issues setup.'
    if (e.agentId !== undefined) return { decision: 'deny' as const, reason: `Only the person can let the board write to a project, and nobody watches a subagent's permission prompts. ${ask}` }
    const mode = unseenMode()
    if (mode) {
      return { decision: 'deny' as const, reason: `The ${mode} permission mode settles prompts without showing them, and this one needs the person to read it. ${ask} Or switch to a mode that asks, and try again.` }
    }
    const plan = await adoptPlan($, e.input)
    if ('refusal' in plan) return { decision: 'deny' as const, reason: plan.refusal }
    return { decision: 'ask' as const, reason: 'release' in plan ? releaseReason(plan.release) : adoptReason(plan.adopt, settings.refresh) }
  }).catch(($, _e, next) => adoptCheckFailed($, next))

  // The permission mode, which each prompt's classic hook carries, for project_adopt's and project_plan's checks.
  on('classic.UserPromptSubmit', async ($, e, next) => {
    if (e.permission_mode) permissionMode = e.permission_mode
    return next(e)
  }).catch(($, e, next) => fallBack($, e, next, 'classic.UserPromptSubmit'))

  // Claude making or changing a milestone. Claude Code asks first, as for any tool that changes something.
  on('tool.call', { tool: MILESTONE_TOOL }, async ($, e, next) =>
    asTool(e.tool, async () => {
      const ask = e as unknown as { title?: unknown; newTitle?: unknown; due?: unknown; description?: unknown; close?: unknown; reopen?: unknown }
      const title = textOf(ask.title)
      if (!title) return { deny: 'Give the milestone a title.' }
      const repo = (await read($, board))?.repo
      if (!repo) return { deny: NOT_READ_SENTENCE }
      return askThenAct(e, next, async () => {
        try {
          const newTitle = textOf(ask.newTitle)
          return {
            result: await saveMilestone($, repo, {
              title,
              ...(newTitle ? { newTitle } : {}),
              ...(typeof ask.due === 'string' ? { due: ask.due.trim() } : {}),
              ...(typeof ask.description === 'string' ? { description: ask.description } : {}),
              ...(ask.close === true ? { close: true } : {}),
              ...(ask.reopen === true ? { reopen: true } : {}),
            }),
          }
        } catch (cause) {
          return { deny: `Couldn't change the milestone: ${messageOf(cause)}` }
        }
      })
    }),
  ).catch(($, _e, next) => toolFailed($, next, 'milestone'))

  // Moving the Status of the issue the person started is part of working on it, so it doesn't ask, and nor does starting
  // on an issue. Any other change
  // asks, as a tool that changes something does; a rule that allows or denies still stands, and so does an
  // organization's ceiling that keeps the tool at asking.
  on('tool.check', { tool: UPDATE_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision !== 'ask' || !mayAllow(e.ceiling)) return verdict
    const changes = changesOf(e.input)
    if (!changes) return verdict
    // Starting on an issue, with nothing else, is what Start does when pressed: it doesn't ask either.
    const { number, ...rest } = changes
    if ((e.input as { start?: unknown }).start === true && Object.keys(rest).length === 0) return { decision: 'allow' as const }
    const doing = await read($, working)
    return doing && number === doing.number && statusOnly(changes) ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on issue_update'))

  // Ticking boxes is how work on an issue reports its progress, so it needs no permission prompt, as it never has. A rule
  // that denies it still stands, and so does an organization's ceiling that keeps the tool at asking.
  on('tool.check', { tool: TICK_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    return verdict.decision === 'ask' && mayAllow(e.ceiling) ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on tick'))

  // Reading the board changes nothing, so it needs no permission prompt; a rule that denies it still stands, and so
  // does an organization's ceiling that keeps the tool at asking.
  on('tool.check', { tool: ISSUES_TOOL }, async ($, e, next) => {
    const verdict = await next(e)
    return verdict.decision === 'ask' && mayAllow(e.ceiling) ? { decision: 'allow' as const } : verdict
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on issues'))

  // Closing an epic whose sub-issues are still open asks the person first, whatever their rules allow: the sub-issues
  // would stay open under a closed parent. A subagent's call is refused instead, since nobody may be watching for the
  // prompt, and the reason tells the agent what to do. A rule that denies the command still stands.
  on('tool.check', { tool: 'Bash' }, async ($, e, next) => {
    const verdict = await next(e)
    const command = (e.input as { command?: unknown }).command
    if (verdict.decision === 'deny' || typeof command !== 'string' || !CLOSE.test(command)) return verdict
    const issues = (await read($, board))?.issues ?? []
    const epics = [...command.matchAll(new RegExp(CLOSE.source, 'g'))].flatMap(match => {
      const issue = issues.find(one => one.number === Number(match[1]))
      const open = (issue?.subIssues?.total ?? 0) - (issue?.subIssues?.completed ?? 0)
      return issue && open > 0 ? [`#${issue.number} is an epic with ${open} open ${open === 1 ? 'sub-issue' : 'sub-issues'}`] : []
    })
    if (epics.length === 0) return verdict
    const why = `${epics.join('; ')}. Closing it leaves them open under a closed epic.`
    if (e.agentId !== undefined) return { decision: 'deny' as const, reason: `${why} Close or move the sub-issues first, or leave the epic open and say so in your answer.` }
    return { decision: 'ask' as const, reason: why }
  }).catch(($, e, next) => fallBack($, e, next, 'tool.check on Bash'))

  // While Claude works on an issue the person started in this session, the system prompt names it, so compaction
  // doesn't lose it. The section changes only when the person starts another, to keep the prompt cache. In background
  // start mode, a fixed section before it tells Claude to hand issues to workers and see their pull requests through,
  // with the working note on or off.
  // While the capture setting is on, a fixed section first tells Claude to capture work it finds rather than list it.
  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const capturing = settings.capture ? [{ id: 'issue-board:capture', text: captureSection(), scope: 'session' as const }] : []
    const orchestrating = settings.startMode === 'background' ? [{ id: 'issue-board:orchestrator', text: orchestratorSection(), scope: 'session' as const }] : []
    const now = settings.workingNote ? await read($, working) : null
    const mine = !!now?.sessionId && now.sessionId === (await $.session.id().catch(() => undefined))
    const doing = now && mine ? [{ id: 'issue-board:working', text: workingSection(now, settings.closesWhenTicked), scope: 'session' as const }] : []
    if (capturing.length === 0 && orchestrating.length === 0 && doing.length === 0) return composed
    for (const section of capturing) countSection(section.id, section.text, 'capture note')
    for (const section of orchestrating) countSection(section.id, section.text, 'orchestrator note')
    for (const section of doing) countSection(section.id, section.text, 'working note')

    return { sections: [...composed.sections, ...capturing, ...orchestrating, ...doing] }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text, Button, Link } = elements
    const { link, keep, choice } = partsOf(elements)
    const problems = (await read($, access))?.problems ?? []
    const width = Math.max(40, e.props.bodyColumns)
    const roomy = width >= 72
    // Room for the sparklines and the ticked meter.
    const wide = width >= 100
    const now = await read($, board)
    const failure = await read($, error)
    const busy = await read($, loading)
    const chosen = await read($, filter)
    const open = await read($, expanded)
    const armedNow = await read($, armed)
    const arming = armedNow?.kind === 'merge-all'
    const armedPr = armedNow?.kind === 'pr' ? armedNow.number : null
    const who = await read($, viewer)
    const typed = await read($, query)
    const here = await read($, branch)
    const doing = await read($, working)
    const changing = await read($, editing)
    const offered = await read($, palette)
    const armedClose = armedNow?.kind === 'close' ? armedNow.number : null
    const fields = await read($, typing)
    const said = await read($, talk)
    const shownPr = await read($, openPr)
    const planned = await read($, setup)
    const picked = await read($, groupBy)
    const opened = await read($, unfolded)
    const triaged = await read($, triage)
    const watched = await read($, runs)
    const working$ = await read($, workers)
    const launches = await read($, launching)
    const adopting = await read($, adoption)
    const proposed = await read($, proposal)
    // The issue Start sent Claude in this session: its Start says so rather than starting it again.
    const startedHere = doing?.started && doing.sessionId !== undefined && doing.sessionId === (await $.session.id().catch(() => undefined)) ? doing.number : null
    const clock = Date.now()
    // The mobile app draws no text field: its table hands out one that draws nothing.
    const Input = 'Input' in elements && e.surface !== 'mobile' ? elements.Input : undefined
    const Markdown = elements.Markdown

    // Start: the issue is the one Claude is on, and Claude gets it. Its button says so from the press on.
    const start = (issue: Issue) =>
      launch($, issue, 'start', async () => {
        // A start message Edit first left in the prompt box is spent: sending it later doesn't start the issue again.
        await update($, drafted, () => null)
        await track($, issue, true)
        const listed = await makeTasks($, issue)
        // The board's own prompt.submit hook doesn't see a prompt the board submits, so this message goes without the
        // issue's copy and lists the boxes itself.
        await submit($, 'start prompts', { text: startPrompt(issue, listed > 0), asUser: true })
        $.ui.toast(`Sent #${issue.number} to Claude`)
        await claim($, issue)
        return true
      })

    const flip = async (issue: Issue, box: number, done: boolean) => {
      try {
        await tick($, issue.number, [box], done)
        $.ui.toast(`${done ? 'Ticked' : 'Unticked'} box ${box} on #${issue.number}`)
          } catch (cause) {
        toastFailure($, `Couldn't change box ${box} on #${issue.number}`, cause)
      }
    }

    const closeOut = async (pr: PullRequest) => {
      await disarm($, 'pr')
      await submit($, 'other prompts', { text: closeOutPrompt(pr), asUser: true })
      $.ui.toast(`Sent PR #${pr.number} to Claude to finish and merge`)
    }

    // Merge all merges every open pull request, so it asks once more before it goes.
    const closeOutAll = async (prs: PullRequest[]) => {
      await disarm($, 'merge-all')
      // The pull requests it was asked for may have merged while it waited on its confirm.
      if (prs.length === 0) {
        $.ui.toast('No pull requests are open now, so there is nothing to merge.')
        return
      }
      await submit($, 'other prompts', { text: closeOutAllPrompt(prs), asUser: true })
      $.ui.toast(`Sent ${prs.length} ${prs.length === 1 ? 'PR' : 'PRs'} to Claude to finish and merge`)
    }
    const arm = (to: boolean) => () => void (to ? update($, armed, (): Armed => ({ kind: 'merge-all' })) : disarm($, 'merge-all'))

    // One card at a time, so its letter keys always work; an opened card is scrolled into view.
    const toggle = (number: number) => async () => {
      const opening = open !== number
      await update($, expanded, () => (opening ? number : null))
      await update($, editing, () => null)
      if (opening) await $.ui.scroll({ to: { key: `card-${number}` }, in: PANE }).catch(() => undefined)
      if (opening) await loadComments($, number)
      const issue = opening ? now?.issues.find(one => one.number === number) : undefined
      if (issue && (project?.fields ?? []).some(field => !/^(status|priority)$/i.test(field.name))) await readValues($, issue)
    }
    const togglePr = (number: number) => () => void update($, openPr, was => (was === number ? null : number))

    const meter = (done: number, total: number, cells: number) => {
      const [filled, empty] = bar({ done, total }, cells)
      return (
        <Text>
          <Text color={tone({ done, total })}>{filled}</Text>
          <Text color="inactive" dimColor>
            {empty}
          </Text>
        </Text>
      )
    }

    // The header's right: when the board last synced, and Refresh. It keeps its width; the repo's name is cut instead.
    const sync = (
      <Box flexDirection="row" gap={1} flexShrink={0}>
        <Text color={busy ? 'warning' : undefined} dimColor={!busy}>
          {busy ? '◌ syncing…' : now ? `⟳ ${ago(now.fetchedAt, clock)}` : ''}
        </Text>
        <Button key="refresh" hotkey="r" dimColor onPress={() => void refresh($)}>
          Refresh
        </Button>
      </Box>
    )
    const repoName = (
      <Text wrap="truncate-end">
        <Text color="claude">◆ </Text>
        <Text bold>{now ? now.repo : 'GitHub'}</Text>
      </Text>
    )
    // Before there is a board: the repo and the sync, nothing to total yet.
    const header = (
      <Box flexDirection="row" justifyContent="space-between">
        {repoName}
        {sync}
      </Box>
    )

    // What the last permission check found missing, each with its fix.
    const blocked = problems.some(problem => problem.blocks)
    const setupCard = problems.length > 0 && (
      <Box flexDirection="column" borderStyle="round" borderColor={blocked ? 'error' : 'warning'} paddingX={1} marginTop={1}>
        <Text color={blocked ? 'error' : 'warning'} bold>
          {blocked ? '✗ Setup needed' : '⚠ The board is limited'}
        </Text>
        {problems.map(problem => (
          <Box key={`problem-${problem.id}`} flexDirection="column" marginTop={1}>
            <Text bold wrap="wrap">
              {problem.title}
            </Text>
            <Text dimColor wrap="wrap">
              {problem.detail}
            </Text>
            <Text wrap="wrap">{problem.fix}</Text>
            {problem.command && (
              <Box flexDirection="row">
                <Button key={`copy-fix-${problem.id}`} onPress={press => void copyFix($, problem, press.surface)}>
                  Copy command
                </Button>
              </Box>
            )}
            {problem.url && !problem.command && <Link href={problem.url} label={`↗ ${problem.url.replace(/^https:\/\//, '')}`} />}
          </Box>
        ))}
        <Box flexDirection="row" marginTop={1}>
          <Button key="recheck" variant="primary" onPress={() => void recheck($)}>
            Check again
          </Button>
        </Box>
      </Box>
    )

    // The one-time ask before the board writes to the project it reads: what it would write and what that costs. Setup
    // showing asks the same through Apply, so this waits.
    const asked = !planned && now?.project ? now.project : null
    const asking = asked ? adoptAsk(asked, adopting) : null
    const adoptCard = asking && asked && (
      <Box key="adopt-card" flexDirection="column" borderStyle="round" borderColor="warning" paddingX={1} marginTop={1}>
        <Text color="warning" bold wrap="wrap">
          {`⚠ ${asking.title}`}
        </Text>
        {asking.lines.map((line, index) => (
          <Text key={`adopt-line-${index}`} dimColor={index > 0} wrap="wrap">
            {line}
          </Text>
        ))}
        <Box flexDirection="row" gap={1} marginTop={1} flexWrap="wrap">
          <Button key="adopt-yes" variant="primary" onPress={() => void adoptFromPrompt($, asked)}>
            Let it write
          </Button>
          <Button key="adopt-no" dimColor onPress={() => void declineFromPrompt($, asked)}>
            Keep read-only
          </Button>
          {link(asked.url)}
        </Box>
      </Box>
    )

    // `/issues statuses`: Which Status is which alone, picked among the project's own options. Save keeps it in the
    // store; adding an option the project lacks stays in /issues setup.
    const mapping = await read($, statusPicks)
    const pickStatus = (role: Role, id: string | null) => () =>
      void update($, statusPicks, was => {
        if (!was) return was
        // One option plays one part: picking it for this role takes it from any other.
        const picks: Roles = Object.fromEntries(Object.entries(was.picks).filter(([other, one]) => other !== role && one !== id))
        return { ...was, picks: id === null ? picks : { ...picks, [role]: id } }
      })
    const statusesCard = mapping && (
      <Box key="statuses-card" flexDirection="column" borderStyle="round" borderColor="suggestion" paddingX={1} marginTop={1}>
        <Text color="suggestion" bold>
          {`⚙ Which Status is which in ${mapping.project.title}`}
        </Text>
        <Text dimColor wrap="wrap">
          Pick the option that plays each part, or none to turn that part off. Save keeps it here and changes nothing on GitHub.
        </Text>
        {ROLE_ORDER.map(role => {
          const pick = mapping.picks[role] ?? null
          const option = (key: string, label: string, id: string | null) => choice(`statuses-${role}-${key}`, label, pick === id, pickStatus(role, id))
          return (
            <Box key={`statuses-${role}`} flexDirection="row" gap={1} flexWrap="wrap">
              <Text dimColor>{`${ROLE_NAMES[role]}${role === 'backlog' ? ' (folds)' : ''}`}</Text>
              {mapping.options.map(one => option(one.id, one.name, one.id))}
              {option('none', 'none', null)}
            </Box>
          )
        })}
        <Box flexDirection="row" gap={1} marginTop={1}>
          <Button key="statuses-save" variant="primary" onPress={() => void saveStatuses($)}>
            Save
          </Button>
          <Button key="statuses-cancel" dimColor onPress={() => void update($, statusPicks, () => null)}>
            Cancel
          </Button>
        </Box>
      </Box>
    )

    // `/issues labels`: which label or issue type Bugs goes by, and without a project which label Later does, picked
    // among the repo's own. Save keeps it in the store.
    const marking = await read($, markerPicks)
    const pickMarker = (picks: Partial<Markers>) => () => void update($, markerPicks, was => was && { ...was, picks: { ...was.picks, ...picks } })
    const labelsCard = marking && (
      <Box key="labels-card" flexDirection="column" borderStyle="round" borderColor="suggestion" paddingX={1} marginTop={1}>
        <Text color="suggestion" bold>
          ⚙ Which labels Bugs and Later go by
        </Text>
        <Text dimColor wrap="wrap">
          {marking.later
            ? 'Pick what marks a bug, and the label for Later. Save keeps it here and changes nothing on GitHub.'
            : 'Pick what marks a bug. With a project, Later goes by Priority. Save keeps it here and changes nothing on GitHub.'}
        </Text>
        <Box key="labels-bug" flexDirection="row" gap={1} flexWrap="wrap">
          <Text dimColor>Bugs</Text>
          {marking.types.map(type =>
            choice(`labels-bug-type-${type}`, `${type} type`, 'type' in marking.picks.bug && marking.picks.bug.type === type, pickMarker({ bug: { type } })),
          )}
          {marking.labels.map(label =>
            choice(`labels-bug-${label}`, label, 'label' in marking.picks.bug && marking.picks.bug.label === label, pickMarker({ bug: { label } })),
          )}
        </Box>
        {marking.later && (
          <Box key="labels-later" flexDirection="row" gap={1} flexWrap="wrap">
            <Text dimColor>Later</Text>
            {marking.labels.map(label => choice(`labels-later-${label}`, label, marking.picks.later === label, pickMarker({ later: label })))}
          </Box>
        )}
        <Box flexDirection="row" gap={1} marginTop={1}>
          <Button key="labels-save" variant="primary" onPress={() => void saveMarkerPicks($)}>
            Save
          </Button>
          <Button key="labels-cancel" dimColor onPress={() => void update($, markerPicks, () => null)}>
            Cancel
          </Button>
        </Box>
      </Box>
    )

    // `/issues setup`: the project it would use, what it would change, what only the project's settings can turn on,
    // and Apply, the one ask before anything changes. While Apply runs, each change is marked as it goes.
    const MARKS = { running: ['◌', 'warning'], done: ['✓', 'success'], failed: ['✗', 'error'], skipped: ['–', 'inactive'] } as const
    const facts = planned && 'facts' in planned ? planned.facts : undefined
    const chosenProject = facts && planned && 'chosen' in planned ? facts.projects.find(one => one.id === planned.chosen) : undefined
    const choose = (id: string | null) => () =>
      void update($, setup, was => {
        if (was?.phase !== 'ready') return was
        const roles = picksFor(was.facts, id)
        return { ...was, chosen: id, roles, steps: stepsOf(was.facts, id, was.areas, roles) }
      })
    const typeAreas = (text: string) =>
      void update($, setup, was => (was?.phase === 'ready' ? { ...was, areas: text, steps: stepsOf(was.facts, was.chosen, text, was.roles) } : was))
    const pickRole = (role: Role, name: string | null) => () =>
      void update($, setup, was => {
        if (was?.phase !== 'ready') return was
        const roles = { ...was.roles, [role]: name }
        return { ...was, roles, steps: stepsOf(was.facts, was.chosen, was.areas, roles) }
      })
    const manual = facts ? automationsOff(chosenProject) : []
    const unwanted = facts && planned && 'roles' in planned ? automationsOn(chosenProject, settings.autoMove && planned.roles.done !== null) : []
    const setupPlan = planned && (
      <Box key="setup-plan" flexDirection="column" borderStyle="round" borderColor="suggestion" paddingX={1} marginTop={1}>
        <Text color="suggestion" bold>
          {`⚙ Set up ${facts?.repo.name ?? 'the repo'} for the board`}
        </Text>
        {planned.phase === 'reading' && <Text dimColor>◌ Reading the repo, its project and its issues…</Text>}
        {planned.phase === 'failed' && (
          <Box flexDirection="column">
            <Text color="error" wrap="wrap">{`Couldn't read what setup needs: ${planned.message}`}</Text>
            <Text dimColor>/issues check says what is missing and how to fix it.</Text>
          </Box>
        )}
        {facts && 'steps' in planned && (
          <Box flexDirection="column">
            <Box flexDirection="row" gap={1} flexWrap="wrap" marginTop={1}>
              <Text dimColor>Project</Text>
              {facts.projects.length === 0 && <Text>{`none is linked to ${facts.repo.name}`}</Text>}
              {facts.projects.length === 1 && chosenProject && <Text bold>{`${chosenProject.title} (#${chosenProject.number})`}</Text>}
              {facts.projects.length > 1 &&
                facts.projects.map(one =>
                  choice(`setup-project-${one.number}`, `${one.title} #${one.number}`, one.id === planned.chosen, planned.phase === 'ready' ? choose(one.id) : () => undefined),
                )}
              {chosenProject && link(chosenProject.url)}
            </Box>
            {facts.adopted !== undefined && (
              <Box key="setup-adopted" flexDirection="row" gap={1} flexWrap="wrap">
                <Text dimColor>Writes</Text>
                {facts.adopted ? (
                  <Text>{`the board may write to ${facts.projects.find(one => one.id === facts.adopted)?.title ?? 'a project of this repo'}`}</Text>
                ) : (
                  <Text>{chosenProject ? `none: the board only reads ${chosenProject.title} until Apply` : 'none: the board writes to no project'}</Text>
                )}
                {facts.adopted && facts.granted && <Text dimColor>{"granted by this repo's .claude/settings.json; edit writeProjects there to release it"}</Text>}
                {facts.adopted && !facts.granted && planned.phase !== 'applying' && (
                  <Button key="setup-release" dimColor onPress={() => void releaseFromSetup($, facts.projects.find(one => one.id === facts.adopted))}>
                    Release
                  </Button>
                )}
              </Box>
            )}
            {planned.steps.length === 0 ? (
              <Text color="success">✓ Nothing to change: the repo and its project are set up for the board.</Text>
            ) : (
              <Box flexDirection="column" marginTop={1}>
                <Text bold>{planned.phase === 'ready' ? 'Apply will:' : 'Changes:'}</Text>
                {planned.steps.map(step => {
                  const [mark, color] = step.state ? MARKS[step.state] : (['✚', 'suggestion'] as const)
                  return (
                    <Box key={`setup-step-${step.id}`} flexDirection="column">
                      <Text wrap="wrap">
                        <Text color={color}>{`${mark} `}</Text>
                        <Text>{step.title}</Text>
                      </Text>
                      {step.message && (
                        <Text dimColor wrap="wrap">
                          {`  ${step.message}`}
                        </Text>
                      )}
                    </Box>
                  )
                })}
              </Box>
            )}
            {planned.phase === 'ready' && Input && !facts.labels.some(label => label.startsWith('area:')) && (
              <Box flexDirection="row" marginTop={1}>
                <Input
                  key="setup-areas"
                  label="area labels to create: "
                  placeholder="such as simulation, interface"
                  value={planned.areas}
                  submitLabel="update"
                  onInput={typeAreas}
                  onSubmit={typeAreas}
                />
              </Box>
            )}
            {chosenProject?.status && (
              <Box key="setup-roles" flexDirection="column" marginTop={1}>
                <Text bold>Which Status is which</Text>
                {ROLE_ORDER.map(role => {
                  const options = statusOptionsOf(chosenProject).map(one => one.name)
                  const own = ROLE_NAMES[role]
                  const pick = planned.roles[role]
                  const ready = planned.phase === 'ready'
                  const option = (key: string, label: string, name: string | null) =>
                    choice(`setup-role-${role}-${key}`, label, pick === name, ready ? pickRole(role, name) : () => undefined)
                  return (
                    <Box key={`setup-role-${role}`} flexDirection="row" gap={1} flexWrap="wrap">
                      <Text dimColor>{`${own}${role === 'backlog' ? ' (folds)' : ''}`}</Text>
                      {options.map(name => option(name, name, name))}
                      {!options.some(name => name.toLowerCase() === own.toLowerCase()) && option('add', `＋ ${own}`, own)}
                      {option('none', 'none', null)}
                    </Box>
                  )
                })}
              </Box>
            )}
            {(manual.length > 0 || unwanted.length > 0 || addsAsTodo(chosenProject, planned.roles.inbox)) && (
              <Box flexDirection="column" marginTop={1}>
                <Text color="warning">In the project's Workflows settings, by hand:</Text>
                {manual.length > 0 && <Text color="warning" wrap="wrap">{`  · turn on ${manual.join(', ')}`}</Text>}
                {unwanted.length > 0 && (
                  <Text color="warning" wrap="wrap">
                    {`  · turn off ${unwanted.join(', ')}: it marks every closed issue Done, even an abandoned one; the board moves issues closed as completed`}
                  </Text>
                )}
                {addsAsTodo(chosenProject, planned.roles.inbox) && (
                  <Text color="warning" wrap="wrap">
                    {`  · new issues arrive with Status Todo, GitHub's default, so they skip the Inbox: open Item added to project and set its Status to ${planned.roles.inbox}. Once it's set, delete the Todo option, which this note looks for.`}
                  </Text>
                )}
                {chosenProject && <Link href={`${chosenProject.url}/workflows`} label="↗ Workflows" />}
              </Box>
            )}
            {!facts.hasTemplate && (
              <Box flexDirection="row" gap={1} flexWrap="wrap" marginTop={1}>
                <Text dimColor>No issue template has an Acceptance list.</Text>
                <Button
                  key="setup-template"
                  dimColor
                  onPress={() => void submit($, 'other prompts', { text: templatePrompt(facts.repo.name), asUser: true }).then(() => $.ui.toast('Asked Claude for an issue template, as a pull request to review'))}
                >
                  Have Claude add one
                </Button>
              </Box>
            )}
            <Box flexDirection="row" gap={1} marginTop={1}>
              {planned.phase === 'ready' && planned.steps.length > 0 && (
                <Button key="setup-apply" variant="primary" onPress={() => void within('setup', () => applySetup($))}>
                  Apply
                </Button>
              )}
              {planned.phase === 'applying' && <Text color="warning">◌ Applying…</Text>}
              {planned.phase !== 'applying' && (
                <Button key="setup-close" dimColor onPress={() => void update($, setup, () => null)}>
                  {planned.phase === 'ready' && planned.steps.length > 0 ? 'Cancel' : 'Close'}
                </Button>
              )}
            </Box>
          </Box>
        )}
        {planned.phase === 'failed' && (
          <Box flexDirection="row" marginTop={1}>
            <Button key="setup-close" dimColor onPress={() => void update($, setup, () => null)}>
              Close
            </Button>
          </Box>
        )}
      </Box>
    )

    if (!now) {
      return (
        <Box flexDirection="column">
          {header}
          {statusesCard}
          {labelsCard}
          {setupPlan}
          {setupCard ||
            (failure ? (
            <Box flexDirection="column" borderStyle="round" borderColor="error" paddingX={1} marginTop={1}>
              <Text color="error" bold>
                ✗ Couldn't reach GitHub
              </Text>
              <Text>{failure}</Text>
              <Text dimColor>Press r to try again, or run /issues check.</Text>
            </Box>
          ) : (
            <Box marginTop={1}>
              <Text dimColor>◌ Fetching issues and pull requests…</Text>
            </Box>
          ))}
        </Box>
      )
    }

    // Without a project the board works from labels: Active and Future, grouped by area.
    const project = now.project ?? null
    // The tabs: the project's views with filters, then All and Closed; or the built-in filters. A tab chosen that is no
    // longer there, such as Now once the views are the tabs, gives way to the first.
    const tabs = filtersFor(project)
    const tab = tabOf(tabs, chosen)
    const shownTab = tab.id
    const marks = await markersNow($, now)
    const tabTests = new Map(tabs.map(one => [one.id, tabTest(one, project, marks)] as const))
    const inTab = (one: Tab, issue: Issue) => tabTests.get(one.id)?.(issue, who) ?? false
    // A view's tab groups as the view does, when the board can: Status, epic, or another field it read. The grouping
    // named for the view's field shows among the others while its tab does.
    const viewGrouping = viewGroupingOf(tab.view, project)
    const viewField = viewGrouping?.by === 'view' ? viewGrouping.field : null
    const grouping = groupingOf(picked, viewGrouping, Boolean(project))
    // The terms of the view's filter the board can't apply, for the note under the heading.
    const unknownTerms = tab.view ? viewMatchOf(tab.view.filter, project).unknown : []
    // Whether an issue is under the filter and the search. The open card stays in the list whether or not, until it is
    // collapsed, so setting its Priority or Status doesn't take it away while it's being changed.
    const kept = (issue: Issue) => inTab(tab, issue) && searched(typed, issue)
    const shown = now.issues.filter(issue => open === issue.number || kept(issue))
    const closedNow = shownTab === 'closed' ? await read($, recent) : null
    // The project's fields beyond Status and Priority, and what the open card's issue has in them.
    const otherFields = (project?.fields ?? []).filter(field => !/^(status|priority)$/i.test(field.name))
    const fieldValues = await read($, values)
    const more = await read($, editorMore)
    // The sections above the issues: open or folded as the person left them, else folded on a short pane.
    const opened$ = await read($, sections)
    const sectionOpen = (key: string) => opened$[key] ?? e.props.scroll.bodyRows >= SHORT_ROWS
    const fold = (key: string) => () => void update($, sections, was => ({ ...was, [key]: !sectionOpen(key) })).then(() => save($))
    const heading = (key: string, title: string) => (
      <Box key={`section-head-${key}`}>
        <Button key={`section-${key}`} plain hover={{ bold: true }} onPress={fold(key)}>
          {`${sectionOpen(key) ? '▾' : '▸'} ${title}`}
        </Button>
      </Box>
    )
    // One card open: its letter keys work.
    const single = open !== null && shown.some(issue => issue.number === open)
    const filterName = tab.name
    const bugs = now.issues.filter(issue => isBug(issue, marks)).length
    const failing = now.prs.filter(pr => pr.ci === 'fail').length
    const overall = sumProgress(shown)

    const stat = (glyph: string, color: ThemeKey, value: number, label: string) => (
      <Text>
        <Text color={color}>{glyph}</Text>
        <Text bold>{` ${value}`}</Text>
        <Text dimColor>{` ${label}`}</Text>
      </Text>
    )

    // One line: the repo and its totals at the left, the sync at the right. The ticked meter needs the room.
    // The repo and its counts wrap onto a second line in a narrow pane rather than squeeze a count into two; the sync
    // and Refresh keep their place at the right.
    const topLine = (
      <Box flexDirection="row" justifyContent="space-between" gap={1}>
        <Box flexDirection="row" columnGap={2} flexWrap="wrap" flexShrink={1}>
          {repoName}
          {stat('●', 'claude', now.issues.length, now.issues.length === 1 ? 'issue' : 'issues')}
          {stat('▲', bugs > 0 ? 'error' : 'inactive', bugs, bugs === 1 ? 'bug' : 'bugs')}
          {stat('⇄', 'suggestion', now.prs.length, now.prs.length === 1 ? 'PR' : 'PRs')}
          {failing > 0 && stat('✗', 'error', failing, 'failing')}
          {wide && overall.total > 0 && (
            <Text>
              {meter(overall.done, overall.total, 6)}
              <Text dimColor>{` ${Math.round((overall.done / overall.total) * 100)}%`}</Text>
            </Text>
          )}
        </Box>
        {sync}
      </Box>
    )

    // A board kept from before velocity was fetched has none until it refreshes.
    const velocity = now.velocity ?? { closed: [], merged: [] }
    const trend = (label: string, color: ThemeKey, counts: number[]) => (
      <Text>
        <Text dimColor>{`${label} `}</Text>
        <Text color={color}>{spark(counts)}</Text>
        <Text bold>{` ${counts.reduce((sum, count) => sum + count, 0)}`}</Text>
      </Text>
    )
    const trends = wide && velocity.closed.length > 0 && (
      <Box flexDirection="row" gap={3} flexWrap="wrap">
        {trend('closed', 'success', velocity.closed)}
        {trend('merged', 'suggestion', velocity.merged)}
        <Text dimColor>{`last ${WEEKS} weeks`}</Text>
      </Box>
    )

    // The Issues heading: its filters, the search and the grouping, which act on the issues below it alone. With a
    // project the first two filters read Priority, and the grouping can be Status.
    const groupings = [...GROUPINGS.filter(one => one.id !== 'status' || project), ...(viewField ? [{ id: 'view' as const, label: viewField }] : [])]
    // A tab's label: its name and how many open issues it holds; Closed's count isn't known until it is read.
    const tabLabel = (one: Tab) => (one.id === 'closed' ? one.name : `${one.name} ${now.issues.filter(issue => inTab(one, issue)).length}`)
    const issuesHeading = (
      <Box flexDirection="row" gap={1} flexWrap="wrap">
        <Text bold color="claude">
          Issues
        </Text>
        {tabs.map(one => choice(`filter-${one.id}`, tabLabel(one), one.id === shownTab, () => void pickTab($, one, project), { hotkey: one.hotkey }))}
        {Input && (
          <Input
            key="search"
            label="⌕ "
            placeholder="search titles, #numbers, labels"
            value={typed}
            submitLabel="search"
            onInput={text => void update($, query, () => text)}
            onSubmit={text => void update($, query, () => text)}
          />
        )}
        <Text dimColor>by</Text>
        {groupings.map(one => choice(`group-${one.id}`, one.label, one.id === grouping, () => void update($, groupBy, () => one.id)))}
      </Box>
    )

    // The plan Claude proposed with project_plan: a row per change, grouped by issue, each with a box to tick and
    // Claude's reason. Apply writes the ticked rows; Discard drops the plan. A row that failed stays, saying why. A row
    // the board shows as made already, as when Claude made it another way, isn't drawn.
    const planRows = proposed ? rowsToMake(proposed.rows, now) : []
    const planTicked = planRows.filter(row => row.picked).length
    // The rows grouped: the repo's labels first, then each issue, then the project's views.
    const planGroups = [...new Set(planRows.map(row => groupOf(row.change)))]
    const pickRow = (id: string) => () => void update($, proposal, was => was && { ...was, rows: was.rows.map(row => (row.id === id ? { ...row, picked: !row.picked } : row)) })
    const planCard = proposed && planRows.length > 0 && (
      <Box key="plan-card" flexDirection="column" borderStyle="round" borderColor="suggestion" paddingX={1} marginTop={1}>
        <Text color="suggestion" bold>{`Claude's plan · ${sizeText(planRows.map(row => row.change))}`}</Text>
        <Text dimColor wrap="wrap">
          {kindsText(planRows.map(row => row.change))}
        </Text>
        {planGroups.map(group => (
          <Box key={`plan-${typeof group === 'number' ? `issue-${group}` : `${group}s`}`} flexDirection="column" marginTop={1}>
            {group === 'label' ? (
              <Text color="claude" bold>
                {"The repo's labels"}
              </Text>
            ) : group === 'view' ? (
              <Text color="claude" bold wrap="truncate-end">{`${now.project?.title ?? 'Project'} views`}</Text>
            ) : (
              <Text wrap="truncate-end">
                <Text color="claude" bold>{`#${group} `}</Text>
                {now.issues.find(one => one.number === group)?.title ?? ''}
              </Text>
            )}
            {planRows
              .filter(row => groupOf(row.change) === group)
              .map(row => (
                <Box key={`plan-row-${row.id}`} flexDirection="column">
                  <Box flexDirection="row" gap={1} flexWrap="wrap">
                    {choice(`plan-pick-${row.id}`, `${row.picked ? '☑' : '☐'} ${cardParts(row.change).head}`, row.picked, pickRow(row.id))}
                    {cardParts(row.change).detail && <Text wrap="wrap">{cardParts(row.change).detail}</Text>}
                    <Text dimColor wrap="wrap">
                      {row.reason}
                    </Text>
                  </Box>
                  {viewNoteOf(row.change) && (
                    <Text color="warning" wrap="wrap">
                      {`⚠ ${viewNoteOf(row.change)}`}
                    </Text>
                  )}
                  {row.failed && <Text color="error" wrap="wrap">{`✗ ${row.failed}`}</Text>}
                </Box>
              ))}
          </Box>
        ))}
        {proposed.note && (
          <Box marginTop={1}>
            <Text color="warning" wrap="wrap">
              {proposed.note}
            </Text>
          </Box>
        )}
        {proposed.applying ? (
          <Box marginTop={1}>
            <Text color="warning">◌ Applying the plan…</Text>
          </Box>
        ) : (
          <Box flexDirection="row" gap={1} marginTop={1} flexWrap="wrap">
            <Button key="plan-apply" variant="primary" dimColor={planTicked === 0} onPress={() => void applyFromCard($, proposed.id)}>
              {`✓ Apply ${planTicked} of ${planRows.length}`}
            </Button>
            <Button key="plan-discard" dimColor onPress={() => void update($, proposal, () => null)}>
              Discard
            </Button>
          </Box>
        )}
      </Box>
    )

    // A pull request on one row: CI, number, a ⚙ while a background agent owns its branch, title, the issue it is for,
    // a review mark, why it can't merge yet and whether it is this branch's, then its diff counts and Finish & merge. Every part but the title keeps its width,
    // and the title is cut to what is left; a narrow pane drops parts in prRowRoom's order rather than wrap the row.
    // The title opens its details beneath: branch, author, age, review, failing checks and its link.
    const prRow = (pr: PullRequest) => {
      const badge = ciBadge[pr.ci]
      const review = reviewBadge(pr)
      const isOpen = shownPr === pr.number
      const mine = here !== null && pr.branch === here
      // The counts stay on one line, `+12 −3`, never one above the other.
      const size = `+${pr.additions} −${pr.deletions}`
      // The issue it closes or refers to, on the row: the first it names.
      const forIssue = (pr.issues ?? [])[0]
      const forText = forIssue ? `→ #${forIssue}` : ''
      // Why it can't merge yet: conflicts or behind its base, review threads still open, and who is asked to review.
      const merge = mergeNoteOf(pr)
      const threads = pr.openThreads ?? 0
      const threadText = threads > 0 ? `${threads} open ${threads === 1 ? 'thread' : 'threads'}` : ''
      const askedText = (pr.reviewers ?? []).length > 0 ? `asks ${(pr.reviewers ?? []).slice(0, 2).join(', ')}${(pr.reviewers ?? []).length > 2 ? ` +${(pr.reviewers ?? []).length - 2}` : ''}` : ''
      // A background agent that may still push to its branch, and why Finish & merge asks first: that agent, or CI
      // that hasn't passed.
      const owner = workerOfPr(pr, working$)
      const risk = closeOutRisk(pr, owner)
      const asking = risk !== null && armedPr === pr.number
      const gapped = (text: string) => (text ? cells(text) + 1 : 0)
      const fits = prRowRoom(width, cells(badge.text) + 1 + cells(`#${pr.number}`) + 1 + (mine ? 2 : 0) + (owner ? 2 : 0), {
        asked: gapped(askedText),
        threads: gapped(threadText),
        size: roomy ? gapped(size) : 0,
        issue: gapped(forText),
        merge: gapped(merge?.text ?? ''),
        review: review ? 2 : 0,
      })
      const { shown } = fits
      return (
        <Box key={`pr-row-${pr.number}`} flexDirection="column">
          <Box flexDirection="row" justifyContent="space-between" gap={1}>
            <Box flexDirection="row" gap={1} flexShrink={1}>
              {keep(
                <Text color={badge.color} inverse bold>
                  {badge.text}
                </Text>,
              )}
              {keep(<Text color="suggestion" bold>{`#${pr.number}`}</Text>)}
              {owner && keep(<Text color={workerBadge(owner.status).color}>⚙</Text>)}
              <Button key={`pr-${pr.number}`} plain hover={{ bold: true }} onPress={togglePr(pr.number)}>
                {fit(pr.title, fits.title)}
              </Button>
              {shown.issue && keep(<Text color="claude">{forText}</Text>)}
              {shown.review && review && keep(<Text color={review.color}>{pr.isDraft ? '◌' : review.text.slice(0, 1)}</Text>)}
              {shown.merge && merge && keep(<Text color={merge.color}>{merge.text}</Text>)}
              {shown.threads && keep(<Text color="warning">{threadText}</Text>)}
              {shown.asked && keep(<Text dimColor>{askedText}</Text>)}
              {mine &&
                keep(
                  <Text color="claude" bold>
                    ◆
                  </Text>,
                )}
            </Box>
            <Box flexDirection="row" gap={1} flexShrink={0}>
              {shown.size && (
                <Text>
                  <Text color="success">{`+${pr.additions}`}</Text>
                  <Text color="error">{` −${pr.deletions}`}</Text>
                </Text>
              )}
              <Button key={`close-out-${pr.number}`} dimColor hover={{ dimColor: false, color: 'suggestion' }} onPress={() => void (risk ? update($, armed, (): Armed => ({ kind: 'pr', number: pr.number })) : closeOut(pr))}>
                {fits.finish}
              </Button>
            </Box>
          </Box>
          {asking && (
            <Box key={`close-out-ask-${pr.number}`} flexDirection="row" flexWrap="wrap" gap={1} paddingLeft={cells(badge.text) + 1}>
              <Text color="warning" wrap="wrap">{`Close out PR #${pr.number} anyway? ${risk}`}</Text>
              <Button key={`close-out-yes-${pr.number}`} variant="primary" onPress={() => void closeOut(pr)}>
                Close out anyway
              </Button>
              <Button key={`close-out-no-${pr.number}`} dimColor onPress={() => void disarm($, 'pr')}>
                Cancel
              </Button>
            </Box>
          )}
          {isOpen && (
            <Box key={`pr-detail-${pr.number}`} flexDirection="row" flexWrap="wrap" gap={1} paddingLeft={[...badge.text].length + 1} marginBottom={1}>
              <Text dimColor>{`⎇ ${fit(pr.branch, Math.max(10, Math.floor(width / 3)))}`}</Text>
              {pr.author && <Text dimColor>{`· @${pr.author}`}</Text>}
              {pr.updatedAt && <Text dimColor>{`· ${ago(pr.updatedAt, clock)}`}</Text>}
              {review && <Text color={review.color}>{`· ${review.text}`}</Text>}
              {pr.ci === 'fail' && (pr.failing ?? []).length > 0 && <Text color="error">{`· ${fit(pr.failing.join(', '), 30)}`}</Text>}
              {(pr.issues ?? []).length > 0 && <Text dimColor>{`· for ${pr.issues.map(number => `#${number}`).join(', ')}`}</Text>}
              {owner && <Text color={workerBadge(owner.status).color}>{`· ${workerOnLine(owner.status, ago(owner.startedAt, clock), owner.number)}`}</Text>}
              {mine && (
                <Text color="claude" bold>
                  · ◆ this branch
                </Text>
              )}
              {link(pageOf(now.repo, 'pull', pr))}
            </Box>
          )}
        </Box>
      )
    }

    // A priority as a short tag, the most pressing in the loudest color.
    const priorityColor = (priority: string): ThemeKey => {
      const rank = project?.priority?.options.findIndex(option => option.name === priority) ?? -1
      return rank === 0 ? 'error' : rank === 1 ? 'warning' : 'inactive'
    }

    // Stop tracking the issue this session is on: no row has the ▶ until Start or a branch names one again.
    const stopTracking = async () => {
      await update($, working, () => null)
      await save($)
    }

    // One issue on one line: a mark, its priority, number and title at the left, which opens it; at the right its agent,
    // what blocks it, its pull request with CI, chips, a short progress bar with the count, and its age. The mark is ▶
    // on the issue this session is on and ▲ on a bug.
    const issueRow = (issue: Issue) => {
      const isOpen = open === issue.number
      const step = progress(issue.checks)
      const bug = isBug(issue, marks)
      const chipList = roomy ? chipsOf(issue, marks).slice(0, 2) : []
      const age = ago(issue.updatedAt, clock)
      const count = `${step.done}/${step.total}`.padEnd(5)
      const linked = prsFor(issue, now.prs)[0]
      const pr = linked ? `⇄ #${linked.number} ${ciGlyph(linked.ci)}` : ''
      const tag = project && issue.priority ? `${fit(issue.priority, 3)} ` : ''
      // The open issue it waits on, if any: the first, and how many more.
      const blockers = issue.blockedBy ?? []
      const blocked = blockers.length > 0 ? `⛔ #${blockers[0]}${blockers.length > 1 ? ` +${blockers.length - 1}` : ''}` : ''
      // The background agent on it, if Start in background set one going.
      const worker = working$.find(one => one.number === issue.number)
      const badge = worker && workerBadge(worker.status)
      // The issue this session is on, unless a background agent is at work on it: then the row shows the agent instead.
      // Its ✕ at the row's end stops tracking it.
      const onIt = doing?.number === issue.number && !(worker && ACTIVE.includes(worker.status))
      // Each right-hand part with the cell of gap before it. A narrow pane drops the chips, then the bar, then the age.
      const fits = rowRoom(width, 2 + (onIt && bug ? 2 : 0) + tag.length + String(issue.number).length + 2, {
        chips: chipList.reduce((sum, chip) => sum + cells(chip.name) + 3, 0),
        bar: step.total > 0 ? 3 + 1 + 5 + 1 : 0,
        age: age ? 3 + 1 : 0,
        rest: (pr ? cells(pr) + 1 : 0) + (blocked ? cells(blocked) + 1 : 0) + (badge ? cells(badge.text) + 1 : 0) + (onIt ? 2 : 0),
      })
      const chips = fits.chips ? chipList : []
      return (
        <Box key={`row-${issue.number}`} flexDirection="row" justifyContent="space-between">
          {!isOpen && peek(issue)}
          {/* The marks, priority and number keep their width; were the row ever short of room, the title gives way. */}
          <Box flexDirection="row" flexShrink={1}>
            <Box flexDirection="row" flexShrink={0}>
              {onIt ? (
                <Text color="claude" bold>
                  {'▶ '}
                </Text>
              ) : (
                <Text color="error">{bug ? '▲ ' : '  '}</Text>
              )}
              {onIt && bug && <Text color="error">▲ </Text>}
              {tag && <Text color={priorityColor(issue.priority ?? '')}>{tag}</Text>}
              <Text color={isOpen || onIt ? 'claude' : undefined} dimColor={!isOpen && !onIt} hover={{ dimColor: false, color: 'claude' }}>
                {`#${issue.number} `}
              </Text>
            </Box>
            <Button key={`issue-${issue.number}`} plain hover={{ bold: true }} onPress={toggle(issue.number)}>
              {fit(issue.title, fits.title)}
            </Button>
          </Box>
          <Box flexDirection="row" gap={1} flexShrink={0}>
            {badge && <Text color={badge.color}>{badge.text}</Text>}
            {blocked && <Text color="warning">{blocked}</Text>}
            {linked && <Text color={ciBadge[linked.ci].color}>{pr}</Text>}
            {chips.map(chip => (
              <Text>
                <Text color={hex(chip)}>●</Text>
                <Text dimColor>{` ${chip.name}`}</Text>
              </Text>
            ))}
            {fits.bar && (
              <Text key={`progress-${issue.number}`}>
                {meter(step.done, step.total, 3)}
                <Text color={tone(step)}>{` ${count}`}</Text>
              </Text>
            )}
            {fits.age && <Text dimColor>{age.padStart(3)}</Text>}
            {onIt && (
              <Button key={`stop-${issue.number}`} dimColor onPress={() => void stopTracking()}>
                ✕
              </Button>
            )}
          </Box>
        </Box>
      )
    }

    // The Inbox shows each issue with what Claude suggests for it: a row of Priority buttons and one of areas, the picked
    // one highlighted, Claude's reason, and Accept, which moves it on to the Status Claude suggests, or the other.
    const triaging = shownTab === 'inbox' && project !== null
    const areaNames = [...new Set([...triaged.areas, ...labelsOf(now.issues).filter(name => name.startsWith('area:')).map(name => name.slice('area:'.length))])].sort()
    const triageRow = (issue: Issue) => {
      const said = triaged.suggestions.find(one => one.number === issue.number)
      const mine = triaged.picks.find(one => one.number === issue.number)
      const had = areaOf(issue)
      const priority = mine?.priority ?? said?.priority ?? issue.priority ?? null
      const area = mine && 'area' in mine ? (mine.area ?? null) : said ? said.area : had === 'other' ? null : had
      const status = said?.status ?? statusFor(project, priority)
      const other = status === 'Ready' ? 'Backlog' : 'Ready'
      const target = triageTarget(project, status)
      const otherTarget = triageTarget(project, other)
      const choosing = (edit: { priority?: string; area?: string | null }) => () =>
        void update($, triage, was => ({ ...was, picks: [...was.picks.filter(one => one.number !== issue.number), { ...was.picks.find(one => one.number === issue.number), number: issue.number, ...edit }] }))
      const age = ago(issue.updatedAt, clock)
      return (
        <Box key={`triage-${issue.number}`} flexDirection="column" marginTop={1}>
          <Box flexDirection="row" justifyContent="space-between">
            <Box flexDirection="row" gap={1}>
              <Text color="claude">{`#${issue.number}`}</Text>
              <Button key={`issue-${issue.number}`} plain hover={{ bold: true }} onPress={toggle(issue.number)}>
                {fit(issue.title, Math.max(12, width - String(issue.number).length - age.length - 4))}
              </Button>
            </Box>
            <Text dimColor>{age}</Text>
          </Box>
          <Box flexDirection="row" gap={1} flexWrap="wrap" paddingLeft={2}>
            {(project?.priority?.options ?? []).map(one => choice(`triage-${issue.number}-priority-${one.name}`, one.name, one.name === priority, choosing({ priority: one.name })))}
            <Text dimColor>·</Text>
            {areaNames.map(name => choice(`triage-${issue.number}-area-${name}`, name, name === area, choosing({ area: name })))}
            {choice(`triage-${issue.number}-area-none`, 'no area', area === null, choosing({ area: null }))}
            <Text dimColor>·</Text>
            <Button key={`triage-${issue.number}-accept`} variant="primary" onPress={() => void acceptTriage($, issue, { priority, area }, status)}>
              {target ? `✓ Accept → ${target}` : '✓ Accept'}
            </Button>
            {otherTarget && (
              <Button key={`triage-${issue.number}-${other.toLowerCase()}`} dimColor onPress={() => void acceptTriage($, issue, { priority, area }, other)}>
                {`→ ${otherTarget}`}
              </Button>
            )}
          </Box>
          <Box paddingLeft={2}>
            <Text dimColor wrap="wrap">
              {said ? `✦ ${said.reason || 'No reason given.'}` : triaged.asking ? '◌ waiting on Claude' : '✦ No suggestion yet: pick, then accept.'}
            </Text>
          </Box>
        </Box>
      )
    }

    // What hovering a row shows above it: the title, how far along, and the boxes still open.
    // Every line is padded to the card's width, its margins spaces rather than paddingX, so it covers the rows it is
    // painted over: the surface paints a floating box's text and border but leaves its padding showing what is beneath.
    // It sits at the pane's right, leaving the rows above their mark, number and the start of their title, so the
    // pointer moving up the list reaches the row above rather than the card. A pane without that room shows none.
    // A card above a row too near the pane's top would be pushed down over the row, so each row knows the lines free
    // above it in the window. They are at least these: each line of the board above the list, each heading and row one
    // line, an open card none. Counting short leaves a card smaller than its room, never bigger.
    const PEEK_CLEAR = 28
    const groups = triaging ? [] : groupsOf(shown, grouping, project, viewField, marks)
    const listed$ = triaging
      ? shown.map(issue => issue.number)
      : groups.flatMap(group => [null, ...(group.folded && !opened.includes(group.key) ? [] : group.issues.map(issue => issue.number))])
    // The Issues heading wraps its buttons, each its label and four cells of brackets; the search field, of no known
    // width, isn't counted.
    const heading$ = wrappedLines(
      [
        cells('Issues'),
        ...tabs.map(one => cells(tabLabel(one)) + 4),
        cells('by'),
        ...groupings.map(one => cells(one.label) + 4),
      ],
      width,
    )
    const above$ =
      1 +
      heading$ +
      (trends ? 1 : 0) +
      (failure ? 1 : 0) +
      (project?.update ? 1 : 0) +
      (now.prs.length > 0 ? 1 + (sectionOpen('prs') ? now.prs.length : 0) : 0) +
      ((now.milestones ?? []).length > 0 ? 1 + (sectionOpen('milestones') ? (now.milestones ?? []).length : 0) : 0) +
      (arming && now.prs.length > 0 ? 1 : 0) +
      watched.length +
      (unknownTerms.length > 0 ? 1 : 0) +
      (triaging ? 1 + (triaged.failed ? 1 : 0) : 0)
    const { offset } = e.props.scroll
    const roomOf = (number: number) => Math.max(0, above$ + listed$.indexOf(number) - offset)
    const peek = (issue: Issue) => {
      const step = progress(issue.checks)
      const cardWidth = Math.min(56, width - PEEK_CLEAR)
      if (cardWidth < 30) return null
      const inner = cardWidth - 4
      const todo = issue.checks.filter(check => !check.done)
      const place = peekPlace(roomOf(issue.number), todo.length)
      if (!place) return null
      const listed = todo.slice(0, place.listed)
      const lines: { text: string; color?: ThemeKey; dim?: boolean; bold?: boolean }[] = [
        { text: fit(issue.title, inner), bold: true },
        step.total === 0
          ? { text: 'No acceptance boxes.', dim: true }
          : { text: `${step.done}/${step.total} ticked · ${todo.length} to go`, color: tone(step) },
        ...listed.map(check => ({ text: fit(`☐ ${check.text}`, inner) })),
        ...(place.more ? [{ text: `+${todo.length - listed.length} more`, dim: true }] : []),
        ...(place.hint ? [{ text: '⏎ open · ▶ Start inside', dim: true }] : []),
      ]
      return (
        <Box
          position="absolute"
          top={-(lines.length + 2)}
          left={width - cardWidth}
          width={cardWidth}
          display="none"
          hover={{ display: 'flex' }}
          flexDirection="column"
          borderStyle="round"
          borderColor="claude"
        >
          {lines.map(line => (
            // Padded in cells, and cut rather than wrapped should a character still be measured wrong: a wrapped line
            // would leave the rows beneath showing through and make the card a line taller than its place above the row.
            <Text color={line.color} dimColor={line.dim} bold={line.bold} wrap="truncate-end">
              {` ${pad(fit(line.text, inner), inner)} `}
            </Text>
          ))}
        </Box>
      )
    }

    // A project field on a card: its options as buttons, the one set drawn as the primary. Buttons rather than a
    // Select, which the terminal opens by keyboard alone: a click on its options does nothing.
    const picker = (issue: Issue, field: 'status' | 'priority', label: string, options: { id: string; name: string }[], value: string | null | undefined) => (
      <Box key={`${field}-${issue.number}`} flexDirection="row" gap={1} flexWrap="wrap">
        <Text dimColor>{label}</Text>
        {options.map(option =>
          choice(`${field}-${issue.number}-${option.id}`, option.name, option.name === value, () => void (option.name === value ? undefined : pick($, issue, field, option.name))),
        )}
      </Box>
    )

    // Change opens the card's editor, and reads the repo's labels and milestones the first time.
    const openEditor = (number: number) => async () => {
      const opening = changing !== number
      await update($, editing, () => (opening ? number : null))
      await disarm($, 'close')
      if (opening && !offered) await loadPalette($)
    }

    // The card's editor: each row a change made on GitHub as soon as it's pressed or entered. Closing an epic whose
    // sub-issues are still open takes a second press.
    const editor = (issue: Issue) => {
      const n = issue.number
      const me = who ?? '@me'
      const mine = issue.assignees.includes(me)
      const open = (issue.subIssues?.total ?? 0) - (issue.subIssues?.completed ?? 0)
      const labels = [...new Set([...(offered?.labels ?? labelsOf(now.issues)), ...issue.labels.map(label => label.name)])].sort()
      const closeAs = (reason: 'completed' | 'not planned') => async () => {
        if (open > 0 && armedClose !== n) {
          await update($, armed, (): Armed => ({ kind: 'close', number: n }))
          return
        }
        await disarm($, 'close')
        await update($, editing, () => null)
        await change($, n, { close: reason })
      }
      const row = (label: string) => <Text dimColor>{label.padEnd(9)}</Text>
      return (
        <Box key={`editor-${n}`} flexDirection="column" marginTop={1}>
          {/* What it is. */}
          {Input && (
            <Box flexDirection="row" gap={1} flexWrap="wrap">
              {row('Title')}
              <Input
                key={`title-${n}`}
                label=""
                placeholder={fit(issue.title, 50)}
                value={fields.title ?? ''}
                submitLabel="rename"
                onInput={text => void update($, typing, was => ({ ...was, title: text }))}
                onSubmit={text => {
                  if (!text.trim() || text.trim() === issue.title) return
                  void update($, typing, was => ({ ...was, title: '' })).then(() => change($, n, { title: text.trim() }))
                }}
              />
            </Box>
          )}
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {row('Boxes')}
            {Input && (
              <Input
                key={`box-${n}`}
                label="+ "
                placeholder="add an acceptance box"
                value={fields.box ?? ''}
                submitLabel="add"
                onInput={text => void update($, typing, was => ({ ...was, box: text }))}
                onSubmit={text => {
                  if (!text.trim()) return
                  void update($, typing, was => ({ ...was, box: '' })).then(() => change($, n, { addBoxes: [text.trim()] }))
                }}
              />
            )}
            <Button key={`body-${n}`} dimColor onPress={() => void $.prompt.fill({ text: `Edit the body of #${n}: ` })}>
              ✎ Edit the body with Claude
            </Button>
          </Box>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {row('Labels')}
            {labels.map(name => {
              const has = issue.labels.some(label => label.name === name)
              return choice(`label-${n}-${name}`, name, has, () => void change($, n, has ? { removeLabels: [name] } : { addLabels: [name] }))
            })}
            {Input && (
              // A label the repo hasn't got yet is made, then put on the issue; Claude Code doesn't ask, as the person typed it.
              <Input
                key={`new-label-${n}`}
                label="+ "
                placeholder="new label"
                value={fields.label ?? ''}
                submitLabel="add"
                onInput={text => void update($, typing, was => ({ ...was, label: text }))}
                onSubmit={text => {
                  if (!text.trim()) return
                  void update($, typing, was => ({ ...was, label: '' })).then(() => change($, n, { addLabels: [text.trim()] }))
                }}
              />
            )}
          </Box>
          {more && ((now.issueTypes ?? []).length > 0 && (
            <Box key={`type-row-${n}`} flexDirection="row" gap={1} flexWrap="wrap">
              {row('Type')}
              {(now.issueTypes ?? []).map(name => choice(`type-${n}-${name}`, name, name === issue.type, () => void change($, n, { type: name === issue.type ? null : name })))}
            </Box>
          ))}
          {/* Where it sits. */}
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {row('Epic')}
            <Text>{issue.parent ? `#${issue.parent.number} ${fit(issue.parent.title, 30)}` : 'none'}</Text>
            {issue.parent && (
              <Button key={`unparent-${n}`} dimColor onPress={() => void change($, n, { parent: null })}>
                Take out
              </Button>
            )}
            {Input && (
              <Input
                key={`parent-${n}`}
                label="put under #"
                placeholder="epic number"
                value={fields.parent ?? ''}
                submitLabel="set"
                onInput={text => void update($, typing, was => ({ ...was, parent: text }))}
                onSubmit={text => {
                  const parent = issueNumberIn(text)
                  if (parent === null) return
                  void update($, typing, was => ({ ...was, parent: '' })).then(() => change($, n, { parent }))
                }}
              />
            )}
          </Box>
          {more && (
            <Box flexDirection="row" gap={1} flexWrap="wrap">
              {row('Milestone')}
              {!offered && <Text dimColor>reading…</Text>}
              {offered && offered.milestones.length === 0 && <Text dimColor>none in this repo</Text>}
              {(offered?.milestones ?? []).map(title => {
                const has = issue.milestone === title
                return choice(`milestone-${n}-${title}`, title, has, () => void change($, n, { milestone: has ? null : title }))
              })}
            </Box>
          )}
          {more && (otherFields.map(field => {
            const now$ = fieldValues[n]?.[field.name]
            const key = `${n}-${field.id}`
            return (
              <Box key={`field-row-${key}`} flexDirection="row" gap={1} flexWrap="wrap">
                {row(fit(field.name, 9))}
                {field.kind === 'select' || field.kind === 'iteration'
                  ? (field.options ?? []).map(option =>
                      choice(`field-${key}-${option.id}`, option.name, option.name === now$, () => void change($, n, { fields: { [field.name]: option.name === now$ ? null : option.name } })),
                    )
                  : Input && (
                      <Input
                        key={`field-${key}`}
                        label=""
                        placeholder={now$ ?? (field.kind === 'date' ? 'YYYY-MM-DD' : field.kind === 'number' ? 'a number' : 'text')}
                        value={fields[key] ?? ''}
                        submitLabel="set"
                        onInput={text => void update($, typing, was => ({ ...was, [key]: text }))}
                        onSubmit={text => {
                          if (!text.trim()) return
                          void update($, typing, was => ({ ...was, [key]: '' })).then(() => change($, n, { fields: { [field.name]: text.trim() } }))
                        }}
                      />
                    )}
                {now$ !== undefined && (
                  <Button key={`field-clear-${key}`} dimColor onPress={() => void change($, n, { fields: { [field.name]: null } })}>
                    clear
                  </Button>
                )}
              </Box>
            )
          }))}
          {/* Who has it. */}
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {row('Assignee')}
            {issue.assignees.filter(login => login !== me).map(login => (
              <Text color="suggestion">{`@${login}`}</Text>
            ))}
            <Button key={`assign-${n}`} dimColor={mine} onPress={() => void change($, n, mine ? { unassign: ['@me'] } : { assign: ['@me'] })}>
              {mine ? `Unassign me (@${me})` : 'Assign me'}
            </Button>
          </Box>
          {/* Ending it. */}
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            {row('Close')}
            <Button key={`close-completed-${n}`} dimColor onPress={() => void closeAs('completed')()}>
              as completed
            </Button>
            <Button key={`close-not-planned-${n}`} dimColor onPress={() => void closeAs('not planned')()}>
              as not planned
            </Button>
            {more && Input && (
              <Input
                key={`duplicate-${n}`}
                label="as duplicate of #"
                placeholder="issue number"
                value={fields.duplicate ?? ''}
                submitLabel="close"
                onInput={text => void update($, typing, was => ({ ...was, duplicate: text }))}
                onSubmit={text => {
                  const of = issueNumberIn(text)
                  if (of === null || of === n) return
                  void update($, typing, was => ({ ...was, duplicate: '' }))
                    .then(() => update($, editing, () => null))
                    .then(() => change($, n, { duplicateOf: of }))
                }}
              />
            )}
          </Box>
          {armedClose === n && (
            <Text color="warning" wrap="wrap">{`#${n} is an epic with ${open} open ${open === 1 ? 'sub-issue' : 'sub-issues'}. Closing it leaves them open under a closed epic. Press again to close it anyway.`}</Text>
          )}
          <Box key={`more-row-${n}`} flexDirection="row">
            <Button key={`more-${n}`} dimColor onPress={() => void update($, editorMore, was => !was)}>
              {more ? '▴ Less' : `▾ More: ${[(now.issueTypes ?? []).length > 0 ? 'type' : '', 'milestone', otherFields.length > 0 ? 'fields' : '', 'duplicate'].filter(Boolean).join(', ')}`}
            </Button>
          </Box>
        </Box>
      )
    }

    // The card's comments: the latest few, a field to reply in, and Ask Claude to answer, which hands Claude the last
    // comment with how to reply. A reply posted here reads the comments again.
    const conversation = (issue: Issue) => {
      const n = issue.number
      const mine = said?.number === n ? said : null
      const comments = mine?.comments
      const last = comments?.at(-1)
      const reply = (text: string) => {
        if (!text.trim()) return
        void update($, typing, was => ({ ...was, comment: '' }))
          .then(() => change($, n, { comment: text }))
          .then(() => loadComments($, n))
      }
      return (
        <Box key={`talk-${n}`} flexDirection="column" marginTop={1}>
          <Text bold>
            {comments === undefined || comments === null
              ? 'Comments'
              : mine && mine.total > comments.length
                ? `Comments · latest ${comments.length} of ${mine.total}`
                : `Comments · ${comments.length}`}
          </Text>
          {(comments === undefined || comments === null) && <Text dimColor>◌ reading…</Text>}
          {comments?.length === 0 && <Text dimColor>None yet.</Text>}
          {comments?.map((comment, index) => (
            <Box key={`comment-${n}-${index}`} flexDirection="column" marginTop={index > 0 ? 1 : 0}>
              <Text>
                <Text color="suggestion">{`@${comment.author}`}</Text>
                <Text dimColor>{agoText(comment.at, clock) ? ` · ${agoText(comment.at, clock)}` : ''}</Text>
              </Text>
              <Markdown text={comment.body.length > 800 ? `${comment.body.slice(0, 799)}…` : comment.body || '(empty)'} />
            </Box>
          ))}
          <Box flexDirection="row" gap={1} marginTop={1} flexWrap="wrap">
            {Input && (
              <Input
                key={`reply-${n}`}
                label="reply "
                placeholder="write a comment, Enter posts it"
                value={fields.comment ?? ''}
                submitLabel="post"
                onInput={text => void update($, typing, was => ({ ...was, comment: text }))}
                onSubmit={reply}
              />
            )}
            {last && (
              <Button key={`ask-${n}`} dimColor onPress={() => void submit($, 'other prompts', { text: answerPrompt(issue, last), asUser: true }).then(() => $.ui.toast(`Asked Claude to answer @${last.author} on #${n}`))}>
                Ask Claude to answer
              </Button>
            )}
          </Box>
        </Box>
      )
    }

    // An opened issue: a card with its labels, its text, its boxes and what to do with it.
    const issueCard = (issue: Issue, hotkeys: boolean) => {
      const step = progress(issue.checks)
      const prose = proseOf(issue.body ?? '')
      // The background agent Start in background set on it, with what it last said.
      const worker = working$.find(one => one.number === issue.number)
      const workerAge = worker ? agoText(worker.startedAt, clock) : ''
      // What Start starts: on an epic's card, its first ready sub-issue, which the button names; null when none is.
      const isEpic = (issue.subIssues?.total ?? 0) > 0
      const target = startTargetOf(now.issues, issue, project, marks)
      const goes = target ?? issue
      const startLabel = isEpic && target && target.number !== issue.number ? `▶ Start #${target.number}` : '▶ Start'
      const startIt = () => (target ? start(target) : Promise.resolve($.ui.toast(noReadyText(issue.number))))
      const backgroundIt = () => (target ? startInBackground($, target) : Promise.resolve($.ui.toast(noReadyText(issue.number))))
      // In background start mode the background start is the card's first and primary one: `s`, and `e` for its Edit
      // first. The main-chat start moves to `b`, one key away.
      const inBackground = settings.startMode === 'background'
      // Edit first puts the start message in the prompt box. Sending the foreground message starts the issue, by the
      // prompt.submit hook; the background one asks Claude to dispatch the worker, and the agent.spawn hook claims it and
      // follows it.
      const draftIt = async (background: boolean) => {
        if (!target) return $.ui.toast(noReadyText(issue.number))
        const filled = await $.prompt.fill({ text: background ? backgroundPrompt(target) : startPrompt(target, false, await copyGoes($, target)) })
        if (!filled.isFilled) return
        await update($, drafted, () => (background ? null : target.number))
      }
      // A background agent at work on what Start would start, whether Start in background set it going or Claude
      // dispatched it: the card shows it in place of every start button, so the issue isn't started a second time.
      const busy = working$.find(one => one.number === goes.number && ACTIVE.includes(one.status))
      const startButton = launches.some(one => one.number === goes.number && one.how === 'start') ? (
        <Text key={`starting-${issue.number}`} color="claude">
          ▶ Starting…
        </Text>
      ) : startedHere === goes.number ? (
        <Text key={`started-${issue.number}`} color="claude">
          ▶ Started
        </Text>
      ) : (
        <Button key={`start-${issue.number}`} variant={inBackground ? undefined : 'primary'} hotkey={hotkeys ? (inBackground ? 'b' : 's') : undefined} onPress={() => void startIt()}>
          {startLabel}
        </Button>
      )
      const backgroundButton =
        startedHere === goes.number ? null : launches.some(one => one.number === goes.number && one.how === 'background') ? (
          <Text key={`starting-background-${issue.number}`} color="claude">
            ⚙ Starting in background…
          </Text>
        ) : (
          <Button key={`background-${issue.number}`} variant={inBackground ? 'primary' : undefined} hotkey={hotkeys ? (inBackground ? 's' : 'b') : undefined} onPress={() => void backgroundIt()}>
            {isEpic && target && target.number !== issue.number ? `⚙ Start #${target.number} in background` : '⚙ Start in background'}
          </Button>
        )
      const draftButton = (
        <Button key={`draft-${issue.number}`} dimColor={inBackground} hotkey={hotkeys && !inBackground ? 'e' : undefined} onPress={() => void draftIt(false)}>
          ✎ Edit first
        </Button>
      )
      const draftBackgroundButton = (
        <Button key={`draft-background-${issue.number}`} dimColor={!inBackground} hotkey={hotkeys && inBackground ? 'e' : undefined} onPress={() => void draftIt(true)}>
          ✎ Edit first in background
        </Button>
      )
      return (
        <Box key={`card-${issue.number}`} flexDirection="column" borderStyle="round" borderColor="claude" paddingX={1} marginLeft={2} marginBottom={1}>
          <Text bold wrap="wrap">
            {issue.title}
          </Text>
          {!kept(issue) && (
            <Text color="warning" wrap="wrap">{`Not under ${filterName}${typed.trim() ? ` or the search` : ''} any more. It leaves the list when you collapse it.`}</Text>
          )}
          <Box flexDirection="row" gap={2} flexWrap="wrap">
            {issue.labels.map(label => (
              <Text>
                <Text color={hex(label)}>●</Text>
                <Text dimColor>{` ${label.name}`}</Text>
              </Text>
            ))}
            {issue.assignees.map(login => (
              <Text color="suggestion">{`@${login}`}</Text>
            ))}
            <Text dimColor>{`updated ${agoText(issue.updatedAt, clock)}`}</Text>
            {issue.parent && <Text dimColor>{`in #${issue.parent.number}`}</Text>}
            {(issue.subIssues?.total ?? 0) > 0 && <Text dimColor>{`epic · ${issue.subIssues?.completed}/${issue.subIssues?.total} sub-issues closed`}</Text>}
            {issue.milestone && <Text dimColor>{`⚑ ${issue.milestone}`}</Text>}
            {(issue.blockedBy ?? []).length > 0 && <Text color="warning">{`blocked by ${issue.blockedBy?.map(number => `#${number}`).join(', ')}`}</Text>}
          </Box>
          {project && (project.status || project.priority) && (
            <Box flexDirection="column" marginTop={1}>
              {project.status && picker(issue, 'status', 'Status  ', project.status.options, issue.status)}
              {project.priority && picker(issue, 'priority', 'Priority', project.priority.options, issue.priority)}
            </Box>
          )}
          {prose && (
            <Box marginTop={1}>
              <Markdown key={`body-${issue.number}`} text={prose} />
            </Box>
          )}
          {step.total > 0 ? (
            <Box flexDirection="column" marginTop={1}>
              <Text>
                {meter(step.done, step.total, Math.max(10, Math.min(30, width - 24)))}
                <Text bold>{` ${step.done}/${step.total}`}</Text>
                <Text dimColor>{` · ${Math.round((step.done / step.total) * 100)}%`}</Text>
              </Text>
              {issue.checks.map((check, index) => (
                <Box key={`box-row-${issue.number}-${index + 1}`} flexDirection="row">
                  <Box flexShrink={0}>
                    <Text color={check.done ? 'success' : 'warning'}>{check.done ? '✔ ' : '☐ '}</Text>
                  </Box>
                  <Box flexShrink={1}>
                    <Button
                      key={`box-${issue.number}-${index + 1}`}
                      plain
                      dimColor={check.done}
                      hover={{ bold: true }}
                      onPress={() => void flip(issue, index + 1, !check.done)}
                    >
                      {check.text}
                    </Button>
                  </Box>
                </Box>
              ))}
            </Box>
          ) : (
            <Box marginTop={1}>
              <Text dimColor italic>
                No acceptance boxes in this issue.
              </Text>
            </Box>
          )}
          {issue.type && (
            <Text>
              <Text dimColor>Type </Text>
              {issue.type}
            </Text>
          )}
          {(() => {
            const set = Object.entries(fieldValues[issue.number] ?? {}).filter(([name]) => otherFields.some(field => field.name === name))
            return set.length > 0 ? (
              <Text wrap="wrap">
                <Text dimColor>Fields </Text>
                {set.map(([name, value]) => `${name} ${value}`).join(' · ')}
              </Text>
            ) : null
          })()}
          {conversation(issue)}
          {worker && (
            <Box flexDirection="column" marginTop={1}>
              <Text>
                <Text color={workerBadge(worker.status).color}>{`${workerBadge(worker.status).text} `}</Text>
                <Text dimColor>{`a background agent, started ${workerAge}`}</Text>
              </Text>
              {worker.answer && (
                <Text dimColor wrap="wrap">
                  {worker.answer}
                </Text>
              )}
            </Box>
          )}
          <Box flexDirection="row" gap={1} marginTop={1} flexWrap="wrap">
            {busy ? (
              <Text key={`worker-on-${issue.number}`} color={workerBadge(busy.status).color}>
                {workerOnLine(busy.status, ago(busy.startedAt, clock), goes.number === issue.number ? undefined : goes.number)}
              </Text>
            ) : inBackground ? (
              [backgroundButton, startButton, draftBackgroundButton, draftButton]
            ) : (
              [startButton, backgroundButton, draftButton, draftBackgroundButton]
            )}
            {choice(`edit-${issue.number}`, '⚙ Change', changing === issue.number, openEditor(issue.number))}
            {link(pageOf(now.repo, 'issues', issue))}
            <Button key={`close-${issue.number}`} dimColor hotkey={hotkeys ? 'x' : undefined} onPress={toggle(issue.number)}>
              Collapse
            </Button>
          </Box>
          {changing === issue.number && editor(issue)}
        </Box>
      )
    }

    // Merge all's confirm, while there is still something to merge.
    const confirm = arming && now.prs.length > 0

    return (
      <Box flexDirection="column">
        {topLine}
        {project?.update && (
          // The project's latest status update, colored by how it stands.
          <Text wrap="truncate-end">
            <Text color={{ 'On track': 'success', 'At risk': 'warning', 'Off track': 'error', Complete: 'claude' }[project.update.status] as ThemeKey | undefined}>{'◉ '}</Text>
            {updateLine(project.update, clock)}
          </Text>
        )}
        {planCard}
        {statusesCard}
        {labelsCard}
        {setupPlan}
        {trends}
        {setupCard}
        {adoptCard}
        {failure && <Text color="error">{`✗ Last refresh failed: ${failure}`}</Text>}

        {now.prs.length > 0 && (
          <Box flexDirection="row" justifyContent="space-between">
            <Box flexDirection="row" gap={1}>
              {heading('prs', 'Pull requests')}
              <Text dimColor>
                {sectionOpen('prs')
                  ? `${now.prs.length} open`
                  : prCountsText(now.prs)}
              </Text>
            </Box>
            {!arming && (
              <Button key="close-out-all" dimColor hotkey="m" onPress={arm(true)}>
                {`⇶ Merge all ${now.prs.length}…`}
              </Button>
            )}
          </Box>
        )}
        {confirm && (
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            <Text color="warning">{`Finish and merge all ${now.prs.length} open ${now.prs.length === 1 ? 'PR' : 'PRs'}?`}</Text>
            <Button key="close-out-all-yes" variant="primary" hotkey="y" onPress={() => void closeOutAll(now.prs)}>
              Yes, merge them
            </Button>
            <Button key="close-out-all-no" dimColor hotkey="n" onPress={arm(false)}>
              Cancel
            </Button>
          </Box>
        )}
        {sectionOpen('prs') && now.prs.map(prRow)}
        {watched.map(run => (
          <Box key={`run-${run.id}`} flexDirection="row" gap={1}>
            <Text color={run.failed > 0 ? 'error' : 'warning'}>◷</Text>
            <Text>
              <Text bold>{fit(run.workflow, 28)}</Text>
              <Text dimColor>{` on ${fit(run.branch, 28)}`}</Text>
            </Text>
            {run.total > 0 && (
              <Text>
                {meter(run.done, run.total, 8)}
                <Text dimColor>{` ${run.done}/${run.total} jobs${run.failed > 0 ? `, ${run.failed} failed` : ''}`}</Text>
              </Text>
            )}
            {run.running && <Text dimColor>{fit(`${run.running}${run.step ? ` › ${run.step}` : ''}`, Math.max(12, width - 76))}</Text>}
          </Box>
        ))}

        {(now.milestones ?? []).length > 0 && (
          // The open milestones, release scope: how far along each is, and when it is due.
          <Box key="milestones" flexDirection="column">
            <Box flexDirection="row" gap={1}>
              {heading('milestones', 'Milestones')}
              <Text dimColor>
                {sectionOpen('milestones')
                  ? `${(now.milestones ?? []).length} open`
                  : fit((now.milestones ?? []).map(one => `${one.title} ${one.closed}/${one.open + one.closed}`).join(' · '), Math.max(12, width - 16))}
              </Text>
            </Box>
            {(sectionOpen('milestones') ? (now.milestones ?? []) : []).map(one => {
              const total = one.open + one.closed
              const due = milestoneDue(one, new Date(clock).toISOString().slice(0, 10))
              return (
                <Box key={`milestone-${one.number}`} flexDirection="row" justifyContent="space-between">
                  <Text>{fit(one.title, Math.max(12, width - 34))}</Text>
                  <Box flexDirection="row" gap={1}>
                    {meter(one.closed, total, 8)}
                    <Text dimColor>{`${one.closed}/${total}`}</Text>
                    <Text color={due.late ? 'error' : undefined} dimColor={!due.late}>
                      {due.text}
                    </Text>
                  </Box>
                </Box>
              )
            })}
          </Box>
        )}

        {issuesHeading}

        {unknownTerms.length > 0 && tab.view && project && (
          // A term of the view's filter the board can't apply is left out, so the tab may hold more than the view.
          <Box key="view-note" flexDirection="row" gap={1} flexWrap="wrap">
            <Text color="warning" wrap="wrap">{`The board can't apply ${unknownTerms.map(term => `\`${term}\``).join(', ')} from this view's filter, so it may list more than GitHub does.`}</Text>
            <Link href={viewUrl(project, tab.view)} label="↗ Open the view" />
          </Box>
        )}

        {shownTab === 'closed' && (
          // The issues closed lately, newest change first, each with how it closed: GitHub's, not the board's copy.
          <Box key="closed-list" flexDirection="column">
            {!closedNow && <Text dimColor>◌ Reading the issues closed lately…</Text>}
            {closedNow?.failed && <Text color="error" wrap="wrap">{`Couldn't read closed issues: ${closedNow.failed}`}</Text>}
            {closedNow && !closedNow.failed && closedNow.items.length === 0 && <Text dimColor>Nothing closed yet.</Text>}
            {(closedNow?.items ?? []).map(one => (
              <Box key={`closed-${one.number}`} flexDirection="row" justifyContent="space-between">
                <Text>
                  <Text color={one.reason === 'not_planned' ? 'inactive' : 'success'}>{one.reason === 'not_planned' ? '⊘ ' : '✓ '}</Text>
                  <Text dimColor>{`#${one.number} `}</Text>
                  {fit(one.title, Math.max(12, width - 30))}
                </Text>
                <Text dimColor>{standing(one, clock).replace(/^closed /, '')}</Text>
              </Box>
            ))}
          </Box>
        )}
        {shownTab !== 'closed' && shown.length === 0 && (
          <Box flexDirection="column" alignItems="center">
            <Text color="success">✓</Text>
            <Text dimColor>{typed.trim() ? `Nothing under ${filterName} matches “${typed.trim()}”.` : `Nothing open under ${filterName}.`}</Text>
          </Box>
        )}
        {triaging && (
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            <Text color={triaged.asking ? 'warning' : undefined} dimColor={!triaged.asking}>
              {triaged.asking ? '◌ Claude is suggesting a Priority, area and Status for each…' : '✦ Claude suggests a Priority, area and Status for each. Change any, then accept.'}
            </Text>
            {!triaged.asking && shown.length > 0 && (
              <Button key="triage-again" dimColor onPress={() => void suggestAgain($)}>
                Suggest again
              </Button>
            )}
          </Box>
        )}
        {triaging && triaged.failed && <Text color="error" wrap="wrap">{`Couldn't get suggestions: ${triaged.failed}`}</Text>}
        {triaging &&
          shown.map(issue => (
            <Box key={`triage-entry-${issue.number}`} flexDirection="column">
              {isInbox(issue, project) ? triageRow(issue) : issueRow(issue)}
              {open === issue.number && issueCard(issue, single)}
            </Box>
          ))}
        {groups.map(group => {
          const count = String(group.issues.length)
          const shut = group.folded && !opened.includes(group.key)
          // A folded group, such as Backlog, is a heading the person opens; open, its heading folds it again.
          const fold = () => void update($, unfolded, list => (list.includes(group.key) ? list.filter(one => one !== group.key) : [...list, group.key]))
          return (
            <Box key={`group-${group.key}`} flexDirection="column">
              {group.folded ? (
                <Box flexDirection="row" gap={1}>
                  <Button key={`fold-${group.key}`} plain hover={{ bold: true }} onPress={fold}>
                    {`${shut ? '▸' : '▾'} ${group.title}`}
                  </Button>
                  <Text dimColor>{shut ? `${count} folded` : count}</Text>
                </Box>
              ) : group.epic ? (
                // An epic: how many of its sub-issues are closed, as a bar, and Next, which starts the first ready one.
                (() => {
                  const epic = group.epic
                  const next = nextOf(now.issues, epic.number, project, marks)
                  const closed = `${epic.completed}/${epic.total} closed`
                  return (
                    <Box flexDirection="row" justifyContent="space-between" gap={1}>
                      <Text wrap="truncate-end">
                        <Text bold color="claude">
                          {fit(group.title, Math.max(12, width - 12 - cells(closed) - (next ? 10 : 0) - 5 - count.length))}
                        </Text>
                        <Text dimColor>{` ${count}`}</Text>
                      </Text>
                      <Box flexDirection="row" gap={1} flexShrink={0}>
                        {meter(epic.completed, epic.total, 10)}
                        <Text dimColor>{closed}</Text>
                        {next && (
                          <Button key={`next-${epic.number}`} dimColor hover={{ dimColor: false, color: 'claude' }} onPress={() => void start(next)}>
                            ▶ Next
                          </Button>
                        )}
                      </Box>
                    </Box>
                  )
                })()
              ) : (
                // One short label with its count, such as `In Progress 1`.
                <Box flexDirection="row" gap={1}>
                  <Text bold color="claude">
                    {fit(group.title, Math.max(12, width - count.length - 1))}
                  </Text>
                  <Text dimColor>{count}</Text>
                </Box>
              )}
              {!shut &&
                group.issues.map(issue => (
                  <Box flexDirection="column">
                    {issueRow(issue)}
                    {open === issue.number && issueCard(issue, single)}
                  </Box>
                ))}
            </Box>
          )
        })}

        <Box>
          <Text dimColor>
            {
              // The keys for what shows, most useful first, cut to the pane's width rather than wrapped.
              hintFit(
                confirm
                  ? ['y merge every open PR', 'n cancel']
                  : single
                      ? ['s start', 'e edit first', 'x or esc collapse', 'press a box to tick it', 'r refresh']
                      : [
                          '⏎ open an issue',
                          filterKeys(filtersFor(project)),
                          'r refresh',
                          ...(now.prs.length > 0 ? ['m merge all PRs'] : []),
                        ],
                width,
              )
            }
          </Text>
        </Box>
      </Box>
    )
  })

  // The board in a line, dim at the end of the hint under the prompt; nothing when nothing is open. While the check
  // finds something missing, it says so: always when the board can't read GitHub, otherwise until waved off in the band.
  // The engine puts its own ` · ` between the hint and the tail, so the tail doesn't start with one.
  // Not `$.ui.status`: the status line draws as a warning, and an open issue isn't one.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const now = await read($, board)
    const gone = await read($, dismissed)
    const loud = ((await read($, access))?.problems ?? []).filter(problem => problem.blocks || !gone.includes(accessKey(problem)))
    const note = loud.length > 0 ? `issue board ${loud.some(problem => problem.blocks) ? 'needs setup' : 'is limited'} (/issues check)` : undefined
    const text = [now && summary(now.issues, now.prs, await markersNow($, now), await footerBranch($)), note].filter(Boolean).join(' · ')
    if (!text) return next(e)

    return next({ ...e, props: { ...e.props, tail: e.props.tail ? `${e.props.tail} · ${text}` : text } })
  })

  // The band above the prompt is for what needs the person now (something to fix, merge, tick or look at). It shows
  // nothing otherwise. The main session's progress (the issue Claude is on, CI running) is the pane's, and Claude Code
  // lists running background agents itself, so the band repeats neither. Every line is one row at any width.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // Turned off, the band draws nothing of the board's; the pane still shows what needs the person.
    if (e.props.hasSurvey || !settings.band) return next(e)
    const now = await read($, board)
    const gone = await read($, dismissed)
    const problems = ((await read($, access))?.problems ?? []).filter(problem => !gone.includes(accessKey(problem)))
    const doing = await read($, working)
    const alerts = now ? alertsOf(now, doing, gone, await read($, greened)) : []
    // Tasks Claude completed whose boxes are still open: the band asks whether to tick them.
    const offers = (now ? await read($, tasks) : []).flatMap(task => {
      const issue = task.done ? now?.issues.find(one => one.number === task.number) : undefined
      const at = issue && boxOf(issue, task)
      return at && !at.done ? [{ task, box: at.box }] : []
    })
    // What the board noticed about epics: why one moved to Verification, or a sub-issue open again under one. A line
    // past its age limit goes here too, since a quiet board may not read again for a while.
    const notes = now ? liveEpicNotes(await read($, epicNotes), now, await nowOf($)) : []
    // The project the board reads but may not write to yet: the band points at the pane, which has the whole warning.
    const unadopted = now?.project && adoptAsk(now.project, await read($, adoption)) ? now.project : null
    // Which Status is which, when the board found it by common names and the person hasn't answered: once per guess.
    const guess = guessOf(now?.project)
    const guessed = now?.project && guess.length > 0 && !(await read($, guessSeen)).includes(guessKey(now.project, guess)) ? now.project : null
    // A plan Claude proposed that waits on the person: the band points at the pane, where its card is.
    // Only the rows the board doesn't show as made already count.
    const waiting = await read($, proposal)
    const waitingRows = waiting && now ? rowsToMake(waiting.rows, now) : (waiting?.rows ?? [])
    const planned = waiting && waitingRows.length > 0 && !waiting.applying ? { ...waiting, rows: waitingRows } : null
    // Which labels Bugs and Later go by, when the board found them by the repo's names and the person hasn't answered.
    const markerAsk = markerAskOf(now, await read($, chosenMarkers))
    const marked = Object.keys(markerAsk).length > 0 && !(await read($, guessSeen)).includes(markerKey(markerAsk))
    // Issues captured to the Inbox since the person last opened it.
    const caught = await read($, captured)
    if (problems.length === 0 && alerts.length === 0 && offers.length === 0 && notes.length === 0 && !unadopted && !guessed && !marked && !planned && caught === 0)
      return next(e)

    const elements = $.ui.resolve(e)
    const { Box, Text, Button } = elements
    // Each line keeps its badge, number and buttons whole, as the pane's rows do; its text is cut to what is left.
    const { link, keep } = partsOf(elements)
    const width = e.props.bodyColumns
    const clock = Date.now()
    const repo = now?.repo ?? ''
    const dismiss = (alert: Alert) => async () => {
      await update($, dismissed, list => [...list.slice(-50), alert.key])
      if (alert.kind === 'closed') await update($, working, () => null)
      await save($)
    }
    // A button that hands Claude a pull request: into the prompt box while Claude is busy, sent otherwise.
    const hand = (text: string) => (e.props.isWorking ? $.prompt.fill({ text }) : submit($, 'other prompts', { text, asUser: true }))

    // One line of the band: `<badge> #<number> <text> <buttons> ✕`. The badge, number, buttons and ✕ keep their width;
    // the text is cut to what is left.
    const bandRow = (row: {
      key?: string
      badge: string
      color: ThemeKey
      number?: { value: number; color: ThemeKey }
      text: RenderChildren
      actions?: RenderChildren[]
      dismiss?: { key: string; onPress: () => void }
    }) => (
      <Box key={row.key} flexDirection="row" gap={1}>
        {keep(
          <Text color={row.color} inverse bold>
            {` ${row.badge} `}
          </Text>,
        )}
        {row.number && keep(<Text color={row.number.color} bold>{`#${row.number.value}`}</Text>)}
        <Text wrap="truncate-end">{row.text}</Text>
        {(row.actions ?? []).map(part => part && keep(part))}
        {row.dismiss &&
          keep(
            <Button key={row.dismiss.key} dimColor onPress={row.dismiss.onPress}>
              ✕
            </Button>,
          )}
      </Box>
    )

    const line = (alert: Alert) => {
      const gone = { key: `dismiss-${alert.key}`, onPress: () => void dismiss(alert)() }
      switch (alert.kind) {
        case 'ci': {
          const { pr } = alert
          const names = pr.failing ?? []
          return bandRow({
            badge: '✗ CI',
            color: 'error',
            number: { value: pr.number, color: 'suggestion' },
            text: [
              <Text>{fit(pr.title, Math.max(12, width - 44))}</Text>,
              <Text dimColor>{` ${names.length > 0 ? fit(names.join(', '), 24) : 'failing'} on ${fit(pr.branch, 20)}`}</Text>,
            ],
            actions: [
              <Button key={`fix-${pr.number}`} variant="primary" onPress={() => void hand(fixPrompt(pr))}>
                Fix
              </Button>,
              link(pageOf(repo, 'pull', pr)),
            ],
            dismiss: gone,
          })
        }
        case 'pass': {
          const { pr } = alert
          return bandRow({
            badge: '✓ CI',
            color: 'success',
            number: { value: pr.number, color: 'suggestion' },
            text: [<Text>{fit(pr.title, Math.max(12, width - 57))}</Text>, <Text dimColor>{` passed on ${fit(pr.branch, 20)}`}</Text>],
            actions: [
              <Button key={`merge-${pr.number}`} variant="primary" onPress={() => void hand(closeOutPrompt(pr))}>
                Finish & merge
              </Button>,
              link(pageOf(repo, 'pull', pr)),
            ],
            dismiss: gone,
          })
        }
        case 'activity': {
          const { issue } = alert
          return bandRow({
            badge: '● NEW',
            color: 'warning',
            number: { value: issue.number, color: 'claude' },
            text: [<Text>{fit(issue.title, Math.max(12, width - 44))}</Text>, <Text dimColor>{` changed ${agoText(issue.updatedAt, clock)}`}</Text>],
            actions: [link(pageOf(repo, 'issues', issue))],
            dismiss: gone,
          })
        }
        case 'closed':
          return bandRow({
            badge: '✓ DONE',
            color: 'success',
            number: { value: alert.working.number, color: 'claude' },
            text: [<Text>{fit(alert.working.title, Math.max(12, width - 30))}</Text>, <Text dimColor> is closed</Text>],
            dismiss: gone,
          })
      }
    }

    const offerLine = ({ task, box }: { task: BoxTask; box: number }) =>
      bandRow({
        key: `offer-${task.id}`,
        badge: '☑ TICK?',
        color: 'success',
        number: { value: task.number, color: 'claude' },
        text: [<Text dimColor>{`box ${box} `}</Text>, <Text>{fit(task.text, Math.max(12, width - 52))}</Text>, <Text dimColor> is done</Text>],
        actions: [
          <Button key={`tick-task-${task.id}`} variant="primary" onPress={() => void tickTask($, task)}>
            {`Tick box ${box}`}
          </Button>,
        ],
        dismiss: { key: `skip-task-${task.id}`, onPress: () => void update($, tasks, list => list.filter(one => one.id !== task.id)) },
      })

    // An epic the board moved on, or that has a sub-issue open again: `◆ EPIC #35 <title> · <what happened>`.
    const epicLine = (note: EpicNote) => {
      const tail = ` · ${note.text}`
      return bandRow({
        key: `epic-row-${note.key}`,
        badge: '◆ EPIC',
        color: 'warning',
        number: { value: note.epic, color: 'claude' },
        text: [<Text>{fit(note.title, Math.max(12, width - cells(tail) - 30))}</Text>, <Text dimColor>{tail}</Text>],
        actions: [link(pageOf(repo, 'issues', { number: note.epic, url: '' }))],
        dismiss: { key: `dismiss-${note.key}`, onPress: () => void update($, epicNotes, list => list.filter(one => one.key !== note.key)) },
      })
    }

    // Something missing: what it is, the command or page that fixes it, and a look again once it's done.
    const problemLine = (problem: Problem) => {
      const how = problem.command ? `run ${problem.command}` : problem.fix
      return bandRow({
        key: `problem-row-${problem.id}`,
        badge: '⚠ SETUP',
        color: problem.blocks ? 'error' : 'warning',
        text: [<Text>{fit(problem.title, Math.max(16, width - 64))}</Text>, <Text dimColor>{` · ${fit(how, 32)}`}</Text>],
        actions: [
          problem.command && (
            <Button key={`copy-fix-${problem.id}`} variant="primary" onPress={press => void copyFix($, problem, press.surface)}>
              Copy command
            </Button>
          ),
          problem.url && !problem.command && link(problem.url, '↗ Open page'),
          <Button key={`recheck-${problem.id}`} dimColor onPress={() => void recheck($)}>
            Check again
          </Button>,
        ],
        dismiss: { key: `dismiss-${accessKey(problem)}`, onPress: () => void dismissProblem($, problem) },
      })
    }

    // `⚠ PROJECT Let the board write to <title>, owned by <owner>? · it only reads it until you say yes`. Review opens the
    // pane, where the warning says what it would write; ✕ keeps it read-only.
    const adoptLine = (project: Project) => {
      const tail = ' · it only reads it until you say yes'
      return bandRow({
        key: 'adopt-row',
        badge: '⚠ PROJECT',
        color: 'warning',
        text: [<Text>{fit(adoptText(project, settings.refresh).title, Math.max(16, width - cells(tail) - 26))}</Text>, <Text dimColor>{tail}</Text>],
        actions: [
          <Button key="adopt-review" variant="primary" onPress={() => void $.ui.open(OPEN)}>
            Review
          </Button>,
        ],
        dismiss: { key: 'adopt-dismiss', onPress: () => void declineFromPrompt($, project) },
      })
    }

    // `✦ PLAN Claude's plan: 5 changes to 3 issues · Status 3 · Priority 2`. Review opens the pane at the plan's card.
    const planLine = (one: Plan) => {
      const changes = one.rows.map(row => row.change)
      const head = `Claude's plan: ${sizeText(changes)}`
      const tail = ` · ${kindsText(changes)}`
      return bandRow({
        key: 'plan-row',
        badge: '✦ PLAN',
        color: 'suggestion',
        text: [<Text>{fit(head, Math.max(16, width - 22))}</Text>, <Text dimColor>{fit(tail, Math.max(0, width - 22 - cells(head)))}</Text>],
        actions: [
          <Button key="plan-review" variant="primary" onPress={() => void $.ui.open(OPEN)}>
            Review
          </Button>,
        ],
      })
    }

    // A guess the board asks the person to look at: Looks right saves it; Change opens the card that picks it; ✕ leaves
    // it a guess, unasked. `id` names its row and buttons, `seen` the guess.
    const askLine = (id: 'guess' | 'labels', badge: string, text: string, seen: string, confirm: () => Promise<unknown>, change: () => Promise<unknown>) =>
      bandRow({
        key: `${id}-row`,
        badge,
        color: 'suggestion',
        text: fit(text, Math.max(16, width - 44)),
        actions: [
          <Button key={`${id}-yes`} variant="primary" onPress={() => void confirm()}>
            Looks right
          </Button>,
          <Button key={`${id}-change`} dimColor onPress={() => void seeGuess($, seen).then(change)}>
            Change
          </Button>,
        ],
        dismiss: { key: `${id}-dismiss`, onPress: () => void seeGuess($, seen) },
      })
    // `? STATUS Status: Todo is Ready, Doing is In progress, Shipped is Done`, changed in /issues statuses.
    const guessLine = (project: Project) =>
      askLine('guess', '? STATUS', guessText(guess), guessKey(project, guess), () => confirmGuess($, project), () => openStatuses($))
    // `? LABELS Bugs: the Bug issue type · Later: the label someday`, changed in /issues labels.
    const markerLine = () =>
      askLine('labels', '? LABELS', markerText(markerAsk), markerKey(markerAsk), () => confirmMarkers($, markerAsk), () => openMarkers($))

    // `✚ INBOX 3 captured to the Inbox`. Open Inbox opens the pane at the Inbox tab, which ends the count; ✕ ends it too.
    const capturedLine = () => {
      const project = now?.project ?? null
      const tab = inboxTabOf(filtersFor(project), project)
      return bandRow({
        key: 'captured-row',
        badge: '✚ INBOX',
        color: 'suggestion',
        text: fit(`${caught} captured to the Inbox`, Math.max(16, width - 32)),
        actions: [
          <Button key="captured-open" variant="primary" onPress={() => void openInbox($)}>
            {tab ? 'Open Inbox' : 'Open issues'}
          </Button>,
        ],
        dismiss: { key: 'captured-dismiss', onPress: () => void update($, captured, () => 0) },
      })
    }

    return (
      <Box flexDirection="column">
        {problems.slice(0, 2).map(problemLine)}
        {unadopted && adoptLine(unadopted)}
        {planned && planLine(planned)}
        {guessed && guessLine(guessed)}
        {marked && markerLine()}
        {alerts.slice(0, 3).map(line)}
        {offers.slice(0, 3).map(offerLine)}
        {caught > 0 && capturedLine()}
        {/* Epic lines come last: they report what happened, and the lines above ask for something now. */}
        {notes.slice(-2).map(epicLine)}
      </Box>
    )
  })
}

files.hooks/parse.ts:
import type { ModelTextBlock, ThemeKey } from 'claude-code'
import type { Alert, Board, BoxTask, BuiltInFilter, Check, Ci, Comment, EpicNote, Filter, Found, GroupBy, Issue, Known, Label, Markers, Milestone, ProjectField, ProjectView, StatusUpdate, Project, PullRequest, Role, RunWatch, Suggestion, Worker, Working } from '../types'
import { DEFAULT_MARKERS, isBug, isBugLabel, isFuture, same } from './markers'
import { TOOLS, WORKER } from './tools'
import { ROLE_NAMES, NOW_COUNT, isLater, isNow, isRole, nowNames, priorityRank, roleOf } from './project'
import { offText } from './settings'
import type { StartMode } from './settings'

type RawLabel = { name: string; color?: string }
type RawUser = { login: string }
type RawIssue = {
  number: number
  title: string
  url?: string
  labels: RawLabel[]
  assignees?: RawUser[] | null
  body: string | null
  updatedAt: string
}
type RawCheck = { status?: string; conclusion?: string; state?: string; name?: string; context?: string; detailsUrl?: string; targetUrl?: string }
type RawPr = {
  number: number
  title: string
  url?: string
  author?: RawUser | null
  headRefName: string
  headRefOid?: string
  isDraft: boolean
  statusCheckRollup: RawCheck[] | null
  reviewDecision: string | null
  additions?: number
  deletions?: number
  updatedAt?: string
  body?: string | null
  closingIssuesReferences?: { number: number }[] | null
  mergeStateStatus?: string | null
  reviewRequests?: ({ login?: string; name?: string; slug?: string } | null)[] | null
}

const BOX = /^\s*[-*]\s+\[([ xX])\]\s+(.*)$/
const FAILED = new Set(['FAILURE', 'TIMED_OUT', 'CANCELLED', 'ACTION_REQUIRED', 'STARTUP_FAILURE', 'ERROR'])

// The task-list boxes of an issue's body, in order.
export const checksOf = (body: string | null): Check[] =>
  (body ?? '').split(/\r?\n/).flatMap(line => {
    const match = BOX.exec(line)
    return match ? [{ done: match[1] !== ' ', text: (match[2] ?? '').trim() }] : []
  })

export const parseIssues = (json: string): Issue[] =>
  (JSON.parse(json) as RawIssue[]).map(raw => ({
    number: raw.number,
    title: raw.title,
    url: raw.url ?? '',
    labels: raw.labels.map(label => ({ name: label.name, color: label.color ?? '' })),
    assignees: (raw.assignees ?? []).map(user => user.login),
    checks: checksOf(raw.body),
    updatedAt: raw.updatedAt,
    body: raw.body ?? '',
  }))

const HEADING = /^\s{0,3}#{1,6}\s/
const MARKDOWN_LIMIT = 10_000

// The body as the card shows it: without its task-list boxes, which the card lists as buttons of their own, and
// without a heading left with nothing under it, such as `## Acceptance` once its boxes are gone.
export const proseOf = (body: string): string => {
  const lines = body.split(/\r?\n/).filter(line => !BOX.test(line))
  const kept = lines.filter((line, index) => {
    if (!HEADING.test(line)) return true
    const rest = lines.slice(index + 1)
    const end = rest.findIndex(next => HEADING.test(next))
    return (end < 0 ? rest : rest.slice(0, end)).some(next => next.trim() !== '')
  })
  const text = kept.join('\n').replace(/\n{3,}/g, '\n\n').trim()
  return text.length <= MARKDOWN_LIMIT ? text : `${text.slice(0, MARKDOWN_LIMIT - 1)}…`
}

export const ciOf = (rollup: RawCheck[] | null): Ci => {
  const checks = rollup ?? []
  if (checks.length === 0) return 'none'
  if (checks.some(isFailed)) return 'fail'
  if (checks.some(check => (check.status !== undefined && check.status !== 'COMPLETED') || check.state === 'PENDING' || check.state === 'EXPECTED')) {
    return 'pending'
  }
  return 'pass'
}

const isFailed = (check: RawCheck): boolean => FAILED.has(check.conclusion ?? check.state ?? '')

// The Actions run a check belongs to, read from its link (`.../actions/runs/<id>/job/<id>`).
const RUN = /\/actions\/runs\/(\d+)/

export const failingOf = (rollup: RawCheck[] | null): { failing: string[]; runs: number[] } => {
  const failed = (rollup ?? []).filter(isFailed)
  const runs = failed.flatMap(check => {
    const match = RUN.exec(check.detailsUrl ?? check.targetUrl ?? '')
    return match ? [Number(match[1])] : []
  })
  return { failing: [...new Set(failed.map(check => check.name ?? check.context ?? '').filter(Boolean))], runs: [...new Set(runs)] }
}

export const parsePrs = (json: string): PullRequest[] =>
  (JSON.parse(json) as RawPr[]).map(raw => ({
    number: raw.number,
    title: raw.title,
    url: raw.url ?? '',
    author: raw.author?.login ?? '',
    branch: raw.headRefName,
    isDraft: raw.isDraft,
    ci: ciOf(raw.statusCheckRollup),
    review: raw.reviewDecision ?? '',
    additions: raw.additions ?? 0,
    deletions: raw.deletions ?? 0,
    updatedAt: raw.updatedAt ?? '',
    sha: raw.headRefOid ?? '',
    ...failingOf(raw.statusCheckRollup),
    issues: issuesOf(raw.closingIssuesReferences ?? [], raw.body ?? ''),
    mergeState: raw.mergeStateStatus ?? '',
    reviewers: (raw.reviewRequests ?? []).flatMap(one => (one ? [one.login ? `@${one.login}` : (one.name ?? one.slug ?? '')] : [])).filter(Boolean),
    openThreads: 0,
  }))

// The open pull requests' review threads, to count the ones still open; gh pr list can't give them.
export const THREADS_QUERY =
  'query($owner: String!, $name: String!) { repository(owner: $owner, name: $name) { pullRequests(states: OPEN, first: 50) { nodes { number reviewThreads(first: 100) { nodes { isResolved } } } } } }'

// How many review threads are open on each pull request, by number; none known from an answer that isn't the query's.
export const threadsOf = (json: string): Map<number, number> => {
  type Raw = { data?: { repository?: { pullRequests?: { nodes?: ({ number: number; reviewThreads?: { nodes?: ({ isResolved: boolean } | null)[] } } | null)[] } } } }
  try {
    const nodes = (JSON.parse(json) as Raw | null)?.data?.repository?.pullRequests?.nodes ?? []
    return new Map(nodes.flatMap(pr => (pr ? [[pr.number, (pr.reviewThreads?.nodes ?? []).filter(thread => thread && !thread.isResolved).length] as const] : [])))
  } catch {
    return new Map()
  }
}

// What a GraphQL answer holds. GitHub answers some failures with an `errors` list beside the data rather than with a
// failed call, so the first error is thrown here, on every path, instead of being read as an empty answer.
export const graphqlData = (out: string): Record<string, any> => {
  const answer = JSON.parse(out) as { data?: Record<string, any> | null; errors?: { message?: string }[] } | null
  if (answer?.errors?.length) throw new Error(answer.errors[0]?.message || 'GitHub answered with an error')
  return answer?.data ?? {}
}

// The gh call that posts a comment on an issue, over REST, which spends nothing of the GraphQL limit. The body goes on
// stdin as JSON, so any text arrives as written.
export const commentCommand = (repo: string, number: number, body: string): { argv: string[]; stdin: string } => ({
  argv: ['api', '-X', 'POST', `repos/${repo}/issues/${number}/comments`, '--input', '-'],
  stdin: JSON.stringify({ body }),
})

// Why a box an issue hasn't got can't be ticked or reworded: how many it has, and the numbers asked for that it lacks.
export const noBoxText = (number: number, count: number, missing: readonly number[]): string =>
  `#${number} has ${count} ${count === 1 ? 'box' : 'boxes'}, so there is no box ${missing.join(', ')}`

// Why a pull request can't merge as it stands, from GitHub's merge state: conflicts with its base, or behind it.
export const mergeNoteOf = (pr: PullRequest): { text: string; color: ThemeKey } | null =>
  pr.mergeState === 'DIRTY' ? { text: '⚠ conflicts', color: 'error' } : pr.mergeState === 'BEHIND' ? { text: '↓ behind', color: 'warning' } : null

type RawComment = { author?: { login?: string } | null; body?: string | null; createdAt?: string }

// An issue's comments from `gh issue view --json comments`, oldest first.
export const commentsOf = (json: string): Comment[] =>
  ((JSON.parse(json) as { comments?: RawComment[] | null }).comments ?? []).map(one => ({ author: one.author?.login ?? 'ghost', body: (one.body ?? '').trim(), at: one.createdAt ?? '' }))

// An issue's comments as GitHub's REST answers them, oldest first.
export const restCommentsOf = (items: unknown[]): Comment[] =>
  (items as { user?: { login?: string } | null; body?: string | null; created_at?: string }[]).map(one => ({
    author: one.user?.login ?? 'ghost',
    body: (one.body ?? '').trim(),
    at: one.created_at ?? '',
  }))

// How many comments the issues tool shows, the latest, and how much of each.
export const TOOL_COMMENTS = 10
const TOOL_COMMENT_TEXT = 1500

// An issue's latest comments for Claude, newest last, each with who wrote it and when; and how many earlier ones are
// left out of `total`.
export const commentsText = (comments: Comment[], total: number, now: number): string => {
  if (total === 0) return 'No comments.'
  const shown = comments.slice(-TOOL_COMMENTS)
  const left = total - shown.length
  return [
    left > 0 ? `Comments (the latest ${shown.length} of ${total}; ${left} earlier left out):` : `Comments (${total}):`,
    ...shown.map(one => {
      const when = one.at ? agoText(one.at, now) : ''
      const text = one.body.length > TOOL_COMMENT_TEXT ? `${one.body.slice(0, TOOL_COMMENT_TEXT - 1)}…` : one.body
      return `— @${one.author}${when ? `, ${when}` : ''}:\n${text.replace(/^/gm, '  ')}`
    }),
  ].join('\n')
}

// What Ask Claude to answer hands Claude: the issue, the comment to answer, and how to reply.
export const answerPrompt = (issue: Issue, comment: Comment): string => {
  const quoted = comment.body.length > 400 ? `${comment.body.slice(0, 399)}…` : comment.body
  return (
    `Answer the latest comment on #${issue.number}: ${issue.title}. @${comment.author} wrote:\n\n${quoted.replace(/^/gm, '> ')}\n\n` +
    `Read the whole thread with \`gh issue view ${issue.number} --comments\` first. Then reply on the issue with the mcp__issue-board__issue_update tool's comment.`
  )
}

// `Closes #N` and its kin, and `Refs #N`: a pull request saying which issue it is for, closing it or not.
const REFERENCE = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?|refs?)\b:?\s+#(\d+)/gi

// The issues a pull request is for: the ones GitHub links as closing, then the ones its body refers to.
export const issuesOf = (closing: { number: number }[], body: string): number[] => [
  ...new Set([...closing.map(one => one.number), ...[...body.matchAll(REFERENCE)].map(match => Number(match[1]))]),
]

export const areaOf = (issue: Issue): string => {
  const label = issue.labels.find(one => one.name.startsWith('area:'))
  return label ? label.name.slice('area:'.length) : 'other'
}

// The labels worth a chip on a row: not the area it is grouped under, not the bug label (a badge of its own).
export const chipsOf = (issue: Issue, markers: Markers = DEFAULT_MARKERS): Label[] => issue.labels.filter(one => !one.name.startsWith('area:') && !isBugLabel(one, markers))

// A label's color as a surface draws it: GitHub's hex, or nothing for a label without one.
export const hex = (label: Label): string | undefined => (/^[0-9a-f]{6}$/i.test(label.color) ? `#${label.color}` : undefined)

// Whether the issue belongs under the filter; `viewer` is the login Mine means. With a project, Active is Now (P0 and
// P1) and Future is Later (P2); without one they read the repo's later label. `markers` are the bug and later labels
// the board goes by.
export const matches = (filter: BuiltInFilter, issue: Issue, viewer: string | null = null, project: Project | null = null, markers: Markers = DEFAULT_MARKERS): boolean => {
  switch (filter) {
    case 'active':
      return project ? isNow(project, issue) : !isFuture(issue, markers)
    case 'future':
      return project ? isLater(project, issue) : isFuture(issue, markers)
    case 'bugs':
      return isBug(issue, markers)
    case 'mine':
      return viewer !== null && issue.assignees.includes(viewer)
    case 'all':
      return true
    case 'inbox':
      return isInbox(issue, project)
    case 'closed':
      return false
  }
}

// Whether an issue waits in the project's Inbox: its Status is the Inbox option, or it has none, as an issue not in the
// project. A project with no Inbox option has no Inbox.
export const isInbox = (issue: Issue, project: Project | null | undefined): boolean =>
  roleOf(project, 'inbox') !== undefined && (!issue.status || isRole(project, issue.status, 'inbox'))

// The Status an issue moves to out of the Inbox when Claude didn't say: Ready for Now's priorities, Backlog otherwise.
export const statusFor = (project: Project | null, priority: string | null): 'Ready' | 'Backlog' => (priorityRank(project, priority) < NOW_COUNT ? 'Ready' : 'Backlog')

// How much of an issue's text Claude reads to triage it.
const TRIAGE_TEXT = 1500

// What the Inbox asks Claude: a Priority, an area and a Status for each issue, as JSON. The rules come first, marked
// for the prompt cache, and hold nothing that changes from one ask to the next, so a retry or the next batch within five
// minutes reads them from the cache. The repo and the issues follow in a second block. The engine joins the blocks with
// nothing between them, so the second opens with its own blank line.
export const triagePrompt = (repo: string, issues: Issue[], priorities: { name: string; description: string }[], areas: string[]): ModelTextBlock[] => [
  {
    text: [
      'Triage the new GitHub issues listed below. For each, suggest:',
      priorities.length > 0
        ? `- priority: one of ${priorities.map(one => (one.description ? `${one.name} (${one.description})` : one.name)).join(', ')};`
        : '- priority: null, as the project has no Priority field;',
      areas.length > 0 ? `- area: the part of the repository it is about, one of ${areas.join(', ')}, or null when none fits;` : '- area: null, as the repository has no area labels;',
      '- status: "Ready" when it is clear enough to start on now, "Backlog" when it should wait;',
      '- reason: one short, plain sentence saying why.',
      'Keep a Priority or area the issue already has unless it is clearly wrong.',
      'Answer with one JSON array and nothing else: [{"number": 1, "priority": "P1", "area": "...", "status": "Ready", "reason": "..."}].',
    ].join('\n'),
    cache: true,
  },
  {
    text: [
      '',
      '',
      `The issues, of ${repo}:`,
      ...issues.flatMap(issue => {
        const text = issue.body.trim()
        return [
          '',
          `#${issue.number} ${issue.title}`,
          `Labels: ${issue.labels.map(label => label.name).join(', ') || 'none'}. Priority: ${issue.priority ?? 'none'}.`,
          ...(text ? [text.length > TRIAGE_TEXT ? `${text.slice(0, TRIAGE_TEXT - 1)}…` : text] : []),
        ]
      }),
    ].join('\n'),
  },
]

// Claude's suggestions read back from its answer, one per issue asked about, keeping only the priorities and areas
// offered; a Status it didn't give follows the priority.
export const parseTriage = (text: string, issues: Issue[], priorities: string[], areas: string[], project: Project | null = null): Suggestion[] => {
  const json = /\[[\s\S]*\]/.exec(text)?.[0]
  let raw: unknown
  try {
    raw = json ? JSON.parse(json) : null
  } catch {
    return []
  }
  if (!Array.isArray(raw)) return []
  const named = (list: string[], value: unknown) => (typeof value === 'string' ? (list.find(one => one.toLowerCase() === value.replace(/^area:/i, '').trim().toLowerCase()) ?? null) : null)
  const made: Suggestion[] = []
  for (const one of raw as Record<string, unknown>[]) {
    const issue = issues.find(each => each.number === one?.number)
    if (!issue || made.some(each => each.number === issue.number)) continue
    const priority = named(priorities, one.priority)
    const status = typeof one.status === 'string' && /^backlog$/i.test(one.status.trim()) ? 'Backlog' : typeof one.status === 'string' && /^ready$/i.test(one.status.trim()) ? 'Ready' : statusFor(project, priority)
    const reason = typeof one.reason === 'string' ? fit(one.reason.replace(/\s+/g, ' ').trim(), 200) : ''
    made.push({ number: issue.number, priority, area: named(areas, one.area), status, reason, updatedAt: issue.updatedAt })
  }
  return made
}

// Whether the issue matches what was typed in the search field: words of its title, `#42` or `42`, or a label.
export const searched = (query: string, issue: Issue): boolean => {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  const haystack = `#${issue.number} ${issue.title} ${issue.labels.map(label => label.name).join(' ')}`.toLowerCase()
  return words.every(word => haystack.includes(word))
}

// How many rows `#` offers in the prompt box at most: more would push the engine's own rows off the screen.
export const HASH_ROWS = 8

// One row of the prompt box's typeahead, as `prompt.autocomplete` takes it.
export type HashRow = { text: string; label: string; description: string }

const CI_WORDS: Record<Ci, string> = { pass: 'CI passing', fail: 'CI failing', pending: 'CI running', none: 'no CI' }

// Where a row stands among the others: issues in progress first, then open pull requests, which are work under way
// too, then Ready, Verification, Backlog and Inbox. An issue with no Status, or another one, comes last.
const HASH_ORDER: Role[] = ['started', 'ready', 'verification', 'backlog', 'inbox']
const hashRank = (project: Project | null | undefined, status: string | null | undefined): number => {
  const at = HASH_ORDER.findIndex(role => isRole(project, status, role))
  return at < 0 ? HASH_ORDER.length + 1 : at === 0 ? 0 : at + 1
}

// Whether a number or title matches what follows `#`: digits match the start of the number, anything else a part of
// the title, ignoring case. A bare `#` matches everything.
const hashMatches = (typed: string, number: number, title: string): boolean =>
  /^\d+$/.test(typed) ? String(number).startsWith(typed) : title.toLowerCase().includes(typed.toLowerCase())

// The rows `#` offers for the token at the cursor: the board's open issues and pull requests that match it, in order
// of Status, then Priority, then newest, at most HASH_ROWS. An issue's dim line is its Status, Priority and labels; a
// pull request's is its CI.
export const hashRows = (board: Board, token: string): HashRow[] => {
  const typed = token.replace(/^#/, '')
  const project = board.project
  const issues = board.issues
    .filter(issue => hashMatches(typed, issue.number, issue.title))
    .map(issue => ({
      rank: hashRank(project, issue.status),
      priority: priorityRank(project, issue.priority),
      number: issue.number,
      row: {
        text: `#${issue.number}`,
        label: `#${issue.number} ${issue.title}`,
        description: [issue.status, issue.priority, issue.labels.map(label => label.name).join(', ')].filter(Boolean).join(' · '),
      },
    }))
  const prs = board.prs
    .filter(pr => hashMatches(typed, pr.number, pr.title))
    .map(pr => ({
      rank: 1,
      priority: Number.POSITIVE_INFINITY,
      number: pr.number,
      row: { text: `#${pr.number}`, label: `#${pr.number} ${pr.title}`, description: ['pull request', pr.isDraft ? 'draft' : '', CI_WORDS[pr.ci]].filter(Boolean).join(' · ') },
    }))
  return [...issues, ...prs]
    .sort((a, b) => a.rank - b.rank || (a.priority === b.priority ? 0 : a.priority < b.priority ? -1 : 1) || b.number - a.number)
    .slice(0, HASH_ROWS)
    .map(one => one.row)
}

// Bugs first, then issues under way (some boxes ticked), then the newest.
const rank = (issue: Issue, markers: Markers = DEFAULT_MARKERS): number => {
  if (isBug(issue, markers)) return 0
  const done = issue.checks.filter(check => check.done).length
  return done > 0 && done < issue.checks.length ? 1 : 2
}

export const byArea = (issues: Issue[], markers: Markers = DEFAULT_MARKERS): [string, Issue[]][] => {
  const groups = new Map<string, Issue[]>()
  for (const issue of issues) {
    const area = areaOf(issue)
    groups.set(area, [...(groups.get(area) ?? []), issue])
  }
  return [...groups.entries()]
    .sort(([a], [b]) => (a === 'other' ? 1 : b === 'other' ? -1 : a.localeCompare(b)))
    .map(([area, list]) => [area, [...list].sort((a, b) => rank(a, markers) - rank(b, markers) || b.number - a.number)])
}

// Whether an issue waits on another that is still open.
export const isBlocked = (issue: Issue): boolean => (issue.blockedBy ?? []).length > 0

// The most pressing first: by priority when there is a project, then bugs, issues under way and the newest. With
// `readyFirst`, as within an epic, the ones nothing blocks come before the ones that wait, and the oldest before the
// newest: an epic's sub-issues are mostly written in the order they're meant to be done.
export const sortIssues = (issues: Issue[], project: Project | null = null, readyFirst = false, order?: number[], markers: Markers = DEFAULT_MARKERS): Issue[] => {
  // GitHub's order of an epic's sub-issues settles what the board has no reason to: one it doesn't list goes last.
  const at = (issue: Issue) => {
    const index = order?.indexOf(issue.number) ?? -1
    return index < 0 ? Number.MAX_SAFE_INTEGER : index
  }
  return [...issues].sort(
    (a, b) =>
      (readyFirst ? Number(isBlocked(a)) - Number(isBlocked(b)) : 0) ||
      priorityRank(project, a.priority) - priorityRank(project, b.priority) ||
      rank(a, markers) - rank(b, markers) ||
      (order ? at(a) - at(b) : 0) ||
      (readyFirst ? a.number - b.number : b.number - a.number),
  )
}

// A group's rows: the issues the project holds in the project's own order, the order a person sets by dragging rows on
// GitHub, then the rest in the board's order. A board read without the project's order has no positions, and is all in
// the board's order.
export const projectOrder = (issues: Issue[], project: Project | null = null, markers: Markers = DEFAULT_MARKERS): Issue[] => {
  const placed = issues.filter(issue => issue.position !== undefined).sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
  return [...placed, ...sortIssues(issues.filter(issue => issue.position === undefined), project, false, undefined, markers)]
}

// The sub-issue an epic's Next starts: the first open one nothing blocks, in the order the epic lists them.
export const nextOf = (issues: Issue[], epic: number, project: Project | null = null, markers: Markers = DEFAULT_MARKERS): Issue | undefined =>
  sortIssues(
    issues.filter(issue => issue.parent?.number === epic),
    project,
    true,
    issues.find(issue => issue.number === epic)?.subOrder,
    markers,
  ).find(issue => !isBlocked(issue))

// What Start on an issue starts. An epic is worked one sub-issue at a time, so Start on one starts its next ready
// sub-issue, as Next does; null when its open sub-issues are all blocked. An epic whose sub-issues are all closed
// starts itself, so its own open boxes can be finished. Any other issue starts itself.
export const startTargetOf = (issues: Issue[], issue: Issue, project: Project | null = null, markers: Markers = DEFAULT_MARKERS): Issue | null => {
  const subs = issue.subIssues
  if (!subs || subs.total === 0 || subs.completed >= subs.total) return issue
  return nextOf(issues, issue.number, project, markers) ?? null
}

// What Start on an epic says when every open sub-issue is blocked.
export const noReadyText = (epic: number): string => `Epic #${epic} has no ready sub-issue to start: each open one is blocked.`

// A heading of the issue list and the issues under it. `folded`: drawn shut until the person opens it, as the Backlog
// option is.
// `epic`: the parent the group is for, so its row isn't drawn again beneath it.
export type Group = { key: string; title: string; issues: Issue[]; folded: boolean; epic?: { number: number; total: number; completed: number } }

// The issues in groups: by the project's Status in the project's order, by the epic they are sub-issues of, or by
// `area:` label. Issues that don't fit a group come last, under No status, No epic or other. Rows follow the project's
// own order, except an epic's sub-issues, which keep the epic's order.
export const groupsOf = (issues: Issue[], by: GroupBy, project: Project | null = null, field: string | null = null, markers: Markers = DEFAULT_MARKERS): Group[] => {
  if (by === 'view' && field) return groupsByField(issues, field, project, markers)
  if (by === 'status' && project) {
    const named = (project.status?.options ?? []).map(option => ({
      key: `status:${option.name}`,
      title: option.name,
      issues: projectOrder(issues.filter(issue => issue.status === option.name), project, markers),
      folded: isRole(project, option.name, 'backlog'),
    }))
    const known = new Set(named.map(group => group.title))
    const rest = projectOrder(issues.filter(issue => !issue.status || !known.has(issue.status)), project, markers)
    return [...named, { key: 'status:none', title: 'No status', issues: rest, folded: false }].filter(group => group.issues.length > 0)
  }
  if (by === 'epic') {
    const parents = new Map<number, NonNullable<Issue['parent']>>()
    for (const issue of issues) if (issue.parent) parents.set(issue.parent.number, issue.parent)
    const epics = [...parents.values()]
      .sort((a, b) => a.number - b.number)
      .map(parent => ({
        key: `epic:${parent.number}`,
        title: `#${parent.number} ${parent.title}`,
        issues: sortIssues(
          issues.filter(issue => issue.parent?.number === parent.number),
          project,
          true,
          issues.find(issue => issue.number === parent.number)?.subOrder,
          markers,
        ),
        folded: false,
        epic: { number: parent.number, total: parent.total, completed: parent.completed },
      }))
    // An open epic is its group's heading, so it isn't listed again under No epic.
    const rest = projectOrder(issues.filter(issue => !issue.parent && !parents.has(issue.number)), project, markers)
    return [...epics, { key: 'epic:none', title: 'No epic', issues: rest, folded: false }].filter(group => group.issues.length > 0)
  }
  return byArea(issues, markers).map(([area, list]) => ({ key: `area:${area}`, title: area, issues: project ? projectOrder(list, project, markers) : list, folded: false }))
}

// The issues grouped by a field a project view groups by, such as Area or Sprint: the field's options in the project's
// order, then any other value an issue has, then the issues with none.
const groupsByField = (issues: Issue[], name: string, project: Project | null, markers: Markers): Group[] => {
  const options = projectFieldOf(name, project)?.options?.map(option => option.name) ?? []
  const valueOf = (issue: Issue) => fieldValuesOf(issue, name, project)[0] ?? ''
  const others = [...new Set(issues.map(valueOf).filter(value => value !== '' && !options.some(option => same(option, value))))].sort()
  const named = [...options, ...others].map(value => ({
    key: `field:${name}:${value}`,
    title: value,
    issues: projectOrder(
      issues.filter(issue => same(valueOf(issue), value)),
      project,
      markers,
    ),
    folded: false,
  }))
  const rest = projectOrder(
    issues.filter(issue => valueOf(issue) === ''),
    project,
    markers,
  )
  return [...named, { key: `field:${name}:none`, title: `No ${name}`, issues: rest, folded: false }].filter(group => group.issues.length > 0)
}

// A field named the way a filter writes it: any case, and a hyphen for a space, so `story-points` is Story Points.
const sameField = (written: string, name: string): boolean => same(written.replace(/-/g, ' '), name.replace(/-/g, ' '))

// The issue's own qualifiers, which a filter writes by these names, and the values each gives.
const ISSUE_VALUES: Record<string, (issue: Issue) => string[]> = {
  status: issue => (issue.status ? [issue.status] : []),
  priority: issue => (issue.priority ? [issue.priority] : []),
  label: issue => issue.labels.map(label => label.name),
  assignee: issue => issue.assignees,
  milestone: issue => (issue.milestone ? [issue.milestone] : []),
  type: issue => (issue.type ? [issue.type] : []),
}
const ISSUE_ALIASES: Record<string, string> = { labels: 'label', assignees: 'assignee', 'issue type': 'type', 'issue-type': 'type' }
const issueKeyOf = (written: string): string | undefined => {
  const key = written.trim().toLowerCase()
  return ISSUE_VALUES[key] ? key : ISSUE_ALIASES[key]
}

// The project field a filter or grouping names, beyond the issue's own qualifiers.
const projectFieldOf = (written: string, project: Project | null | undefined): ProjectField | undefined =>
  (project?.fields ?? []).find(field => sameField(written, field.name))

// The values an issue has in a field, by the name a view uses: the issue's own (Status, Labels, Milestone…), or a
// project field the board read for the views. Unknown or unset, none.
export const fieldValuesOf = (issue: Issue, name: string, project: Project | null | undefined): string[] => {
  const own = issueKeyOf(name)
  if (own) return ISSUE_VALUES[own]?.(issue) ?? []
  const field = projectFieldOf(name, project)
  const value = field ? issue.fields?.[field.name] : undefined
  return value ? [value] : []
}

// One term of a project view's filter: `label:bug,docs` is the key `label` and two values, `-status:Done` a negated
// term, and a plain word has no key. `raw` is the term as written, for the note about a term the board can't apply.
export type FilterTerm = { key: string | null; values: string[]; negate: boolean; raw: string }

// Splits on `at` (a space, or a comma) wherever it is outside double quotes.
const splitOutside = (text: string, at: RegExp): string[] => {
  const parts: string[] = []
  let current = ''
  let quoted = false
  for (const char of text) {
    if (char === '"') quoted = !quoted
    if (!quoted && at.test(char)) {
      parts.push(current)
      current = ''
      continue
    }
    current += char
  }
  parts.push(current)
  return parts.filter(part => part.trim() !== '')
}
const unquoted = (text: string): string => text.replace(/"/g, '').trim()

// A view's filter as GitHub writes it, term by term. A quoted value or key may hold spaces, and a comma list means any.
export const parseFilter = (text: string): FilterTerm[] =>
  splitOutside(text.trim(), /\s/).map(raw => {
    const negate = raw.length > 1 && raw.startsWith('-')
    const body = negate ? raw.slice(1) : raw
    let colon = -1
    let quoted = false
    for (let index = 0; index < body.length; index += 1) {
      if (body[index] === '"') quoted = !quoted
      else if (body[index] === ':' && !quoted) {
        colon = index
        break
      }
    }
    if (colon <= 0) return { key: null, values: [unquoted(body)], negate, raw }
    return {
      key: unquoted(body.slice(0, colon)).toLowerCase(),
      values: splitOutside(body.slice(colon + 1), /,/)
        .map(unquoted)
        .filter(Boolean),
      negate,
      raw,
    }
  })

// A value the board compares as text. Ranges, comparisons, wildcards and `@` dates or iterations need more than the
// board knows, so a term holding one is named as one it can't apply. `@me` is the person, for assignee.
const plainValue = (value: string, key: string | undefined): boolean =>
  value.startsWith('@') ? value.toLowerCase() === '@me' && key === 'assignee' : !/^[<>]|\.\.|\*/.test(value)

// A test of one issue against a filter, with the login `@me` means.
type IssueTest = (issue: Issue, viewer: string | null) => boolean

// The board holds open issues only, so `is:open` and `is:issue` keep each of them, `is:closed` and `is:pr` none.
const IS_KINDS: Record<string, boolean> = { open: true, closed: false, issue: true, pr: false }

// The test for one term, or null for a term the board can't apply.
const termTest = (term: FilterTerm, project: Project | null | undefined): IssueTest | null => {
  if (term.key === null) {
    const word = term.values[0] ?? ''
    if (word === '') return null
    const number = /^#?(\d+)$/.exec(word)?.[1]
    return issue => (number !== undefined && String(issue.number) === number) || issue.title.toLowerCase().includes(word.toLowerCase())
  }
  if (term.values.length === 0) return null
  if (term.key === 'is') {
    if (!term.values.every(value => value.toLowerCase() in IS_KINDS)) return null
    const kept = term.values.some(value => IS_KINDS[value.toLowerCase()])
    return () => kept
  }
  if (term.key === 'no' || term.key === 'has') {
    if (!term.values.every(name => issueKeyOf(name) !== undefined || projectFieldOf(name, project) !== undefined)) return null
    const empty = term.key === 'no'
    return issue => term.values.some(name => (fieldValuesOf(issue, name, project).length === 0) === empty)
  }
  const key = term.key
  const own = issueKeyOf(key)
  if (!own && !projectFieldOf(key, project)) return null
  if (!term.values.every(value => plainValue(value, own))) return null
  return (issue, viewer) => {
    const has = fieldValuesOf(issue, key, project)
    return term.values.some(value => {
      const wanted = value.toLowerCase() === '@me' ? viewer : value
      return wanted !== null && has.some(one => same(one, wanted))
    })
  }
}

// What a view's filter keeps, as a test on one issue, with the terms the board can't apply. Those are left out of the
// test, so the tab shows every issue the rest of the filter keeps: more than GitHub would, never fewer.
export type ViewMatch = { test: IssueTest; unknown: string[] }

export const viewMatchOf = (filter: string, project: Project | null | undefined): ViewMatch => {
  const tests: IssueTest[] = []
  const unknown: string[] = []
  for (const term of parseFilter(filter)) {
    const test = termTest(term, project)
    if (!test) unknown.push(term.raw)
    else tests.push(term.negate ? (issue, viewer) => !test(issue, viewer) : test)
  }
  return { test: (issue, viewer) => tests.every(test => test(issue, viewer)), unknown }
}

// The project fields the views filter or group by, beyond the issue's own qualifiers, Status and Priority, which the
// board reads anyway: the extra values the issues query asks each item for.
export const viewFieldsOf = (project: Project | null | undefined): string[] => {
  const names = new Set<string>()
  const add = (written: string) => {
    const field = issueKeyOf(written) ? undefined : projectFieldOf(written, project)
    if (field) names.add(field.name)
  }
  for (const view of viewTabsOf(project)) {
    for (const term of parseFilter(view.filter)) {
      if (term.key === 'no' || term.key === 'has') term.values.forEach(add)
      else if (term.key && term.key !== 'is') add(term.key)
    }
    if (view.groupBy) add(view.groupBy)
  }
  return [...names].sort()
}

// The built-in filters; with a project, the first two read Priority and say so.
export const BUILT_IN_FILTERS: { id: BuiltInFilter; label: string; planned: string; hotkey: string }[] = [
  { id: 'active', label: 'Active', planned: 'Now', hotkey: '1' },
  { id: 'future', label: 'Future', planned: 'Later', hotkey: '2' },
  { id: 'bugs', label: 'Bugs', planned: 'Bugs', hotkey: '3' },
  { id: 'mine', label: 'Mine', planned: 'Mine', hotkey: '4' },
  { id: 'all', label: 'All', planned: 'All', hotkey: '5' },
  { id: 'inbox', label: 'Inbox', planned: 'Inbox', hotkey: '6' },
  { id: 'closed', label: 'Closed', planned: 'Closed', hotkey: '7' },
]

// A tab of the pane: a built-in filter, or a project view.
export type Tab = { id: Filter; name: string; hotkey: string; view?: ProjectView }

// How many views become tabs at most, so they, All and Closed fit on the keys 1 to 9.
export const VIEW_TABS = 7

// The views that become tabs: the table and board views with a filter, in GitHub's order. A view with no filter shows
// every issue, which All already does, so it is left out. So is a roadmap, which lays issues out by date.
export const viewTabsOf = (project: Project | null | undefined): ProjectView[] =>
  (project?.views ?? []).filter(view => view.layout !== 'roadmap' && view.filter.trim() !== '').slice(0, VIEW_TABS)

// The pane's tabs, on the keys 1 to 9 in order. With views that have filters: those views, then the built-in Inbox
// when the project has an Inbox and no view keeps just it, then All and Closed. Without any: the built-in ones, Inbox
// only with a project that has one.
export const tabsOf = (project: Project | null | undefined): Tab[] => {
  const hasInbox = roleOf(project, 'inbox') !== undefined
  const found = viewTabsOf(project)
  if (found.length === 0) {
    return BUILT_IN_FILTERS.filter(one => one.id !== 'inbox' || hasInbox).map(one => ({
      id: one.id,
      name: project ? one.planned : one.label,
      hotkey: one.hotkey,
    }))
  }
  // The Inbox takes a key of its own, so one view fewer fits.
  const inbox = hasInbox && !found.some(view => isInboxFilter(view.filter, project))
  const views = inbox ? found.slice(0, VIEW_TABS - 1) : found
  const after: { id: BuiltInFilter; name: string }[] = [...(inbox ? [{ id: 'inbox' as const, name: 'Inbox' }] : []), { id: 'all', name: 'All' }, { id: 'closed', name: 'Closed' }]
  return [
    ...views.map((view, index): Tab => ({ id: `view:${view.number}`, name: view.name, hotkey: String(index + 1), view })),
    ...after.map((tab, index): Tab => ({ ...tab, hotkey: String(views.length + index + 1) })),
  ]
}

// The tab a chosen filter is: the one it names, or else the first tab. A built-in filter chosen before the project's
// views became the tabs, or a view since removed, lands there.
export const tabOf = (tabs: Tab[], chosen: Filter): Tab => tabs.find(tab => tab.id === chosen) ?? tabs[0] ?? { id: 'all', name: 'All', hotkey: '5' }

// Whether an issue belongs under a tab: its view's filter, or its built-in filter. Made once a tab, then used per issue.
export const tabTest = (tab: Tab, project: Project | null | undefined, markers: Markers = DEFAULT_MARKERS): IssueTest => {
  if (tab.view) return viewMatchOf(tab.view.filter, project).test
  const id = tab.id as BuiltInFilter
  return (issue, viewer) => matches(id, issue, viewer, project ?? null, markers)
}

// What the issues group by: the one the person picked, while it still applies, else the view's own, else Status with
// a project and area without one. The view's field grouping applies only while its tab shows, and Status only with a
// project.
export const groupingOf = (picked: GroupBy | null, view: { by: GroupBy; field: string } | null, hasProject: boolean): GroupBy => {
  const field = view?.by === 'view' ? view.field : null
  const fallback: GroupBy = hasProject ? 'status' : 'area'
  if (picked === 'view') return field ? 'view' : fallback
  return picked && (picked !== 'status' || hasProject) ? picked : (view?.by ?? fallback)
}

// How a view's tab groups its issues: by Status or by epic as the pane does, by another field the board read, or not
// at all (null) for a field it can't group by, such as Labels, of which an issue may have several.
export const viewGroupingOf = (view: ProjectView | undefined, project: Project | null | undefined): { by: GroupBy; field: string } | null => {
  const name = view?.groupBy
  if (!name) return null
  if (same(name, 'Status')) return project?.status ? { by: 'status', field: name } : null
  if (same(name, 'Parent issue')) return { by: 'epic', field: name }
  const own = issueKeyOf(name)
  if (own === 'label' || own === 'assignee') return null
  return own || projectFieldOf(name, project) ? { by: 'view', field: name } : null
}

// A view's page on GitHub.
export const viewUrl = (project: { url: string }, view: { number: number }): string => `${project.url}/views/${view.number}`

// A GraphQL connection as GitHub answers it, any level of which may be missing; the board's read and setup's share it.
export type RawNodes<T> = { nodes?: (T | null)[] | null } | null | undefined
// A project field as a GraphQL fragment answers it. `options` are a single-select field's; setup reads them with their
// colors and descriptions, the board with only their ids and names.
export type RawField<O = { id: string; name: string }> = { id?: string; name?: string; dataType?: string; options?: O[]; configuration?: { iterations?: { id: string; title: string }[] } | null }
// What the board's read and setup both ask of a project.
export type RawProjectBase<O = { id: string; name: string }> = {
  id: string
  number: number
  title: string
  url: string
  closed?: boolean
  fields?: RawNodes<RawField<O>>
  workflows?: RawNodes<{ name: string; enabled: boolean }>
}

// The kind of each field the board can set, by GitHub's data type; the rest, such as Assignees or Labels, are the issue's.
const KINDS: Record<string, ProjectField['kind']> = { TEXT: 'text', NUMBER: 'number', DATE: 'date', ITERATION: 'iteration', SINGLE_SELECT: 'select' }
const fieldsOf = (project: RawProject): ProjectField[] =>
  nodesOf(project.fields).flatMap(one => {
    const kind = one.dataType ? KINDS[one.dataType] : one.options ? 'select' : undefined
    if (!one.id || !one.name || !kind) return []
    const options = kind === 'iteration' ? (one.configuration?.iterations ?? []).map(it => ({ id: it.id, name: it.title })) : one.options
    return [{ id: one.id, name: one.name, kind, ...(options ? { options } : {}) }]
  })
type RawUpdate = { status?: string | null; body?: string | null; createdAt: string; startDate?: string | null; targetDate?: string | null }
type RawProject = RawProjectBase & {
  statusUpdates?: RawNodes<RawUpdate>
  views?: RawNodes<RawView>
  order?: RawNodes<{ id: string }>
}
type RawGroup = RawNodes<{ name?: string }>
type RawView = { name: string; number: number; layout?: string; filter?: string | null; groupByFields?: RawGroup; verticalGroupByFields?: RawGroup }
type RawValue = { name?: string } | null | undefined
type RawAny = { name?: string; title?: string; text?: string; number?: number | null; date?: string } | null | undefined
type RawItem = { id: string; project?: { id: string } | null; status?: RawValue; priority?: RawValue; [alias: `f${number}`]: RawAny }

const LAYOUTS: Record<string, ProjectView['layout']> = { TABLE_LAYOUT: 'table', BOARD_LAYOUT: 'board', ROADMAP_LAYOUT: 'roadmap' }

// A project's views as the board keeps them. A table groups rows by its group-by field; a board's columns are its
// vertical group-by field.
const viewsOf = (project: RawProject): ProjectView[] =>
  nodesOf(project.views).map(view => {
    const layout = LAYOUTS[view.layout ?? ''] ?? 'table'
    const group = nodesOf(view.groupByFields)[0]?.name ?? (layout === 'board' ? nodesOf(view.verticalGroupByFields)[0]?.name : undefined)
    return { name: view.name, number: view.number, layout, filter: (view.filter ?? '').trim(), groupBy: group ?? null }
  })

// A field value as text, whatever the field's kind.
const anyValueOf = (raw: RawAny): string | undefined =>
  raw ? (raw.name ?? raw.title ?? raw.text ?? (typeof raw.number === 'number' ? String(raw.number) : undefined) ?? raw.date) : undefined
type RawGraphIssue = {
  id: string
  number: number
  title: string
  url?: string
  body?: string | null
  updatedAt: string
  labels?: RawNodes<RawLabel>
  assignees?: RawNodes<RawUser>
  milestone?: { title: string } | null
  parent?: { number: number; title: string; subIssuesSummary?: { total: number; completed: number } | null } | null
  subIssuesSummary?: { total: number; completed: number } | null
  blockedBy?: RawNodes<{ number: number; state: string }>
  closedByPullRequestsReferences?: RawNodes<{ number: number }>
  projectItems?: RawNodes<RawItem>
  comments?: { totalCount?: number } | null
  issueType?: { name: string } | null
}
type RawPage = { data?: { repository?: { issueTypes?: RawNodes<{ name: string }>; labels?: RawNodes<{ name: string }>; projectsV2?: RawNodes<RawProject>; issues?: { pageInfo?: { hasNextPage: boolean; endCursor: string | null }; nodes?: (RawGraphIssue | null)[] } } } }

// A connection's nodes, without the missing ones.
export const nodesOf = <T>(list: RawNodes<T>): T[] => (list?.nodes ?? []).filter((one): one is T => one !== null && one !== undefined)

// A project's single-select field by name, whatever its case, with its options.
export const fieldOf = <O>(project: { fields?: RawNodes<RawField<O>> }, name: string): { id: string; options: O[] } | null => {
  const field = nodesOf(project.fields).find(one => one.id && one.name?.toLowerCase() === name.toLowerCase() && one.options)
  return field?.id && field.options ? { id: field.id, options: field.options } : null
}

// GitHub's status of a project update in words, and back.
const STATUS_WORDS: Record<string, string> = { ON_TRACK: 'On track', AT_RISK: 'At risk', OFF_TRACK: 'Off track', COMPLETE: 'Complete', INACTIVE: 'Inactive' }
export const statusEnumOf = (words: string): string | undefined => Object.entries(STATUS_WORDS).find(([, said]) => said.toLowerCase() === words.trim().toLowerCase())?.[0]
export const updateWords = (status: string): string => STATUS_WORDS[status] ?? status

const updateOf = (raw: RawUpdate | undefined): StatusUpdate | null =>
  raw ? { status: updateWords(raw.status ?? ''), body: (raw.body ?? '').trim(), at: raw.createdAt, start: raw.startDate ?? null, target: raw.targetDate ?? null } : null

// A status update in a line: how the project stands, the note's first line, and when.
export const updateLine = (update: StatusUpdate, now: number): string => {
  const when = agoText(update.at, now)
  const note = update.body.split('\n')[0]?.trim() ?? ''
  return [update.status, note, update.target ? `target ${update.target}` : '', when].filter(Boolean).join(' · ')
}

// Where the next page of issues starts, or null after the last.
export const nextPageOf = (json: string): string | null => {
  const info = (JSON.parse(json) as RawPage).data?.repository?.issues?.pageInfo
  return info?.hasNextPage && info.endCursor ? info.endCursor : null
}

// The issues of every page, and the repo's project, read from the first page: the one `/issues setup` saved when it's
// still linked and open, else the first open one linked to the repo. `fields` are the extra field values the query
// asked each item for, in its order.
export const parseGraph = (
  pages: string[],
  preferred?: string,
  fields: readonly string[] = [],
): { issues: Issue[]; project: Project | null; types: string[]; labels?: string[] } => {
  const parsed = pages.map(page => JSON.parse(page) as RawPage)
  const open = nodesOf(parsed[0]?.data?.repository?.projectsV2).filter(one => !one.closed)
  const linked = open.find(one => one.id === preferred) ?? open[0]
  const project: Project | null = linked
    ? {
        id: linked.id,
        number: linked.number,
        title: linked.title,
        url: linked.url,
        status: fieldOf(linked, 'Status'),
        priority: fieldOf(linked, 'Priority'),
        fields: fieldsOf(linked),
        update: updateOf(nodesOf(linked.statusUpdates).at(-1)),
        closesToDone: nodesOf(linked.workflows).some(one => one.name === 'Item closed' && one.enabled),
        views: viewsOf(linked),
      }
    : null
  const issues = parsed.flatMap(page => (page.data?.repository?.issues?.nodes ?? []).filter((one): one is RawGraphIssue => one !== null))
  // The repo's labels, for the Bugs and Later guess; left out when the answer has none, so the guess goes by the labels
  // the issues carry.
  const labels = parsed[0]?.data?.repository?.labels ? nodesOf(parsed[0].data.repository.labels).map(one => one.name) : undefined
  // Each item's place in the project's own order, by item id.
  const positions = new Map(nodesOf(linked?.order).map((one, index) => [one.id, index]))
  return {
    types: nodesOf(parsed[0]?.data?.repository?.issueTypes).map(one => one.name),
    ...(labels ? { labels } : {}),
    project,
    issues: issues.map(raw => {
      const item = project ? nodesOf(raw.projectItems).find(one => one.project?.id === project.id) : undefined
      const parent = raw.parent
      const values = item
        ? fields.flatMap((name, index) => {
            const value = anyValueOf(item[`f${index}`])
            return value === undefined ? [] : [[name, value] as const]
          })
        : []
      return {
        number: raw.number,
        title: raw.title,
        url: raw.url ?? '',
        labels: nodesOf(raw.labels).map(label => ({ name: label.name, color: label.color ?? '' })),
        assignees: nodesOf(raw.assignees).map(user => user.login),
        checks: checksOf(raw.body ?? null),
        updatedAt: raw.updatedAt,
        body: raw.body ?? '',
        id: raw.id,
        item: item?.id ?? null,
        status: item?.status?.name ?? null,
        priority: item?.priority?.name ?? null,
        milestone: raw.milestone?.title ?? null,
        parent: parent ? { number: parent.number, title: parent.title, total: parent.subIssuesSummary?.total ?? 0, completed: parent.subIssuesSummary?.completed ?? 0 } : null,
        subIssues: { total: raw.subIssuesSummary?.total ?? 0, completed: raw.subIssuesSummary?.completed ?? 0 },
        blockedBy: nodesOf(raw.blockedBy).filter(one => one.state === 'OPEN').map(one => one.number),
        prs: nodesOf(raw.closedByPullRequestsReferences).map(one => one.number),
        ...(typeof raw.comments?.totalCount === 'number' ? { comments: raw.comments.totalCount } : {}),
        ...(raw.issueType ? { type: raw.issueType.name } : {}),
        ...(values.length > 0 ? { fields: Object.fromEntries(values) } : {}),
        ...(item && positions.has(item.id) ? { position: positions.get(item.id) } : {}),
      }
    }),
  }
}

// The open pull requests for an issue: the ones GitHub says close it, and the ones that say they are for it.
export const prsFor = (issue: Issue, prs: PullRequest[]): PullRequest[] =>
  prs.filter(pr => (issue.prs ?? []).includes(pr.number) || (pr.issues ?? []).includes(issue.number))

export type Progress = { done: number; total: number }

// The lines a wrapping row of items takes, each item its width in cells and `gap` cells between two on a line.
export const wrappedLines = (widths: number[], width: number, gap = 1): number => {
  let lines = 1
  let used = 0
  for (const one of widths) {
    if (used > 0 && used + gap + one > width) {
      lines += 1
      used = 0
    }
    used += (used > 0 ? gap : 0) + one
  }
  return lines
}

// What a row's hover card holds, given the lines free above the row: the title and how far along, then up to four open
// boxes, "+N more" for the rest, and the hint line. Short of room, it drops the hint and lists the boxes that fit. Null
// when not even the title and how far along fit. The card only ever goes above its row: a floating box paints over what
// is drawn before it, and the rows after it would paint over a card below.
export type PeekPlace = { listed: number; more: boolean; hint: boolean }
export const peekPlace = (above: number, todo: number): PeekPlace | null => {
  const listed = Math.min(todo, 4)
  const more = todo > listed
  // Two lines of border, the title, how far along and the hint.
  if (above >= 5 + listed + (more ? 1 : 0)) return { listed, more, hint: true }
  const spare = above - 4
  if (spare < 0) return null
  if (spare >= listed + (more ? 1 : 0)) return { listed, more, hint: false }
  const fits = Math.max(0, spare - 1)
  return { listed: fits, more: spare > fits, hint: false }
}

export const progress = (checks: Check[]): Progress => ({ done: checks.filter(check => check.done).length, total: checks.length })

export const sumProgress = (issues: Issue[]): Progress =>
  issues.reduce((sum, issue) => {
    const one = progress(issue.checks)
    return { done: sum.done + one.done, total: sum.total + one.total }
  }, { done: 0, total: 0 })

// A bar of `width` cells, filled in proportion: the filled and the empty run, drawn in two colors.
export const bar = ({ done, total }: Progress, width: number): [string, string] => {
  if (total === 0) return ['', '╌'.repeat(width)]
  const filled = done === total ? width : Math.min(width - 1, Math.round((done / total) * width))
  return ['━'.repeat(filled), '━'.repeat(width - filled)]
}

// How far along, as the color the bar is drawn in.
export const tone = ({ done, total }: Progress): ThemeKey => (total > 0 && done === total ? 'success' : done > 0 ? 'warning' : 'inactive')

export const ciMark: Record<Ci, string> = { pass: '✓', fail: '✗', pending: '…', none: '·' }

export const ciBadge: Record<Ci, { text: string; color: ThemeKey }> = {
  pass: { text: ' ✓ PASS ', color: 'success' },
  fail: { text: ' ✗ FAIL ', color: 'error' },
  pending: { text: ' ◷ CI ', color: 'warning' },
  none: { text: ' · NO CI ', color: 'inactive' },
}

// A CI state's mark alone, as a row or a count shows it beside a pull request.
export const ciGlyph = (ci: Ci): string => ciBadge[ci].text.trim().split(' ')[0] ?? ''

// The folded Pull requests heading: how many are open, then how many pass, fail and are running, each that has any.
export const prCountsText = (prs: PullRequest[]): string =>
  [
    `${prs.length} open`,
    ...(['pass', 'fail', 'pending'] as const).flatMap(ci => {
      const count = prs.filter(pr => pr.ci === ci).length
      return count > 0 ? [`${ciGlyph(ci)} ${count}`] : []
    }),
  ].join(' · ')

export const reviewBadge = (pr: PullRequest): { text: string; color: ThemeKey } | undefined => {
  if (pr.isDraft) return { text: 'draft', color: 'inactive' }
  switch (pr.review) {
    case 'APPROVED':
      return { text: '● approved', color: 'success' }
    case 'CHANGES_REQUESTED':
      return { text: '● changes requested', color: 'error' }
    case 'REVIEW_REQUIRED':
      return { text: '○ review required', color: 'warning' }
    default:
      return undefined
  }
}

// How long ago, the way GitHub's lists say it: now, 5m, 3h, 2d, 6w, 1y. It takes a time in milliseconds or an ISO
// string, and gives '' for one it can't read.
export const ago = (when: number | string, now: number): string => {
  const at = typeof when === 'number' ? when : Date.parse(when)
  if (Number.isNaN(at)) return ''
  const minutes = Math.max(0, Math.floor((now - at) / 60_000))
  if (minutes < 1) return 'now'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h`
  const days = Math.floor(hours / 24)
  if (days < 14) return `${days}d`
  if (days < 365) return `${Math.floor(days / 7)}w`
  return `${Math.floor(days / 365)}y`
}

// How long ago as words for a sentence: "just now" under a minute, else "5m ago". Bare `ago` says "now" then, which
// reads wrong with " ago" after it. Gives '' for a time it can't read.
export const agoText = (when: number | string, now: number): string => {
  const age = ago(when, now)
  return age === 'now' ? 'just now' : age ? `${age} ago` : ''
}

// Characters a terminal draws two cells wide: emoji shown as emoji, such as ⛔, and East Asian wide characters.
const WIDE = /\p{Emoji_Presentation}|[ᄀ-ᅟ⺀-〾ぁ-㏿㐀-䶿一-鿿ꀀ-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦\u{20000}-\u{3FFFD}]/u
// Characters drawn on the one before them, taking no cell: combining marks, variation selectors, the emoji joiner.
const ZERO = /\p{Mn}|\p{Me}|[​-‍︀-️]/u

const cellsOf = (char: string): number => (ZERO.test(char) ? 0 : WIDE.test(char) ? 2 : 1)

// How many terminal cells `text` takes, which isn't its length when it holds emoji or wide characters.
export const cells = (text: string): number => [...text].reduce((sum, char) => sum + cellsOf(char), 0)

// `text` cut to `width` cells, an ellipsis standing in for what was cut. Counted in cells, so a line holding ⛔ isn't a
// cell wider than it should be and doesn't wrap.
export const fit = (text: string, width: number): string => {
  if (width <= 0) return ''
  if (cells(text) <= width) return text
  let kept = ''
  let used = 0
  for (const char of text) {
    const size = cellsOf(char)
    if (used + size > width - 1) break
    kept += char
    used += size
  }
  return `${kept}…`
}

// What an issue's row has room for. `left` is the cells before the title; each right-hand part is its width in cells,
// 0 when the row has none, and `rest` the parts that always stay. A narrow pane drops the label chips first, then the
// progress bar, then the age, until the title has `floor` cells. The title gets whatever is left, so the row stays on
// one line.
export const rowRoom = (
  width: number,
  left: number,
  parts: { chips: number; bar: number; age: number; rest: number },
  floor = 24,
): { chips: boolean; bar: boolean; age: boolean; title: number } => {
  const shown = { chips: parts.chips > 0, bar: parts.bar > 0, age: parts.age > 0 }
  const room = () => width - left - parts.rest - (shown.chips ? parts.chips : 0) - (shown.bar ? parts.bar : 0) - (shown.age ? parts.age : 0)
  for (const part of ['chips', 'bar', 'age'] as const) {
    if (room() >= floor) break
    shown[part] = false
  }
  return { ...shown, title: Math.max(1, room()) }
}

// What a pull request's row has room for. `fixed` is the cells that always stay: the CI badge, the number, the ◆ and
// the gaps around the title. Each part is its width in cells with the gap before it, 0 when the row has none. Short of
// room for a title of `floor` cells, the row drops the reviewers it asks, then the open threads, the diff counts, the
// linked issue, the merge note and the review mark, in that order, and last shortens Finish & merge to Merge. The
// title gets what is left, so the row stays on one line.
export const PR_PARTS = ['asked', 'threads', 'size', 'issue', 'merge', 'review'] as const
export type PrPart = (typeof PR_PARTS)[number]
export const FINISH = '⇲ Finish & merge'
export const FINISH_SHORT = '⇲ Merge'
export const prRowRoom = (
  width: number,
  fixed: number,
  parts: Record<PrPart, number>,
  floor = 16,
): { shown: Record<PrPart, boolean>; finish: string; title: number } => {
  const shown = Object.fromEntries(PR_PARTS.map(part => [part, parts[part] > 0])) as Record<PrPart, boolean>
  let finish = FINISH
  // A framed button is its label and four cells of brackets, with a cell between it and the title's side.
  const room = () => width - fixed - (cells(finish) + 4 + 1) - PR_PARTS.reduce((sum, part) => sum + (shown[part] ? parts[part] : 0), 0)
  for (const part of PR_PARTS) {
    if (room() >= floor) break
    shown[part] = false
  }
  if (room() < floor) finish = FINISH_SHORT
  return { shown, finish, title: Math.max(1, room()) }
}

// `text` padded with spaces to `width` cells.
export const pad = (text: string, width: number): string => `${text}${' '.repeat(Math.max(0, width - cells(text)))}`

// The board in a line, such as `35 issues · 1 bug · PR #335✓`; undefined with nothing open, so nothing shows.
// `footer`: the branch whose pull request Claude Code's own PR footer already shows in the same row. That pull request
// is left out of the list, so the row doesn't name it twice.
export const summary = (issues: Issue[], prs: PullRequest[], markers: Markers = DEFAULT_MARKERS, footer: string | null = null): string | undefined => {
  const bugs = issues.filter(issue => isBug(issue, markers)).length
  const listed = footer === null ? prs : prs.filter(pr => pr.branch !== footer)
  const parts: string[] = []
  if (issues.length > 0) parts.push(`${issues.length} issue${issues.length === 1 ? '' : 's'}`)
  if (bugs > 0) parts.push(`${bugs} bug${bugs === 1 ? '' : 's'}`)
  if (listed.length > 0) parts.push(`PR ${listed.map(pr => `#${pr.number}${ciMark[pr.ci]}`).join(' ')}`)
  return parts.length > 0 ? parts.join(' · ') : undefined
}

// The message the Start and Edit first buttons hand Claude for an issue. `tasks`: Start made a task for each open box.
// `copied`: the board's copy of the issue goes with the message, carrying its body and boxes, so the message only names
// it. Without one it lists the boxes: with copies off, in the message Start submits, which the board's own
// prompt.submit hook doesn't see, and in a worker's prompt, which goes to the agent alone.
export const startPrompt = (issue: Issue, tasks = false, copied = false): string => {
  const open = issue.checks.filter(check => !check.done)
  if (copied) {
    const each = tasks && open.length > 0 ? ' Each of its open acceptance boxes is a task in your task list: mark it completed when it is done.' : ''
    return `Let's start on #${issue.number}: ${issue.title}. The board's copy of it is attached.${each}`
  }
  const listed = tasks ? '\n\nEach is a task in your task list too: mark it completed when it is done.' : ''
  const boxes = open.length > 0 ? `\n\nIts open acceptance boxes:\n${open.map(check => `- ${check.text}`).join('\n')}${listed}` : ''
  return `Let's start on #${issue.number}: ${issue.title}. Read it with \`gh issue view ${issue.number}\` first.${boxes}`
}

// Whether a prompt still names the issue: an Edit-first message the person rewrote may no longer be about it.
export const namesIssue = (text: string, number: number): boolean => mentionsOf(text, Infinity).includes(number)

const WEEK_MS = 7 * 24 * 60 * 60 * 1000
export const WEEKS = 12

// The day `weeks` weeks before `now`, as GitHub's search reads a date.
export const since = (now: number, weeks = WEEKS): string => new Date(now - weeks * WEEK_MS).toISOString().slice(0, 10)

// How many of the times fall in each of the last `weeks` weeks, oldest first.
export const weekly = (times: string[], now: number, weeks = WEEKS): number[] => {
  const counts = Array.from({ length: weeks }, () => 0)
  for (const iso of times) {
    const back = Math.floor((now - Date.parse(iso)) / WEEK_MS)
    if (back >= 0 && back < weeks) counts[weeks - 1 - back] = (counts[weeks - 1 - back] ?? 0) + 1
  }
  return counts
}

// The times under `field` in gh's JSON list, such as each issue's closedAt.
export const timesOf = (json: string, field: string): string[] =>
  (JSON.parse(json) as Record<string, unknown>[]).flatMap(raw => (typeof raw[field] === 'string' ? [raw[field] as string] : []))

const BLOCKS = '▁▂▃▄▅▆▇█'

// One block a week, as tall as that week against the busiest.
export const spark = (counts: number[]): string => {
  const top = Math.max(0, ...counts)
  return counts.map(count => (top === 0 ? BLOCKS[0] : BLOCKS[Math.round((count / top) * (BLOCKS.length - 1))])).join('')
}

// What the band above the prompt raises, minus what the person waved off: failing CI, CI that went green while the board
// watched, then the issue Claude is on.
export const alertsOf = (board: Board, working: Working | null, dismissed: string[], greened: string[] = []): Alert[] => {
  const alerts: Alert[] = [
    ...board.prs.filter(pr => pr.ci === 'fail').map(pr => ({ kind: 'ci' as const, key: `ci-${pr.number}-${pr.updatedAt}`, pr })),
    ...board.prs
      .filter(pr => pr.ci === 'pass' && greened.includes(greenKey(pr)))
      .map(pr => ({ kind: 'pass' as const, key: `pass-${greenKey(pr)}`, pr })),
  ]
  if (working) {
    const issue = board.issues.find(one => one.number === working.number)
    if (!issue) alerts.push({ kind: 'closed', key: `closed-${working.number}`, working })
    else if (issue.updatedAt > working.updatedAt) alerts.push({ kind: 'activity', key: `activity-${issue.number}-${issue.updatedAt}`, issue })
  }
  return alerts.filter(alert => !dismissed.includes(alert.key))
}

// How `greened` names one CI run of a pull request.
export const greenKey = (pr: PullRequest): string => `${pr.number}-${pr.sha}`

// The pull requests whose CI was running on the last board and passes on this one.
export const wentGreen = (before: Board | null, after: Board): PullRequest[] =>
  after.prs.filter(pr => pr.ci === 'pass' && before?.prs.some(old => old.number === pr.number && old.ci === 'pending'))

// The message the band's Fix button hands Claude for a pull request whose CI failed.
export const fixPrompt = (pr: PullRequest): string => {
  const names = pr.failing ?? []
  const runs = pr.runs ?? []
  const which = names.length > 0 ? ` The failing ${names.length === 1 ? 'check is' : 'checks are'} ${names.join(', ')}.` : ''
  const logs =
    runs.length > 0
      ? `Read the failure with ${runs.map(run => `\`gh run view ${run} --log-failed\``).join(' and ')}`
      : `Look at \`gh pr checks ${pr.number}\` and the failing run's log`
  return `CI is failing on PR #${pr.number}: ${pr.title} (branch \`${pr.branch}\`).${which} ${logs}, then fix it.`
}

const CLOSE_OUT_RULES =
  "Follow the repository's contributing guidelines, merge only once its required checks pass, and don't bypass branch protection or force-push. If it can't be merged, say what's blocking it."

// One pull request handed to Claude to see through: CI green, review answered, merged.
export const closeOutPrompt = (pr: PullRequest): string => {
  const draft = pr.isDraft ? ' It is a draft: finish it and mark it ready first.' : ''
  return (
    `Close out PR #${pr.number}: ${pr.title} (branch \`${pr.branch}\`). Read it with \`gh pr view ${pr.number}\` and \`gh pr checks ${pr.number}\`, ` +
    `fix any failing CI and answer any review on its branch, then merge it.${draft} ${CLOSE_OUT_RULES}`
  )
}

// Every open pull request, merged one at a time, oldest first, each brought up to date with what merged before it.
export const closeOutAllPrompt = (prs: PullRequest[]): string => {
  const list = [...prs]
    .sort((a, b) => a.number - b.number)
    .map(pr => `- #${pr.number}: ${pr.title} (\`${pr.branch}\`, CI ${pr.ci}${pr.isDraft ? ', draft' : ''})`)
    .join('\n')
  return (
    `Merge all ${prs.length} open pull ${prs.length === 1 ? 'request' : 'requests'}:\n${list}\n\n` +
    'Take them one at a time, oldest first. For each, read it with `gh pr view` and `gh pr checks`, fix any failing CI and answer any review, ' +
    'bring its branch up to date with what merged before it, and merge it once its checks pass. Finish a draft and mark it ready first. ' +
    `${CLOSE_OUT_RULES} Then move on to the next, and end with which merged and which didn't.`
  )
}

// The body with the task-list boxes at `boxes` (counted from 1, in the body's order) set to `done`; `changed` the boxes
// that flipped, `missing` the numbers past the last box.
export const tickBody = (body: string, boxes: number[], done: boolean): { body: string; changed: number[]; missing: number[] } => {
  const changed: number[] = []
  let seen = 0
  // Split on \n alone and match without a trailing \r, so a body the web editor saved with \r\n keeps its line endings.
  const lines = body.split('\n').map(line => {
    const match = BOX.exec(line.endsWith('\r') ? line.slice(0, -1) : line)
    if (!match) return line
    seen += 1
    if (!boxes.includes(seen) || (match[1] !== ' ') === done) return line
    changed.push(seen)
    return line.replace(/\[[ xX]\]/, done ? '[x]' : '[ ]')
  })
  return { body: lines.join('\n'), changed, missing: boxes.filter(box => box < 1 || box > seen) }
}

// Adds boxes to a body's acceptance list, after its last box, or under a new `## Acceptance` heading at the end when it
// has none. The rest stays as written, \r\n endings included.
export const addBoxes = (body: string, texts: string[]): string => {
  const crlf = body.includes('\r\n')
  const eol = crlf ? '\r\n' : '\n'
  const lines = body.split('\n')
  const last = lines.findLastIndex(line => BOX.test(line.endsWith('\r') ? line.slice(0, -1) : line))
  const boxes = texts.map(text => `- [ ] ${text.trim()}`)
  if (last >= 0) {
    // Each new box takes the line ending of the box before it.
    const ending = lines[last]?.endsWith('\r') ? '\r' : ''
    lines.splice(last + 1, 0, ...boxes.map(box => `${box}${ending}`))
    return lines.join('\n')
  }
  const kept = body.replace(/\s+$/, '')
  return `${kept}${kept ? `${eol}${eol}` : ''}## Acceptance${eol}${boxes.join(eol)}${eol}`
}

// Rewords boxes by number, counted as the tick tool counts them, keeping whether each is ticked. Answers the body and
// the numbers it has no box for.
export const rewordBoxes = (body: string, edits: { box: number; text: string }[]): { body: string; missing: number[] } => {
  let seen = 0
  const lines = body.split('\n').map(line => {
    const end = line.endsWith('\r') ? '\r' : ''
    const bare = end ? line.slice(0, -1) : line
    if (!BOX.test(bare)) return line
    seen += 1
    const edit = edits.find(one => one.box === seen)
    return edit ? `${bare.replace(/(\[[ xX]\]\s+).*$/, `$1${edit.text.trim()}`)}${end}` : line
  })
  return { body: lines.join('\n'), missing: edits.map(one => one.box).filter(box => box < 1 || box > seen) }
}

// What the board knows of one issue, a fact a line, its boxes numbered as the tick tool counts them.
const issueLines = (issue: Issue): string[] => {
  const step = progress(issue.checks)
  return [
    `#${issue.number} ${issue.title}`,
    issue.url,
    `Labels: ${issue.labels.map(label => label.name).join(', ') || 'none'}`,
    `Assignees: ${issue.assignees.join(', ') || 'none'}`,
    issue.status || issue.priority ? `Status: ${issue.status ?? 'none'}. Priority: ${issue.priority ?? 'none'}.` : '',
    issue.milestone ? `Milestone: ${issue.milestone}` : '',
    issue.type ? `Type: ${issue.type}` : '',
    issue.parent ? `Sub-issue of #${issue.parent.number}: ${issue.parent.title}` : '',
    (issue.subIssues?.total ?? 0) > 0 ? `Sub-issues: ${issue.subIssues?.completed}/${issue.subIssues?.total} closed` : '',
    (issue.blockedBy ?? []).length > 0 ? `Blocked by: ${issue.blockedBy?.map(number => `#${number}`).join(', ')}` : '',
    `Updated: ${issue.updatedAt}`,
    step.total > 0 ? `Boxes (${step.done}/${step.total} ticked):` : 'Boxes: none',
    ...issue.checks.map((check, index) => `${index + 1}. [${check.done ? 'x' : ' '}] ${check.text}`),
  ].filter(line => line !== '')
}

// One issue as the issues tool answers it.
export const issueText = (issue: Issue): string =>
  [...issueLines(issue), `This is the board's copy, without the body's other text. Read the whole issue with \`gh issue view ${issue.number}\`.`].join('\n')

// Issues as GitHub's REST answers them, a list or search results; pull requests, which the same endpoints mix in, left out.
export const foundOf = (items: unknown[]): Found[] =>
  (items as {
    number: number
    title: string
    html_url?: string
    state: string
    state_reason?: string | null
    closed_at?: string | null
    labels?: ({ name?: string } | string)[]
    pull_request?: unknown
  }[])
    .filter(raw => !raw.pull_request)
    .map(raw => ({
      number: raw.number,
      title: raw.title,
      url: raw.html_url ?? '',
      state: raw.state === 'closed' ? 'closed' : 'open',
      reason: raw.state_reason ?? null,
      closedAt: raw.closed_at ?? null,
      labels: (raw.labels ?? []).map(label => (typeof label === 'string' ? label : (label.name ?? ''))).filter(Boolean),
    }))

// How an issue stands, in a few words: open, or closed, how and when.
export const standing = (found: Found, now: number): string => {
  if (found.state === 'open') return 'open'
  const when = found.closedAt ? agoText(found.closedAt, now) : ''
  return `closed${found.reason ? ` as ${found.reason.replace('_', ' ')}` : ''}${when ? ` ${when}` : ''}`
}

// One line a found issue, as the issues tool lists it.
export const foundLine = (found: Found, now: number): string =>
  `#${found.number} ${found.title} · ${standing(found, now)}${found.labels.length > 0 ? ` · ${found.labels.join(', ')}` : ''}`

// GitHub's search terms for the repo's issues: a state, words, and a label, assignee or milestone.
export const searchTerms = (repo: string, ask: { state?: string; search?: string; label?: string; assignee?: string; milestone?: string }): string => {
  const quoted = (value: string) => (/\s/.test(value) ? `"${value}"` : value)
  return [
    `repo:${repo}`,
    'is:issue',
    ask.state === 'open' || ask.state === 'closed' ? `state:${ask.state}` : '',
    ask.label ? `label:${quoted(ask.label)}` : '',
    ask.assignee ? `assignee:${ask.assignee}` : '',
    ask.milestone ? `milestone:${quoted(ask.milestone)}` : '',
    ask.search?.trim() ?? '',
  ]
    .filter(Boolean)
    .join(' ')
}

// One pull request as the issues tool answers it.
export const prText = (pr: PullRequest): string => {
  const review = reviewBadge(pr)
  const parts = [`branch ${pr.branch}`, `CI ${pr.ci}`, ...(review ? [review.text.replace(/^[●○] /, '')] : []), `+${pr.additions} −${pr.deletions}`]
  const failing = pr.ci === 'fail' && (pr.failing ?? []).length > 0 ? ` Failing: ${pr.failing.join(', ')}.` : ''
  return `#${pr.number} ${pr.title} [${parts.join(', ')}]${failing}`
}

const LISTED = 150

// The issues tool's list: the board's issues under the filter and the narrowing asked for, in the pane's order, and
// the words that name the filter for Claude. A project groups them by Status, else by area.
export const toolListOf = (
  issues: Issue[],
  ask: { filter?: BuiltInFilter; area?: string; query?: string; label?: string; assignee?: string; milestone?: string },
  viewer: string | null,
  project: Project | null,
  markers: Markers,
): { issues: Issue[]; label: string } => {
  const chosen = ask.filter ?? 'all'
  const area = ask.area?.replace(/^area:/, '')
  const kept = groupsOf(
    issues.filter(
      issue =>
        matches(chosen, issue, viewer, project, markers) &&
        (!area || areaOf(issue) === area) &&
        (!ask.query || searched(ask.query, issue)) &&
        (!ask.label || issue.labels.some(label => label.name.toLowerCase() === ask.label?.toLowerCase())) &&
        (!ask.assignee || issue.assignees.includes(ask.assignee.replace(/^@/, ''))) &&
        (!ask.milestone || issue.milestone?.toLowerCase() === ask.milestone.toLowerCase()),
    ),
    project ? 'status' : 'area',
    project,
    null,
    markers,
  ).flatMap(group => group.issues)
  const label =
    project && (chosen === 'active' || chosen === 'future')
      ? `${chosen === 'active' ? 'now' : 'later'}: ${nowNames(project)[chosen === 'active' ? 'now' : 'later'].join(' and ') || 'none'}`
      : chosen === 'inbox'
        ? `inbox: Status ${roleOf(project, 'inbox')?.name ?? 'Inbox'} or none`
        : chosen
  return { issues: kept, label }
}

// The board as the issues tool answers it: its pull requests, then the issues the filter keeps, one line each.
export const boardText = (board: Board, issues: Issue[], label: string, clock: number): string => {
  const line = (issue: Issue) => {
    const step = progress(issue.checks)
    const labels = issue.labels.map(one => one.name).join(', ')
    const planned = [issue.status, issue.priority].filter(Boolean).join(' ')
    const parts = [planned, labels, step.total > 0 ? `${step.done}/${step.total} boxes` : ''].filter(Boolean)
    return `#${issue.number} ${issue.title}${parts.length > 0 ? ` [${parts.join('; ')}]` : ''}`
  }
  const listed = issues.slice(0, LISTED)
  return [
    `${board.repo}: ${board.issues.length} open issues, ${board.prs.length} open pull requests (synced ${agoText(board.fetchedAt, clock)}).`,
    '',
    'Pull requests:',
    ...(board.prs.length > 0 ? board.prs.map(prText) : ['none']),
    '',
    `Issues (${label}, ${issues.length}):`,
    ...(listed.length > 0 ? listed.map(line) : ['none']),
    ...(issues.length > listed.length ? [`…and ${issues.length - listed.length} more; narrow with filter, area or query.`] : []),
  ].join('\n')
}

// The PR rule's sentences for an issue: `Closes` only when every box is ticked, else `Refs`. None with the rule off,
// which leaves it to the repository's own rules.
const prRuleText = (number: number, closesWhenTicked: boolean): string[] =>
  closesWhenTicked
    ? [
        `When you open a pull request for #${number}, write \`Closes #${number}\` in its body only if every acceptance box of #${number} is ticked by then.`,
        `Otherwise write \`Refs #${number}\`, so the issue stays open for what is left. If the repository's contributing guidelines say otherwise, follow them.`,
      ]
    : []

// The system prompt's section while Claude works on an issue the person started this session. It names the issue and
// nothing that changes as the work goes on, so the prompt cache holds until the person starts another. `Closes` only
// when the pull request finishes the issue: some repos keep an issue open for verification, and say `Refs` until then.
export const workingSection = (working: Working, closesWhenTicked: boolean): string =>
  [
    `The person is working on GitHub issue #${working.number}: ${working.title}. They handed it to you from the issue board.`,
    `When you finish and check an acceptance box of #${working.number}, tick it with the mcp__issue-board__tick tool.`,
    `Change it with the mcp__issue-board__issue_update tool; moving its Status needs no permission.`,
    ...prRuleText(working.number, closesWhenTicked),
  ].join(' ')

// What Claude does when a background agent it handed an issue to ends, in `background` start mode. It follows the
// person's own rules on merging, since some want to merge by hand.
const reviewText =
  "When a worker ends, review its pull request, run the repository's tests and checks on its branch, and watch its CI. Then merge it, if the person's rules let you merge, or tell the person what is left."

// The system prompt's section in `background` start mode: Claude orchestrates. It hands issues to the board's agent and
// keeps the main context small, doing only small changes itself. It never changes, so the prompt cache holds.
export const orchestratorSection = (): string =>
  [
    'The person wants you to work as an orchestrator. Hand each GitHub issue of this repository to a background worker instead of working on it here.',
    `Dispatch one with the Agent tool, subagent_type \`${WORKER}\`, a description that starts with the issue's #number, and a prompt that starts on the issue.`,
    'Do only small changes yourself, such as a one-line fix or a typo in the docs.',
    reviewText,
  ].join(' ')

// What `/issues new` asks Claude for, over the conversation so far, to capture to the Inbox. With `epic`, a parent issue
// and its sub-issues.
export const draftPrompt = (what: string, labels: string[], epic = false): string =>
  [
    epic
      ? `Draft an epic for this repository${what ? ` about: ${what}` : ' from what we have discussed'}: a parent GitHub issue and the sub-issues that, closed, finish it.`
      : `Draft a GitHub issue for this repository${what ? ` about: ${what}` : ' from what we have discussed'}.`,
    epic
      ? 'Answer with one JSON object and nothing else: {"title": "...", "body": "...", "labels": ["..."], "children": [{"title": "...", "body": "...", "labels": ["..."]}]}.'
      : 'Answer with one JSON object and nothing else: {"title": "...", "body": "...", "labels": ["..."]}.',
    'Write each title as a short, plain sentence. In each body, say what is wrong or wanted and why, in plain sentences.',
    epic
      ? 'The parent body says what the whole is for and the order to do the parts in. Each sub-issue is one piece of work, and its body ends with a "## Acceptance" section of task-list boxes ("- [ ] ..."), one checkable outcome each.'
      : 'End the body with a "## Acceptance" section of task-list boxes ("- [ ] ..."), one checkable outcome each.',
    labels.length > 0 ? `Choose labels only from this list, or none: ${labels.join(', ')}.` : 'Leave labels empty.',
  ].join(' ')

type RawDraft = { title?: unknown; body?: unknown; labels?: unknown }

// One issue of a draft, its labels kept to the ones the repository has; null when it has no title or body.
const draftOf = (raw: RawDraft, labels: string[]): NewIssue | null => {
  if (typeof raw.title !== 'string' || raw.title.trim() === '' || typeof raw.body !== 'string') return null
  const picked = Array.isArray(raw.labels) ? raw.labels.filter((one): one is string => typeof one === 'string' && labels.includes(one)) : []
  return { title: raw.title.trim(), body: raw.body.trim(), labels: [...new Set(picked)] }
}

// The draft in Claude's reply as an issue to capture; null when the reply holds none. An epic's sub-issues come as
// `children` in the reply and go to `subIssues`.
export const parseDraft = (text: string, labels: string[]): NewIssue | null => {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  try {
    const raw = JSON.parse(text.slice(start, end + 1)) as RawDraft & { children?: unknown }
    const parent = draftOf(raw, labels)
    if (!parent) return null
    const children = Array.isArray(raw.children) ? raw.children.flatMap(child => (child && typeof child === 'object' ? [draftOf(child as RawDraft, labels)] : [])).filter(one => one !== null) : []
    return children.length > 0 ? { ...parent, subIssues: children } : parent
  } catch {
    return null
  }
}

// Every label the board's issues carry, sorted: the ones a draft may use.
export const labelsOf = (issues: Issue[]): string[] => [...new Set(issues.flatMap(issue => issue.labels.map(label => label.name)))].sort()

// The system prompt's capture section. Its text never changes, so the prompt cache holds it.
export const captureSection = (): string =>
  'When you find work that will not be done in this turn, such as a follow-up, a bug noticed in passing or an idea, ' +
  "file it with the issue board's capture tool instead of listing it in your answer. Skip trivia."

// Words that say little about what an issue is, left out when titles are compared.
const SMALL_WORDS = new Set(['a', 'an', 'and', 'as', 'at', 'be', 'by', 'for', 'from', 'in', 'into', 'is', 'it', 'its', 'of', 'on', 'or', 'so', 'the', 'to', 'when', 'with'])

// A title's words for comparing: lower case, without punctuation or small words, and a plural's s dropped.
export const titleWords = (title: string): Set<string> =>
  new Set(
    title
      .toLowerCase()
      .split(/[^\p{L}\p{N}]+/u)
      .filter(word => word !== '' && !SMALL_WORDS.has(word))
      .map(word => (word.length > 3 && word.endsWith('s') && !word.endsWith('ss') ? word.slice(0, -1) : word)),
  )

// How alike two titles are, from 0 to 1: the words they share, against the words of both.
export const titleLikeness = (a: string, b: string): number => {
  const one = titleWords(a)
  const two = titleWords(b)
  if (one.size === 0 || two.size === 0) return 0
  const shared = [...one].filter(word => two.has(word)).length
  return (2 * shared) / (one.size + two.size)
}

// How alike a title must be to another for a capture to count as the same work.
export const SAME_WORK = 0.7

// The issue among `candidates` most like `title`, when it is alike enough to be the same work; null otherwise.
export const sameWorkOf = <T extends { title: string }>(title: string, candidates: T[]): T | null => {
  let best: T | null = null
  let score = SAME_WORK
  for (const one of candidates) {
    const like = titleLikeness(title, one.title)
    if (like >= score) {
      best = one
      score = like
    }
  }
  return best
}

// Whether a view's filter keeps just the Inbox: Status at the Inbox option, or no Status, and nothing narrower save
// `is:open` or `is:issue`.
export const isInboxFilter = (filter: string, project: Project | null | undefined): boolean => {
  const inbox = roleOf(project, 'inbox')?.name
  const terms = parseFilter(filter)
  const inboxTerm = (term: FilterTerm) =>
    !term.negate &&
    term.key !== null &&
    ((same(term.key, 'status') && inbox !== undefined && term.values.length > 0 && term.values.every(value => same(value, inbox))) ||
      (same(term.key, 'no') && term.values.length === 1 && same(term.values[0] ?? '', 'status')))
  const harmless = (term: FilterTerm) => !term.negate && term.key !== null && same(term.key, 'is') && term.values.every(value => ['open', 'issue'].includes(value.toLowerCase()))
  return terms.some(inboxTerm) && terms.every(term => inboxTerm(term) || harmless(term))
}

// The pane's Inbox tab: the built-in one, or a project view whose filter is the Inbox; undefined when there is none.
export const inboxTabOf = (tabs: Tab[], project: Project | null | undefined): Tab | undefined =>
  tabs.find(tab => tab.id === 'inbox') ?? tabs.find(tab => tab.view !== undefined && isInboxFilter(tab.view.filter, project))

// A change to an issue, from its card or from Claude's issue_update tool. `parent` and `milestone` set as null remove
// them; `assign` and `unassign` take logins, or `@me` for the signed-in user.
export type IssueChanges = {
  status?: string
  priority?: string
  addLabels?: string[]
  removeLabels?: string[]
  assign?: string[]
  unassign?: string[]
  parent?: number | null
  milestone?: string | null
  comment?: string
  close?: 'completed' | 'not planned'
  reopen?: boolean
  // Blocked-by links to make and to take away, by the blocking issue's number.
  addBlockedBy?: number[]
  removeBlockedBy?: number[]
  // A new title; a whole new body; boxes to add to the acceptance list; boxes to reword, by number.
  title?: string
  body?: string
  addBoxes?: string[]
  rewordBoxes?: { box: number; text: string }[]
  // Close it as a duplicate of this issue, which GitHub then links.
  duplicateOf?: number
  // Its issue type, by name; null takes it off.
  type?: string | null
  // A place among its epic's sub-issues: just before or just after a sibling, by number.
  moveBefore?: number
  moveAfter?: number
  // A place in the project's own order: straight after this issue, by number, or at the top for 0.
  projectAfter?: number
  // Pinned to the top of the repo's issues, or not; its conversation locked, with GitHub's reason or none, or unlocked;
  // and the repo it moves to, `owner/name`, the same owner's.
  pin?: boolean
  lock?: boolean | 'off_topic' | 'resolved' | 'spam' | 'too_heated'
  transferTo?: string
  // Moves it even where GitHub won't move it back, from a public repo to a private one.
  confirmTransfer?: boolean
  // The project's other fields to set, by name; null clears one.
  fields?: Record<string, string | number | null>
}

const listed = (values: string[] | undefined): string => (values ?? []).filter(Boolean).join(',')

// The gh commands a change takes, in order: the edit, then the comment, then the close or reopen, so a comment made
// with a close lands before it. Status and Priority are the project's, set apart from these. `repo` is where the
// comment is posted.
export const commandsOf = (number: number, changes: IssueChanges, repo = ''): { argv: string[]; stdin?: string }[] => {
  const id = String(number)
  const edit = [
    ...(listed(changes.addLabels) ? ['--add-label', listed(changes.addLabels)] : []),
    ...(listed(changes.removeLabels) ? ['--remove-label', listed(changes.removeLabels)] : []),
    ...(listed(changes.assign) ? ['--add-assignee', listed(changes.assign)] : []),
    ...(listed(changes.unassign) ? ['--remove-assignee', listed(changes.unassign)] : []),
    ...(changes.parent === null ? ['--remove-parent'] : changes.parent !== undefined ? ['--parent', String(changes.parent)] : []),
    ...(changes.milestone === null ? ['--remove-milestone'] : changes.milestone !== undefined ? ['--milestone', changes.milestone] : []),
  ]
  return [
    ...(edit.length > 0 ? [{ argv: ['issue', 'edit', id, ...edit] }] : []),
    ...(changes.comment?.trim() ? [commentCommand(repo, number, changes.comment.trim())] : []),
    ...(changes.close ? [{ argv: ['issue', 'close', id, '--reason', changes.close] }] : []),
    ...(changes.reopen && !changes.close ? [{ argv: ['issue', 'reopen', id] }] : []),
    ...(changes.pin === true ? [{ argv: ['issue', 'pin', id] }] : changes.pin === false ? [{ argv: ['issue', 'unpin', id] }] : []),
    ...(changes.lock === false
      ? [{ argv: ['issue', 'unlock', id] }]
      : changes.lock
        ? [{ argv: ['issue', 'lock', id, ...(typeof changes.lock === 'string' ? ['--reason', changes.lock] : [])] }]
        : []),
    // Last: once moved, the issue is no longer this repo's.
    ...(changes.transferTo ? [{ argv: ['issue', 'transfer', id, changes.transferTo] }] : []),
  ]
}

// What a change did, in a sentence each, for a toast and for Claude.
export const changesText = (number: number, changes: IssueChanges): string => {
  const said = [
    changes.status ? `moved to ${changes.status}` : '',
    changes.priority ? `set to ${changes.priority}` : '',
    listed(changes.addLabels) ? `labelled ${listed(changes.addLabels).replace(/,/g, ', ')}` : '',
    listed(changes.removeLabels) ? `unlabelled ${listed(changes.removeLabels).replace(/,/g, ', ')}` : '',
    listed(changes.assign) ? `assigned ${listed(changes.assign).replace(/,/g, ', ')}` : '',
    listed(changes.unassign) ? `unassigned ${listed(changes.unassign).replace(/,/g, ', ')}` : '',
    changes.parent === null ? 'taken out of its epic' : changes.parent !== undefined ? `put under #${changes.parent}` : '',
    changes.title ? `retitled “${changes.title}”` : '',
    changes.body !== undefined ? 'its body rewritten' : '',
    changes.rewordBoxes?.length ? `${changes.rewordBoxes.length === 1 ? 'box' : 'boxes'} ${changes.rewordBoxes.map(one => one.box).join(', ')} reworded` : '',
    changes.addBoxes?.length ? `${changes.addBoxes.length} ${changes.addBoxes.length === 1 ? 'box' : 'boxes'} added` : '',
    changes.addBlockedBy?.length ? `blocked by ${changes.addBlockedBy.map(one => `#${one}`).join(', ')}` : '',
    changes.removeBlockedBy?.length ? `no longer blocked by ${changes.removeBlockedBy.map(one => `#${one}`).join(', ')}` : '',
    changes.milestone === null ? 'taken off its milestone' : changes.milestone !== undefined ? `put on the milestone ${changes.milestone}` : '',
    changes.comment?.trim() ? 'commented on' : '',
    changes.close ? `closed as ${changes.close}` : '',
    changes.duplicateOf ? `closed as a duplicate of #${changes.duplicateOf}` : '',
    changes.type === null ? 'its type taken off' : changes.type ? `typed ${changes.type}` : '',
    changes.moveBefore ? `moved before #${changes.moveBefore}` : changes.moveAfter ? `moved after #${changes.moveAfter}` : '',
    changes.projectAfter === 0 ? "moved to the top of the project's order" : changes.projectAfter ? `moved after #${changes.projectAfter} in the project's order` : '',
    changes.pin === true ? 'pinned' : changes.pin === false ? 'unpinned' : '',
    changes.lock === false ? 'unlocked' : changes.lock ? `locked${typeof changes.lock === 'string' ? ` as ${changes.lock.replace('_', ' ')}` : ''}` : '',
    changes.transferTo ? `moved to ${changes.transferTo}` : '',
    ...Object.entries(changes.fields ?? {}).map(([name, value]) => (value === null ? `${name} cleared` : `${name} set to ${value}`)),
    changes.reopen && !changes.close ? 'reopened' : '',
  ].filter(Boolean)
  return said.length > 0 ? `#${number} ${said.join(', ')}.` : `Nothing to change on #${number}.`
}

// The issues that left the board between two reads and may need moving to Done: each had an item in the project and
// wasn't at Done yet. Whether it closed as completed is GitHub's to say. None when the project has no Done option.
export const leftForDone = (before: Board | null, next: Board): { number: number; item: string }[] => {
  const done = roleOf(next.project, 'done')
  if (!before || !done) return []
  const still = new Set(next.issues.map(one => one.number))
  return before.issues.flatMap(one => (one.item && !still.has(one.number) && one.status !== done.name ? [{ number: one.number, item: one.item }] : []))
}

// The issues that pull requests which left the board between two reads refer to, and that may need moving to
// Verification: each still open (an issue a merge closed has left the board too), with an item in the project, and not
// at Verification or Done yet. Whether the pull request merged is GitHub's to say.
export const leftForVerification = (before: Board | null, next: Board): { pr: number; number: number; item: string }[] => {
  const verify = roleOf(next.project, 'verification')
  if (!before || !verify) return []
  const still = new Set(next.prs.map(pr => pr.number))
  return before.prs
    .filter(pr => !still.has(pr.number))
    .flatMap(pr =>
      (pr.issues ?? []).flatMap(number => {
        const issue = next.issues.find(one => one.number === number)
        return issue?.item && issue.status !== verify.name && !isRole(next.project, issue.status, 'done') ? [{ pr: pr.number, number, item: issue.item }] : []
      }),
    )
}

// The box an epic's last sub-issue closing ticks. Every epic is filed with it, so its acceptance says the parts are done.
export const SUB_ISSUES_BOX = 'Every sub-issue is closed'
const SUB_ISSUES = /^every sub-issue is closed\b/i

// The number of an epic's "Every sub-issue is closed" box, counted from 1 as the tick tool counts; 0 when it has none.
export const subIssuesBoxOf = (checks: Check[]): number => checks.findIndex(check => SUB_ISSUES.test(check.text)) + 1

// An epic's body with the "Every sub-issue is closed" box, added to its acceptance list when it hasn't one.
export const withSubIssuesBox = (body: string): string => (subIssuesBoxOf(checksOf(body)) > 0 ? body : addBoxes(body, [SUB_ISSUES_BOX]))

// Where Start leaves an issue's epic: the epic to move to In progress, when the issue is a sub-issue of an open epic on
// the board that is still in the Inbox, Backlog or Ready, or has no Status yet. An epic further along stays.
export const epicToStart = (issues: Issue[], issue: Issue, project: Project | null | undefined): Issue | undefined => {
  const epic = issue.parent ? issues.find(one => one.number === issue.parent?.number) : undefined
  if (!epic || !project?.status || !roleOf(project, 'started')) return undefined
  const waiting = !epic.status || (['inbox', 'backlog', 'ready'] as const).some(role => isRole(project, epic.status, role))
  return waiting ? epic : undefined
}

// What changed for epics between two reads. `finished`: open epics whose last open sub-issue closed. `reopened`: a
// sub-issue back on the board under an open epic whose closed count dropped. `orphaned`: a sub-issue new to the board
// whose epic is closed, reopened or filed under it.
export type EpicChanges = { finished: number[]; reopened: { number: number; epic: number }[]; orphaned: { number: number; epic: number }[] }
export const epicChanges = (before: Board | null, next: Board): EpicChanges => {
  const changes: EpicChanges = { finished: [], reopened: [], orphaned: [] }
  if (!before) return changes
  const was = new Map(before.issues.map(one => [one.number, one]))
  const open = new Set(next.issues.map(one => one.number))
  for (const epic of next.issues) {
    const now = epic.subIssues
    const then = was.get(epic.number)?.subIssues
    if (!now || !then || now.total === 0) continue
    if (then.completed < then.total && now.completed === now.total) changes.finished.push(epic.number)
  }
  for (const issue of next.issues) {
    const epic = issue.parent?.number
    if (!epic || was.has(issue.number)) continue
    if (!open.has(epic)) {
      changes.orphaned.push({ number: issue.number, epic })
      continue
    }
    const then = was.get(epic)?.subIssues
    const now = next.issues.find(one => one.number === epic)?.subIssues
    if (then && now && now.completed < then.completed) changes.reopened.push({ number: issue.number, epic })
  }
  return changes
}

// How long an epic line may stay in the band, whatever else holds: a backstop for a line nothing else clears.
export const EPIC_NOTE_MS = 24 * 60 * 60 * 1000

// The epic lines that still apply on this read of the board, which holds only open issues. A Verification line goes
// once its epic closes or every box is ticked. A reopened line goes once the sub-issue closes or leaves the epic, or the
// epic closes. An orphaned line goes once the sub-issue closes or leaves the epic, or the epic reopens. Any line goes
// after a day.
export const liveEpicNotes = (notes: EpicNote[], board: Board, now: number): EpicNote[] => {
  const open = new Map(board.issues.map(one => [one.number, one]))
  return notes.filter(note => {
    if (now - note.at >= EPIC_NOTE_MS) return false
    const epic = open.get(note.epic)
    if (note.kind === 'verify') return !!epic && epic.checks.some(check => !check.done)
    const sub = note.number === undefined ? undefined : open.get(note.number)
    if (!sub || sub.parent?.number !== note.epic) return false
    return note.kind === 'reopened' ? !!epic : !epic
  })
}

// Where GitHub's REST API keeps a project, from the project's page: `users/<login>/projectsV2/<n>` or the `orgs/` one.
export const projectPathOf = (url: string): string | null => {
  const found = /github\.com\/(users|orgs)\/([^/]+)\/projects\/(\d+)/.exec(url)
  return found ? `${found[1]}/${found[2]}/projectsV2/${found[3]}` : null
}

// The project's issues at a Status, open or closed, from its items as REST answers them with the Status field; a closed
// one only when it closed on or after `since`, a date.
export const itemsAt = (items: unknown[], status: string, since?: string): Found[] =>
  (items as { content_type?: string; content?: Record<string, unknown> | null; fields?: { name?: string; value?: { name?: { raw?: string } | string } | null }[] }[])
    .filter(item => item.content_type === 'Issue' && item.content)
    .filter(item => {
      const value = item.fields?.find(field => field.name === 'Status')?.value?.name
      const name = typeof value === 'string' ? value : value?.raw
      return name?.toLowerCase() === status.toLowerCase()
    })
    .flatMap(item => foundOf([item.content]))
    .filter(found => !since || found.state === 'open' || (found.closedAt ?? '') >= since)

// The project's items an archive takes, as REST lists them with the Status field: one issue's, by number, or every issue
// at Done that closed before a date, `done` naming the project's Done option. Archived ones are left out.
export const toArchive = (items: unknown[], ask: { number?: number; doneBefore?: string }, done?: string): { number: number; title: string; node: string }[] =>
  (
    items as {
      node_id?: string
      archived_at?: string | null
      content_type?: string
      content?: { number?: number; title?: string; state?: string; closed_at?: string | null } | null
      fields?: { name?: string; value?: { name?: { raw?: string } | string } | null }[]
    }[]
  )
    .filter(item => item.content_type === 'Issue' && item.content && item.node_id && !item.archived_at)
    .filter(item => {
      if (ask.number !== undefined) return item.content?.number === ask.number
      const value = item.fields?.find(field => field.name === 'Status')?.value?.name
      const status = typeof value === 'string' ? value : value?.raw
      return done !== undefined && status === done && item.content?.state === 'closed' && (item.content.closed_at ?? '') < (ask.doneBefore ?? '')
    })
    .map(item => ({ number: item.content?.number ?? 0, title: item.content?.title ?? '', node: item.node_id ?? '' }))

// Milestones as GitHub's REST answers them.
export const milestonesOf = (items: unknown[]): Milestone[] =>
  (items as { number: number; title: string; due_on?: string | null; description?: string | null; open_issues?: number; closed_issues?: number }[]).map(raw => ({
    number: raw.number,
    title: raw.title,
    due: raw.due_on ? raw.due_on.slice(0, 10) : null,
    description: raw.description ?? '',
    open: raw.open_issues ?? 0,
    closed: raw.closed_issues ?? 0,
  }))

// One milestone in a line: how many of its issues are closed, and when it is due, or how long since it was.
export const milestoneLine = (milestone: Milestone, today: string): string =>
  `${milestone.title} · ${milestone.closed}/${milestone.open + milestone.closed} closed · ${milestoneDue(milestone, today).text}`

// When a milestone is due, as words, and whether it is late: past its date with issues still open. `today` is a
// YYYY-MM-DD date.
export const milestoneDue = (milestone: Milestone, today: string): { text: string; late: boolean } => {
  const late = milestone.due !== null && milestone.due < today && milestone.open > 0
  return { text: milestone.due ? (late ? `was due ${milestone.due}` : `due ${milestone.due}`) : 'no due date', late }
}

// An item's field values, by field name, from the ITEM_VALUES query: each as text, as the card and Claude read it.
export const itemValuesOf = (answer: unknown): Record<string, string> => {
  const nodes =
    (answer as { node?: { fieldValues?: { nodes?: ({ text?: string; number?: number; date?: string; title?: string; name?: string; field?: { name?: string } } | null)[] } } })?.node?.fieldValues
      ?.nodes ?? []
  return Object.fromEntries(
    nodes.flatMap(one => {
      const value = one?.text ?? (one?.number !== undefined ? String(one.number) : undefined) ?? one?.date ?? one?.title ?? one?.name
      return one?.field?.name && value !== undefined ? [[one.field.name, value]] : []
    }),
  )
}

// A value for a field, as GitHub's mutation takes it, from what Claude or the person gave; or why it doesn't fit.
export const fieldValueOf = (field: ProjectField, given: unknown): { value: Record<string, string | number> } | string => {
  const text = typeof given === 'number' ? String(given) : typeof given === 'string' ? given.trim() : ''
  if (!text) return `give ${field.name} a value, or null to clear it`
  switch (field.kind) {
    case 'text':
      return { value: { text } }
    case 'number':
      return Number.isFinite(Number(text)) ? { value: { number: Number(text) } } : `${field.name} takes a number, not ${text}`
    case 'date':
      return /^\d{4}-\d{2}-\d{2}$/.test(text) ? { value: { date: text } } : `${field.name} takes a date, YYYY-MM-DD, not ${text}`
    case 'iteration':
    case 'select': {
      const option = field.options?.find(one => one.name.toLowerCase() === text.toLowerCase())
      const names = (field.options ?? []).map(one => one.name).join(', ')
      if (!option) return `${field.name} has no ${field.kind === 'iteration' ? 'iteration' : 'option'} called ${text}${names ? `; it has ${names}` : ''}`
      return { value: field.kind === 'iteration' ? { iterationId: option.id } : { singleSelectOptionId: option.id } }
    }
  }
}

// An epic's order with one sub-issue moved just before or just after a sibling; one the order didn't list is added.
export const reordered = (order: number[], number: number, beside: number, before: boolean): number[] => {
  const rest = order.filter(one => one !== number)
  const at = rest.indexOf(beside)
  if (at < 0) return [...rest, number]
  return [...rest.slice(0, before ? at : at + 1), number, ...rest.slice(before ? at : at + 1)]
}

// A move in the project's own order: the issue's item, and the item it goes straight after, or null for the top of the
// project. GitHub only places an item after another, so before an issue is after the one above it among the issues the
// board holds in the project's order; before the first of those is the top. `beside` of null is the top too. A string
// says why it can't move.
export type ProjectMove = { item: string; after: { number: number; item: string } | null }
export const projectMoveOf = (issues: Issue[], number: number, beside: number | null, before: boolean): ProjectMove | string => {
  const issue = issues.find(one => one.number === number)
  if (!issue) return `#${number} isn't an open issue on the board`
  if (!issue.item) return `#${number} isn't in the project yet; set its Status first`
  if (beside === null) return { item: issue.item, after: null }
  if (beside === number) return `#${number} can't move beside itself`
  const ordered = issues.filter(one => one.position !== undefined && one.number !== number).sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
  const at = ordered.findIndex(one => one.number === beside)
  if (at < 0) return `#${beside} isn't an open issue the board has in the project's order`
  const after = before ? ordered[at - 1] : ordered[at]
  return { item: issue.item, after: after?.item ? { number: after.number, item: after.item } : null }
}

// The issues with one moved in the project's order straight after another, or to the top for null, and every place
// counted again from 0, so the pane shows the move before the next read confirms it.
export const placedAfter = (issues: Issue[], number: number, after: number | null): Issue[] => {
  const ordered = issues.filter(one => one.position !== undefined && one.number !== number).sort((a, b) => (a.position ?? 0) - (b.position ?? 0)).map(one => one.number)
  const at = after === null ? 0 : ordered.indexOf(after) + 1
  const order = [...ordered.slice(0, at), number, ...ordered.slice(at)]
  return issues.map(one => (order.includes(one.number) ? { ...one, position: order.indexOf(one.number) } : one))
}

// The labels asked for that the repo hasn't got, by name, ignoring case, each once.
export const missingLabels = (wanted: string[], existing: { name: string }[]): string[] => {
  const have = new Set(existing.map(one => one.name.toLowerCase()))
  return [...new Map(wanted.filter(name => !have.has(name.toLowerCase())).map(name => [name.toLowerCase(), name])).values()]
}

// The color a new label gets: an `area:` label takes the color the repo's other areas have, so they read as one set.
export const labelColorFor = (name: string, existing: { name: string; color?: string }[]): string =>
  (name.startsWith('area:') ? existing.find(one => one.name.startsWith('area:') && one.color)?.color : undefined) ?? 'ededed'

// A hint line that fits `width`: its parts in order of use. All of them in their long form when that fits; otherwise
// the short forms, such as `1-7 filter` for every filter key, and the last parts dropped until it fits, never wrapped.
export const hintFit = (parts: (string | [string, string])[], width: number, gap = ' · '): string => {
  const long = parts.map(part => (Array.isArray(part) ? part[0] : part))
  if (cells(long.join(gap)) <= width) return long.join(gap)
  const kept: string[] = []
  for (const part of parts.map(one => (Array.isArray(one) ? one[1] : one))) {
    if (cells([...kept, part].join(gap)) <= width) kept.push(part)
  }
  return kept.join(gap)
}

// The filter keys, all of them, such as `1 now · 2 later`, and in short, `1-7 filter`.
export const filterKeys = (filters: { hotkey: string; name: string }[]): [string, string] => {
  const keys = filters.map(one => one.hotkey)
  return [filters.map(one => `${one.hotkey} ${one.name.toLowerCase()}`).join(' · '), `${keys[0]}-${keys.at(-1)} filter`]
}

// What opening the pane says: the keys that matter most, from the board's own lists, and the subcommands.
export const openedText = (filters: { hotkey: string; name: string }[]): string =>
  [
    'Issues pane opened.',
    `Filters: ${filters.map(one => `${one.hotkey} ${one.name}`).join(', ')}.`,
    'Enter opens an issue: Start hands it to Claude, Change edits it, and Esc folds it. r refreshes.',
    'Also: /issues new [epic] captures an issue to the Inbox, /issues setup links a project, /issues check says what is missing. /issues help lists everything.',
  ].join(' ')

