              reason: { type: 'string' },
              create: { type: 'boolean' },
              delete: { type: 'boolean' },
              rename: { type: 'string' },
              color: { type: 'string' },
              description: { type: 'string' },
            },
            required: ['name', 'reason'],
          },
        },
        views: {
          type: 'array',
          description: 'view: a number or name; omit to create.',
          items: {
            type: 'object',
            properties: {
